pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap that cannot hold even the smallest plausible item (<=10)
    // is pure waste; gaps below ~20 are nearly worthless.
    if post_residual < 10 {
        score += 1000.0;
    } else if post_residual < 20 {
        score += 60.0 + (20 - post_residual) as f64 * 8.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits (waste-free packing).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // the current bin already fits well; encourage closing bins out.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement chains nicely; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Early in the stream, tolerate opening new bins slightly more;
    // later, be conservative and reuse existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: strong reward for chained fit
            let slack_after_next = post_residual - next_item_size;
            score -= 2.0 * next_item_size as f64;
            score += 0.5 * slack_after_next as f64;
        } else {
            // Next item won't fit: penalize leaving residual that's too small
            // but also penalize wasting too much space
            let waste = post_residual as f64;
            score += 0.3 * waste;
            if post_residual < 10 {
                score += 50.0; // tiny dead space, unusable
            }
        }
    } else {
        // Last item: just minimize post residual
        score += 0.0;
    }

    // Relative to mean residual: prefer bins that stay near the mean
    // (balanced packing) but slightly prefer tighter bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 150.0;
        // But if the item is large relative to typical residuals, allow new bin
        if item_size as f64 > mean_residual * 0.9 {
            score -= 200.0;
        }
        // Early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins where the next item fits the post residual
    if next_item_size > 0 {
        let lookahead_gap = post_residual as f64 - next_item_size as f64;
        if lookahead_gap >= 0.0 {
            // Next item fits exactly or near-exactly after this placement
            score -= 400.0 + 600.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize proportional to wasted gap
            score += 0.5 * (-lookahead_gap);
        }
        // Bonus if next item also fits this bin directly (chain potential)
        if next_item_size as f64 <= post_residual as f64 && item_size + next_item_size <= bin_residual {
            score -= 150.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" — prefer them
    let residual_f = bin_residual as f64;
    let tightness = (mean_residual - residual_f) / bin_capacity as f64;
    score -= 200.0 * tightness;

    // Penalize small unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Early in stream: mild preference for opening new bins to keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus early-stream discount
        score = 60.0 - 80.0 * (1.0 - progress) + (bin_capacity as f64 - post_residual as f64);
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fraction bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Dead space penalty: residuals that are too small to fit the smallest
    // plausible item are pure waste. Harmonic tiers at 1/10, 1/5, 1/3.
    if frac < 0.10 {
        score += 60.0; // nearly dead bin
    } else if frac < 0.20 {
        score += 25.0;
    } else if frac < (1.0 / 3.0) {
        score += 8.0;
    } else {
        score -= 5.0; // roomy leftover is good
    }

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize if it almost fits (teasing near-miss).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_f {
            score -= 18.0;
            // Harmonic bonus: exact modulo closure (next divides residual nicely)
            if (post_residual % next_item_size.max(1)) <= 5 {
                score -= 10.0;
            }
        } else if next - post_f <= 10.0 {
            score += 12.0; // near-miss: wasted lookahead opportunity
        }
    }

    // Integer-division threshold on post_residual: multiples of capacity/4
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual % quarter.max(1) == 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // relative to mean residual across open bins.
    if bin_residual == bin_capacity {
        score += 35.0;
        if (item_size as f64) > mean_residual {
            score -= 45.0; // item too big for typical open bin -> new bin is fine
        }
        // Late in stream, prefer consolidation less strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
    }

    // Mild pressure to keep number of open bins small when residuals are healthy.
    if mean_residual > 0.5 * cap_f && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to bin residual (high fill fraction).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer filling bins with larger residuals less
    // when the mean residual is already low (consolidate).
    if (post_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post residual is too small for the next item (dead space for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no
    // open bin offers a good fit (large dead space otherwise).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0 + open_bins_count as f64 * 0.5;
        // If the only fitting bin is this new one, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with a convex quadratic penalty
    let mut score = pr / cap;
    score += 0.35 * (pr / cap) * (pr / cap);

    // Smooth stream-progress coupling: as stream advances, tighten residual tolerance
    let tightness = 0.5 + 0.5 * progress;
    score += tightness * 0.4 * (pr / cap);

    // Interaction: post_residual * progress polynomial coupling
    score += 0.15 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space that no small item can use (post_residual < typical min size)
    let dead = ((20.0 - pr).max(0.0)) / 20.0;
    score += 0.5 * dead * dead;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - pr / cap;
    score -= 0.6 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 0.4 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.2 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.02 * open_bins_count as f64 / (1.0 + mean_residual / cap);

    // New-bin candidate handling: empty bin gets neutral-ish score unless current fits are poor
    if bin_residual == bin_capacity {
        score = 1.2 - 0.5 * fit_quality + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are dead; treat small gaps (< 10) as near-wasted with escalating penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward keeping residual usable for the known next item (lookahead k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual that can't fit the next item is likely dead space
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual spread / many bins) or this is a large item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score = 120.0 + pressure + 0.5 * fragmentation - 0.3 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 50.0; // never open new when a last-chance bin exists
        }
    }

    // Mild stream-progression tilt: later in stream, tighten packing more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
