pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack.min(200.0) * 0.5;
            // perfect chain fit
            if post_residual == next_item_size {
                score -= 400.0;
            }
        } else {
            // post residual too small for next item: penalize dead space
            let dead = post_residual as f64;
            score += dead * 1.5;
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Last chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize leaving large residuals relative to typical item range
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // Early in stream: keep bins flexible; late: consolidate tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * (post_residual as f64) * 0.3;

