            score -= if nr == 0 { 12.0 } else { 4.0 };
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Empty new-bin candidate: penalize unless current bins are crowded or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
