        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals that no item (min size 1, but typical >=10)
        // can ever fill are wasteful. Classify residual by harmonic class.
        let pr = post_residual;
        // Modulo classes on capacity: residuals in low bands are hard to fill
        let quarter = bin_capacity / 4; // 25
        let eighth = bin_capacity / 8;  // 12
        if pr < eighth {
            // Unusable sliver unless next item matches exactly
            if next_item_size != pr {
                score += 60.0 + (eighth - pr) as f64 * 2.0;
            } else {
                score -= 80.0; // next item seals the sliver perfectly
            }
        } else if pr < quarter {
            score += 15.0;
        }

        // Integer-division threshold: residual divisible into nice halves
        if pr % 2 == 0 {
            score -= 5.0;
        }
        if pr % 5 == 0 {
            score -= 5.0;
        }
        if pr % 10 == 0 {
            score -= 10.0; // residual aligns with decimal item sizes
        }

        // Lookahead coupling: if next item fits the post residual, big reward
        if next_item_size > 0 && next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 - slack * 0.5; // prefer next item filling snugly
            // Harmonic bonus: next item leaves residual in a good class
            let npr = pr - next_item_size;
            if npr == 0 { score -= 60.0; }
            else if npr % 10 == 0 { score -= 15.0; }
        } else if next_item_size > 0 && next_item_size > pr {
            // Next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Fraction of capacity filled by this item (harmonic fraction)
    let fill = item_size as f64 / cap;
    score -= fill * 30.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // existing bins; only attractive when existing residuals are large.
    if bin_residual == bin_capacity {
        // Empty-bin score: base cost of a fresh bin plus pressure terms
        score = cap * 0.75;
        if mean_residual < cap * 0.2 {
            // Existing bins are nearly full; new bin is reasonable
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item benefits from a fresh bin
        }
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 5.0; // discourage bin sprawl
        }
    } else {
        // Prefer bins whose residual is below mean (tighten tight bins first)
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
    }

    // Stream progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: gaps too small for the minimum item (1..=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0; // hard penalty: never create an unusable sliver unless forced
    }
    // Near-dead zone: gaps that only the smallest items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (perfect packing).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 50.0; // small but still usable gap is excellent
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; prefer new bin when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + progress);
    score += bin_pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it mildly unattractive by default, but attractive
    // if the item would leave a bad gap in every existing bin.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 120.0; // new bin keeps space aligned with the next item
        }
    }

    // Lookahead: if the post residual can exactly host the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 15.0; // gap barely fits next item but leaves nothing after
    }

    // Mean residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins with residuals above the mean (older, emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect chain fit: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: mildly reward closeness
            score -= 25.0 / (1.0 + match_gap / 20.0);
        } else {
            // next item won't fit: penalize dead space relative to gap
            score += 15.0 + match_gap * 0.4;
        }
    }

    // Compare post_residual against mean residual across open bins
    // Leaving less than average residual is good (compact packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Opening fresh is good only if item is large relative to capacity
        score += 30.0 + waste * 0.2;
        // If lookahead chains well in fresh bin, soften penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // Prefer fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Exact / near-exact fill bonus (dead space elimination).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Penalize creating awkward dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't chain here; penalize proportionally to wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a decent fit, or when open bins are nearly full anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin grows with stream length (bin economy).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress;

        // If plenty of bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64);
        }
        // If open bins are on average quite full, a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
        // Large items prefer fresh bins (avoid fragmenting them across bins).
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Mild bonus for keeping number of open bins low (consolidation pressure).
        score += 0.05 * open_bins_count as f64;
        // Prefer bins with residual close to mean (balanced packing).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: penalize post residual, with non-linear (quadratic) growth
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post residual) are worth more
    let coupling = (1.0 - 2.0 * progress + progress * progress) * 20.0
                 + (progress - progress * progress) * 60.0;
    score -= coupling * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward filling bins tightly, scaled by how much the item occupies the bin
    let fill_ratio = item / cap;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 55.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score += 0.35 * diff;
        if pr >= nxt {
            score -= 12.0 * (1.0 - diff / cap);
        }
    }

    // Mild penalty when bin deviates from mean residual (balance pressure)
    score += 0.05 * (pr - mean_residual).abs();

    // Prefer using existing bins over opening new ones, more so early on
    score += (1.0 - progress) * 8.0 * (open_bins_count as f64).sqrt();

    // Smooth penalty for very small dead space that is hard to reuse
    let small_waste = if pr > 0.0 { (1.0 - norm_pr.min(1.0)) * norm_pr * (1.0 - norm_pr) } else { 0.0 };
    score += 25.0 * small_waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Classes based on integer division thresholds (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill achieved by this placement (0..1).
    let fill = (bin_residual - post_residual) as f64 / cap;

    // Reward tight fits: post_residual in low harmonic class (0..=10 is "dead").
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else if post_residual <= 50 {
        score += 3.0;
    } else {
        score += 8.0;
    }

    // Modulo arithmetic: leftover divisible into common item sizes is reusable.
    // Item sizes 1..=100; typical harmonics: 10, 20, 25, 50.
    if post_residual > 0 {
        let reusables = [10u32, 20, 25, 33, 50];
        let mut reusable = false;
        for &r in &reusables {
            if post_residual % r == 0 || post_residual >= r && post_residual - r <= 10 {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here regardless; slight penalty for hoarding space.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this is a large item early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_gap = mean_residual - (item_size as f64);
        // Penalize new bin normally...
        score += 18.0;
        // ...but reward it when existing residuals are poor fits or stream is young.
        if mean_gap < 0.0 {
            score -= 30.0;
        }
        if progress < 0.35 && item_size >= 60 {
            score -= 12.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= fill * 8.0;

    // Tie-break: prefer bins with residual above mean (keeps balance).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap that cannot hold even the smallest plausible item (<=10)
    // is pure waste; gaps below ~20 are nearly worthless.
    if post_residual < 10 {
        score += 1000.0;
    } else if post_residual < 20 {
        score += 60.0 + (20 - post_residual) as f64 * 8.0;
    } else if post_residual < 30 {
        score += 10.0 + (30 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits (waste-free packing).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // the current bin already fits well; encourage closing bins out.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement chains nicely; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Early in the stream, tolerate opening new bins slightly more;
    // later, be conservative and reuse existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not too tight.
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward when the next item fits into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let slack = (post_residual as f64 - next).abs();
            // Perfect or near-perfect chain fit is heavily rewarded.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 25.0; // exact chain completion
            }
        } else {
            // Next item cannot follow: post_residual likely becomes dead space.
            let overshoot = next_item_size as f64 - post_residual as f64;
            // Penalize more when overshoot is small (wasted opportunity) but
            // also when post_residual is large enough to be tempting yet unusable.
            if overshoot < 20.0 {
                score += 15.0 + (20.0 - overshoot) * 1.5;
            }
        }
    }

    // Compare post_residual against mean residual: leaving a bin far below the
    // mean residual wastes capacity relative to the fleet average.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.4 * dev;
    } else {
        score += 0.2 * dev; // slight reward for below-average leftover
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Make the empty-bin candidate moderately
    // attractive by default but beatable by any reasonable existing bin.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75; // 75.0 baseline for a fresh bin
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference to fill bins that are already partially committed
    // (fewer open bins is better): penalize placements into emptier bins
    // relative to how many bins are open.
    score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0) / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space that next item cannot use: penalize proportionally to waste.
            score += 0.25 * (next_item_size - post_residual).min(item_size) as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Spread load when many bins fit: prefer bins with less residual than mean.
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins less tightly,
    // keeping flexibility); late in stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open bins pressure: many open bins -> favor consolidating into emptier bins.
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64 - 4.0) * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when current item is large relative to
    // capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 55.0;
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += 20.0 - large_item_bonus - desperation;
        // Late in stream, opening new bins is cheaper (less future waste risk).
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling: dead space becomes more costly as the stream progresses
    let norm_pr = pr / cap;
    let decay = 1.0 + 2.0 * progress * progress;
    score += decay * cap * norm_pr * norm_pr * norm_pr;

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins far below the mean residual (wasteful use of a fuller bin)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead: favor leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap;
        if next_item_size as f64 <= pr {
            score -= 4.0;
        }
    }

    // Mild pressure against accumulating too many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: discourage opening a new bin when decent fits exist,
    // but allow it late in the stream for large residual waste
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        if pr >= 50.0 {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let post_f = post_residual as f64;
    let class = (post_f / cap * 8.0).floor(); // 0..=7 harmonic classes of leftover

    // Reward tiny residuals strongly (perfect packing zones).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0 - post_f;
    } else if post_residual <= 25 {
        score -= 12.0;
    } else if post_residual <= 50 {
        score += 6.0;
    } else {
        score += 14.0; // large dead space is bad
    }

    // Modulo arithmetic: residuals divisible by common item sizes are re-usable.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 10.0; }
        else if r % 5 == 0 { score -= 5.0; }
        else if r % 3 == 0 { score -= 2.0; }
        else { score += 3.0; } // prime-ish residual is awkward
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 50.0;
        } else if next_item_size < r {
            let gap = (r - next_item_size) as f64;
            // harmonic class of the gap after the lookahead placement
            let gap_class = (gap / cap * 8.0).floor();
            score -= 20.0 - gap_class * 3.0;
            if gap % 10 == 0 { score -= 5.0; }
        } else {
            score += 8.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual across open bins.
    score -= (mean_residual - post_f) * 0.3;

    // Early stream: be more willing to open bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual as u32 == bin_capacity {
        // New-bin candidate: only attractive when current residuals are fragmented
        // or this is a big item late in the stream.
        score = post_f - 15.0 + progress * 10.0 - mean_residual * 0.2;
        if open_bins_count == 0 { score -= 25.0; }
    } else {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are dead; treat small gaps (< 10) as near-wasted with escalating penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward keeping residual usable for the known next item (lookahead k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual that can't fit the next item is likely dead space
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual spread / many bins) or this is a large item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score = 120.0 + pressure + 0.5 * fragmentation - 0.3 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 50.0; // never open new when a last-chance bin exists
        }
    }

    // Mild stream-progression tilt: later in stream, tighten packing more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual small relative to capacity.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fit_quality * fit_quality;

    // Aggressive 2-step lookahead: if the next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 30.0 * chain_tightness;
        // Extra reward for exact chain match (next item fills bin completely).
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space: penalize dead space.
        score += 15.0;
    }

    // Penalize leaving residual far from useful sizes relative to mean residual.
    let residual_dev = post_residual as f64 - mean_residual;
    score += 0.15 * residual_dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let waste_here = (bin_capacity - item_size) as f64;
        // Opening a new bin wastes capacity - item_size; only attractive if open bins leave worse waste.
        let open_bin_waste = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64
        } else {
            waste_here
        };
        score += 60.0 + waste_here;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can chain the next item
        }
        if open_bin_waste < waste_here {
            score -= 25.0;
        }
        // Late in stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference to fill bins with small residuals to close them out.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // Penalize dead space that can't hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 1.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.4 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many fitting bins: mild penalty to preserve flexibility for other bins.
    if fitting_bins_count > 2 {
        score += 1.2 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or when few open bins / early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score -= 10.0 * bad_fit;
        score += 18.0; // base cost of opening a new bin
        score -= 6.0 * (1.0 - progress); // cheaper to open bins early
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        if post_residual > 0 && post_residual < 10 {
            score += 8.0; // avoid leaving tiny unusable slivers
        }
    }

    // Penalize bins deviating from mean residual (balance load across bins).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Slight preference for filling larger bins later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.5 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize mid-range residuals more than extremes,
    // with strength growing over stream progress.
    let mid_penalty = 4.0 * pr * (1.0 - pr); // peaks at pr = 0.5
    score += (0.5 + progress) * mid_penalty * bin_capacity as f64 * 0.5;

    // Reward tight fits (small post residual) with a convex shaping term
    score -= (1.0 - pr).powi(3) * 10.0;

    // Penalize very large wasted residual quadratically, damped early in the stream
    score += progress * pr * pr * 20.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are large
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.15 - progress * 5.0;
    }

    // Lookahead coupling: if next item could use the post residual, reward leaving it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 5.0 {
            score -= 6.0;
        } else if nxt > post_residual as f64 {
            score += 2.0 * (1.0 - progress);
        }
    }

    // Mild penalty for accumulating many open bins with slack
    score += open_bins_count as f64 * 0.05 * mean_residual / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (<= 10) are nearly perfectly packed.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else {
        // Modulo-10 class: residues 1..=10 are "tight" classes.
        let class = (post % 10) as f64;
        let decile = (post / 10) as f64;
        // Penalize dead space quadratically, softened for tiny residues.
        score += 0.35 * (post as f64).powi(2) / cap - 8.0 * (10.0 - class.min(10.0)) / 10.0;
        // Coarse decile thresholds: leftover > 30 with next item small is reusable.
        if decile >= 3.0 && next_item_size > 0 && next_item_size <= post {
            score -= 12.0; // bin can plausibly host the lookahead item too
        }
        // Harmonic penalty: residues that are multiples of 5 pair well with
        // typical item sizes (multiples of 5/10); reward them mildly.
        if post % 5 == 0 {
            score -= 5.0;
        } else if post % 10 == 1 || post % 10 == 9 {
            score += 4.0; // awkward off-by-one residues create dead space
        }
    }

    // Lookahead coupling: if next item exactly fills the post residual,
    // this bin is ideal for a two-item chain.
    if next_item_size > 0 && next_item_size == post {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post {
        // Next item won't fit here: this bin becomes dead space unless post is tiny.
        if post > 15 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; reduced late in the stream or when
        // many bins are open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= 60 {
            new_bin_score -= 15.0; // big lookahead item benefits from fresh space
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // nothing fits: must open a bin
        }
        score = score * 0.0 + new_bin_score;
    }

    // Mild pressure toward consolidating into bins below mean residual fill.
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1.0f64;
    if post > 0.0 && post < min_item {
        score += 1000.0;
    }
    // Penalize "awkward" gaps: small but non-zero, hard to fill.
    if post > 0.0 && post <= 12.0 {
        score += (12.0 - post) * 4.0;
    }

    // Reward exact / near-exact fits.
    if post == 0 {
        score -= 50.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let tightness = item_size as f64 / cap;
    score -= tightness * 20.0;

    // Open-bin pressure: prefer already-open bins over opening new ones,
    // but the pressure is relaxed when this is the last fitting bin
    // (otherwise we would waste the bin's remaining space entirely).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is more attractive late in the stream
        // (fewer future items to consolidate).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    } else {
        score -= 5.0;
        if fitting_bins_count == 1 {
            // Last chance: strongly favor using this bin.
            score -= 30.0;
        }
    }

    // Mean residual coupling: when open bins are already loose on average,
    // avoid adding to the loosest ones; prefer filling bins below mean residual.
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward leaving exactly that gap; if next item cannot fit in the gap,
    // the gap is dead space — penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 25.0;
        } else if post > 0.0 && post < nxt {
            score += post * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect fit for next item (small slack)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item can't follow here: penalize proportionally to how much space is wasted
        score += 15.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Penalize unusable dead space (below minimum plausible item size)
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64;
    }

    // Last chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: mildly discourage unless current bins would waste a lot
    if bin_residual == bin_capacity {
        score += 35.0;
        // encourage new bin when existing residuals are far from item
        if (mean_residual - item_size as f64) > 20.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Prefer tighter bins relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // Wasted space that next item cannot use.
            score += 0.15 * (post_residual as f64);
        }
        // Prefer bins whose post-residual pairs well with next item size.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.05 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing ones.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / cap);

    // Mean-residual coupling: penalize bins far below mean residual (fragmented bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Time horizon: late in the stream, be more conservative (favor tight packing,
    // discourage opening new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, but its value is modulated by stream progress.
    // Early on, waste is cheaper (more items to come to fill gaps);
    // late, residual waste is more costly -> weight grows with progress.
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = pr * (1.0 + 0.6 * progress_weight);

    // Non-linear penalty on large unusable gaps: gap that next item cannot use.
    let next_fits = if next_item_size > 0 {
        (next_item_size as f64 / cap)
    } else {
        0.0
    };
    let unusable = ((norm_pr - next_fits).max(0.0)).powi(2);
    score += 40.0 * unusable;

    // Reward tight fits: post_residual near zero gets a smooth quadratic bonus.
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 30.0 * tightness * norm_item;

    // Interaction: item size vs mean residual — prefer bins whose residual
    // is close to the item size (smooth kernel).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 15.0 * gap * gap;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * progress_weight;
    }

    // Slight penalty for proliferating bins relative to mean residual pressure.
    let residual_pressure = mean_residual / cap;
    score += 2.0 * open_bins_count as f64 * residual_pressure * (1.0 - residual_pressure);

    // New-bin candidate: mild smoothing so it wins only when open bins are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity-fraction cell does post_residual fall in?
    let quarters = (post_residual * 4) / bin_capacity; // 0..=3 integer division class
    match quarters {
        0 => score -= 12.0,  // tiny dead space: excellent fill
        1 => score -= 4.0,   // quarter leftover: good
        2 => score += 0.0,   // half leftover: neutral
        _ => score += 8.0,   // mostly empty bin: wasteful placement
    }

    // Modulo-10 harmonic: leftovers that are multiples of 10 are reusable by typical items
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Leftovers in awkward residue classes (1..9 mod 10) are dead space
    if post_residual % 10 != 0 && post_residual < 10 {
        score += 5.0;
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the leftover's harmonic class admit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward leftovers that leave a nicely-classed remainder for the next item
            let next_quarters = (slack * 4.0 / cap).floor();
            score -= 10.0 - 2.0 * next_quarters;
            if slack % 10.0 == 0.0 { score -= 3.0; }
        } else {
            // leftover cannot host next item: penalize proportionally to overshoot
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when existing bins would waste space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_residual - item_size) as f64;
        score = waste + 10.0 * progress - 0.05 * mean_residual;
        if next_item_size > item_size && item_size < bin_capacity / 2 {
            score -= 8.0; // pair large-then-small on a fresh bin
        }
    }

    // Mild pressure to prefer bins below mean residual (tighter bins first)
    score += 0.03 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable by
    // typical items -> heavy penalty band for post_residual in 1..=12.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits relative to item size (fill ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: penalize using bins when many are open,
    // encouraging consolidation; also mild pressure to reuse bins
    // over opening new ones.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make
    // it attractive only when no tight fit exists (its raw score is
    // naturally high via post_residual = capacity). Nudge it up so it
    // loses against decent fits, but stays ahead of dead-space-heavy ones.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is cheaper early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if the next item can use this bin's post-residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Prefer bins whose residual is below the mean residual (more filled bins).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain two items perfectly
        } else if post_residual > next_item_size {
            // residual left after both placements
            let after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - after_next as f64 / bin_capacity as f64);
            if after_next <= 10 {
                score -= 8.0; // near-perfect double fit
            }
        } else {
            // next item cannot reuse this bin's residual -> dead space risk
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Reward tight packing relative to mean residual of open bins.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving very small unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when it prevents bad fragmentation
    // (i.e. current placement would leave large dead space while many bins exist).
    if bin_residual == bin_capacity {
        score += 20.0; // default penalty for opening a new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain the next item too
        }
        if item_size > 50 {
            score -= 10.0; // large items pack cleanly in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
