pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * progress;

    let mut score = pr + 40.0 * poly * cap;

    // Penalize dead space more aggressively later in the stream (smooth cubic)
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += cap * dead * (0.5 + 1.5 * progress * progress * (3.0 - 2.0 * progress));

    // Last-chance bonus: strongly favor the only bin that fits (smoothly scaled by progress)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 50.0 * progress;
    }

    // Lookahead: reward residual that can host the next item (smooth quadratic gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = ((pr - nxt) / cap).abs();
        score -= 25.0 * fits_next * (1.0 - gap * gap) * (0.3 + 0.7 * progress);
    }

    // New-bin candidate: mildly discourage opening a bin early, allow it late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
        // discourage new bin if many open bins with slack
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Tight-fit reward: near-exact fills are excellent (smooth quadratic)
    let tight = 1.0 - (norm_pr * 2.0 - 1.0) * (norm_pr * 2.0 - 1.0);
    score -= 20.0 * tight * tight * (0.5 + progress);

    // Deviation from mean residual: prefer bins unlike the average to diversify residuals
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: perfectly divisible leftovers (post_residual % 10 == 0) are ideal.
    let class = post_residual % 10;
    score += match class {
        0 => -6.0,
        5 => -3.0,
        1 | 9 => -1.5,
        _ => 0.0,
    };

    // Integer-division threshold bands on post_residual: dead space bands.
    let band = post_residual / 10;
    score += match band {
        0 => -4.0,          // near-perfect fill
        1 => -2.0,
        2 | 3 => 0.0,
        4 | 5 => 1.5,
        _ => 3.0,           // large unusable leftover
    };

    // Lookahead coupling: does the leftover accommodate the next item's harmonic class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            let slack_class = slack % 10;
            // Reward if next item fits with a clean remainder
            if slack_class == 0 { score -= 5.0; }
            else if slack_class == 5 { score -= 2.5; }
            score -= (slack / 10).min(4) as f64 * 0.75;
        } else {
            // Next item won't fit here; penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += 1.0 + (gap % 10) as f64 * 0.15 + (gap / 10) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer tighter fits, mild crowding penalty
        score += 0.5;
    }

    // New-bin candidate handling: empty bin gets a moderate default score.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins are crowded
        // or the fit would be poor elsewhere. Base penalty keeps it in check.
        score += 10.0;
        // But if the item exactly halves/quarters a fresh bin harmonically, it's fine
        if item_size * 2 == bin_capacity { score -= 4.0; }
        if bin_capacity % item_size == 0 { score -= 2.0; }
        // Late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 2.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already tight — using it preserves open space elsewhere.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (residual_f - mean_residual) / mean_residual;
        score -= deviation.clamp(-1.5, 1.5) * 2.0;
    }

    // Slight preference for bins with small absolute residual (tight packing).
    score += (bin_residual as f64) * 0.02;

    // Progress-scaled urgency: near the end, avoid leaving many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual % 7) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the unusable gap (1..=10) are heavily penalized,
    // since no future item (min size 1..100, typically >=10) can use them.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a residual that exactly matches the lookahead item (chain packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if the leftover cannot fit the next item but is still large-ish (wasted potential)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer tight packing
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: if this bin's residual is far below average, it's already tight — favor it
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 0.5;
        // If it's a last resort (only this candidate can fit), make it available but not free
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0;
        }
        // Late in the stream, opening new bins is less costly than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= progress * 5.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract score)
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual, this is a great chain
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how snugly
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit after placement: penalize leftover dead space
            score += 25.0;
        }
    }

    // Reward tight fits relative to bin residual (small post_residual is good)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness;

    // Compare against mean residual: placing in a below-average-residual bin
    // (a tight bin) is good, opening slack in a loose bin is wasteful.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New empty bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if the item is huge and would leave a large hole in any existing bin,
        // opening fresh is competitive
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // late in the stream, opening a fresh bin is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space: residual too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // existing fits are poor or the item is large.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.4 * bin_capacity as f64;
        let large_item = item_size > bin_capacity / 2;
        if poor_fit || large_item {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // Lookahead coupling: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global state: with many open bins and high mean residual, prefer
    // consolidating into existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 && mean_residual > (bin_capacity as f64) * 0.5 {
        if bin_residual != bin_capacity {
            score -= 6.0;
        }
    }

    // Early phase: be slightly conservative, keep bins balanced.
    if progress < 0.2 {
        score += (bin_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Mild penalty for very full bins late in the stream to avoid
    // wasting near-closed bins on trivial items.
    if post_residual < 5 && progress > 0.8 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer small post residual (tight fit), with non-linear scaling.
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm);

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tight fits matter more.
    let tightness = 1.0 - post_norm;
    score -= 8.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize residual that is too small to ever be useful again
    // (smooth quadratic dead-space penalty around the minimum item size).
    let min_item = 1.0f64;
    let unusable = ((min_item - post) / cap).max(0.0);
    score += 40.0 * unusable * unusable * cap;

    // Lookahead: bonus if the next item fits the post residual (chaining).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive early or when this bin
    // would leave a very awkward residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let awkward = (1.0 - tightness).min(1.0); // = post_norm
        score += 10.0 * open_bins_count as f64;
        score -= 5.0 * (1.0 - progress) * (1.0 - awkward);
        // Discourage new bin if the residual left is nearly a full item slot.
        score += 15.0 * awkward * awkward;
    }

    // Mild dispersion penalty: prefer bins whose residual is below the mean
    // (consolidating space) with smooth interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    // Small reward for high fill ratio, smoothly scaled by progress.
    score -= 3.0 * fit_ratio * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "dead space quality".
    // Small usable residues (10..=30) are valuable; tiny residues (<10) are dead space.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if pr < 10 {
        score += 25.0; // dead space: unusable for min-size items
    } else if pr <= 30 {
        score -= 20.0 - (class as f64); // usable small pocket, reward finer fits
    } else {
        score -= 5.0; // still roomy, mild reward
    }

    // Coupling with lookahead: does next_item_size fit in the pocket?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward proportional to how snugly it fits
            let snug = (pr - next_item_size) as f64;
            score -= 15.0 - snug * 0.3;
        } else {
            // next item cannot use this pocket: penalize by overflow amount
            let over = (next_item_size - pr) as f64;
            score += over * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all poor.
    if bin_residual == bin_capacity {
        let mean_poor = mean_residual < 35.0;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0));
        score = 100.0 + pressure * 10.0 - if mean_poor { 30.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item fully
        }
    }

    // Late in the stream: consolidation matters more, tighten scoring.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; residuals below a practical threshold are heavily penalized.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits generally (post_residual small relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins that keep residual balance,
    // but avoid bins whose residual is much larger (wasteful spread)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Lookahead: if the next item can fit into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit into post residual but could fit a fuller bin, penalize
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the item is large or few bins fit it; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + (item_size >= 60) as i32 as f64;
        score -= pressure * 30.0;
        score += 5.0; // mild default cost to prefer filling open bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
