        if (post_residual as f64) >= next {
            // Next item fits here afterwards -> big reward proportional to match quality.
            let match_gap = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 45.0 * (1.0 - match_gap);
        } else {
            // Next item cannot follow in this bin -> penalize, worse if residual is dead space.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * dead;
        }
    }

    // Compare against mean residual: bins with residual near item_size are ideal targets.
    let mean_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.25 * mean_gap;
    if (bin_residual as f64) < mean_residual - 5.0 {
        score -= 8.0; // tighter-than-average bin: use it before it becomes dead space
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_alt = if next_item_size > 0 {
            (post_residual as f64).min(bin_capacity as f64)
        } else {
            bin_capacity as f64
        };
        // Penalize new bin mildly; big items prefer fresh bins though.
        let mut nb = 15.0;
        if item_size >= 50 {
            nb -= 18.0;
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            nb -= 10.0; // new bin can host a clean pair
        }
        score = nb + best_alt * 0.1;
    }

    // Slight late-stream tightening: consolidate into fewer bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any plausible future item (1..=100).
    if post_residual > 0 {
        let dead = (cap - post_residual as f64) / cap;
        score += 10.0 * dead * dead;
    }
    if post_residual >= 1 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits the post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > (item_size as f64 + 5.0) {
        score -= 5.0 * (mean_residual / cap);
    }

    // New-bin candidate handling: only attractive early or when current bin is a bad fit.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 0.6 * cap;
        if progress < 0.2 || bad_fit {
            score -= 8.0 + 10.0 * (1.0 - progress);
        } else {
            score += 20.0 * progress; // discourage new bins late in the stream
        }
    }

    // Mild preference for fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic-quartic polynomial in normalized post residual
    let mut score = 4.0 * x - 6.0 * x * x + 4.0 * x * x * x - x * x * x * x;

    // Smooth non-linear coupling with stream progress: dead space hurts more later
    score += progress * (x * x) * cap * 0.5;

    // Interaction: item size relative to capacity, smooth cubic coupling with progress
    let s = item_size as f64 / cap;
    score -= (1.0 - s) * (1.0 - s) * (1.0 - progress) * 2.0;

    // Last-chance bonus: strongly favor the only fitting bin, scaled smoothly
    if fitting_bins_count == 1 {
        score -= 3.0 + 4.0 * progress;
    }

    // Next-item lookahead: smooth reward when next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = if nx <= x { 1.0 - (x - nx) / cap } else { -1.0 * (nx - x) / cap };
        score -= fit * (1.0 - progress) * 1.5;
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.05 * (x / (1.0 + x));

    // Mean residual coupling: prefer bins near the mean (smooth bell)
    let d = (x - mean_residual / cap).abs();
    score += d * d * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..=1

    // Class index via integer division on post_residual (harmonic bands of capacity/8).
    let band = (post_residual * 8) / bin_capacity; // 0..=8
    let band_penalty: f64 = match band {
        0 => -30.0,                 // perfect fit: zero waste
        1 => 12.0,                  // tiny sliver: nearly useless dead space
        2 => 8.0,                   // small sliver
        3 => 2.0,                   // ~37.5% residual: moderately reusable
        4 => -6.0,                  // half-full residual: very reusable
        5 => 0.0,
        6 => -4.0,
        7 => -10.0,                 // large residual: flexible bin
        _ => -20.0,                 // empty-ish bin (new bin candidate)
    };
    score += band_penalty;

    // Reward tight fits continuously: closeness of post_residual to 0 or to a
    // "harmonic" residual that a typical next item could consume.
    score += (post_f * post_f) / (cap_f * 4.0); // quadratic waste penalty

    // Harmonic pairing: does post_residual modulo next_item_size leave a good remainder?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits here: strong reward, scaled by how cleanly it divides
            let rem = post_residual % next_item_size;
            let div_quality = (rem as f64) / nxt; // lower = cleaner division
            score -= 25.0 - 18.0 * div_quality;
            // exact harmonic multiple of next item size is ideal
            if rem == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow into this bin: penalize if we leave stranded space
            score += 6.0 + 0.15 * (nxt - post_f);
        }
        // modulo class of next item vs capacity: big next items favor conserving large residuals
        let nxt_class = (next_item_size * 4) / bin_capacity;
        if nxt_class >= 2 {
            // next item is large; prefer bins whose post_residual is small anyway
            score += 0.05 * post_f;
        } else {
            // small next item: large residuals are valuable
            score -= 0.04 * post_f;
        }
    } else {
        // last item: only absolute waste matters
        score = post_f;
        return score;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would strand a lot of space everywhere.
    if bin_residual == bin_capacity {
        // new bin: residual after placement = capacity - item; score it neutrally
        // but discourage opening when a decent fit exists among open bins.
        let avg_fit = mean_residual; // typical space left in open bins
        let waste_here = post_f;
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        if waste_elsewhere < waste_here * 0.6 && fitting_bins_count > 0 {
            score += 25.0; // keep using open bins
        } else if avg_fit < item_size as f64 {
            score -= 10.0; // open bins are congested; fresh bin is good
        }
        // progress-aware: early in the stream, mild preference to consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Congestion coupling: many open bins with high mean residual -> favor
    // draining the bins with residual close to this item's harmonic class.
    let class_gap = ((post_f - mean_residual) / cap_f).abs();
    score += 4.0 * class_gap * (open_bins_count as f64).sqrt();

    // Fine harmonic bonus: post_residual divisible by common small item sizes (10..=25)
    for d in [10u32, 12, 15, 20, 25] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 3.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward (dead space zero).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any unusable small gap is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }
    // Moderately bad gaps that most items (min 10) can still barely use.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward when this bin's post-fit gap can exactly host the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize if the gap is too small for the lookahead item (dead space for k+1).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to existing open bins.
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if the item is huge relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual {
            score -= 50.0;
        }
    } else {
        // Reward placing into already-open bins, more so with many open bins.
        score -= (open_bins_count as f64).sqrt() * 5.0;
    }

    // Late in the stream: tighten packing, avoid waste even more.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: this bin becomes exactly
    // sized for the next item (dead space eliminated across two placements).
    if next_item_size > 0 {
        let perfect = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if perfect == 0.0 {
            score -= 1000.0;
        } else {
            // Penalize mismatch between post_residual and next item size,
            // scaled by how "tight" the fit is.
            score += perfect * 0.5;
        }
        // If next item cannot fit in the post-residual, penalize proportionally.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Penalize leaving tiny unusable dead space (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Reward exact fill.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win if no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; add small penalty so good fits in open
        // bins win, but subtract if no open bin can fit the item.
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            score += 80.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the mean (tighter than average bins get priority).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins harder to avoid leftover fragments.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact or near-exact fill bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Penalize leaving dead space that no realistic item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are bad
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to mismatch
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin, modulated by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * progress;
        // if many open bins already fit the item, discourage new bin
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64 - 1.0);
        }
        // early stream: cheaper to open bins to build a diverse residual pool
        if progress < 0.3 {
            score -= 25.0;
        }
    } else {
        // Prefer bins whose residual is above item_size with room to spare
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score += 10.0 * (1.0 - fit_ratio);

        // Prefer fuller bins (small residual) to consolidate waste
        score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Global state: many open bins with high mean residual -> consolidate
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 8.0;
    } else if open_bins_count > 8 {
        score -= 5.0; // encourage packing into existing bins when bin count grows
    }

    // Mild time-horizon term: late in stream, avoid creating new residual diversity
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 5.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a smooth non-linear penalty
    // for small-but-unusable leftover space (dead space valley).
    let mut score = pr_norm + 2.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Polynomial coupling of post-residual with stream progress:
    // early on, waste matters less; later, tighten packing.
    let tightness = 1.0 + 3.0 * progress * progress;
    score *= tightness;

    // Interaction: current residual vs mean residual (smooth divergence term).
    let mean_norm = mean_residual / cap;
    let divergence = pr_norm - mean_norm;
    score += 0.5 * divergence * divergence;

    // Lookahead coupling: reward leaving room close to next item size,
    // penalize overshooting it — smooth quadratic around the gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = pr_norm - nxt;
        score -= 0.8 * (-gap * gap * 8.0).exp();
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Slight pressure against accumulating many open bins late in stream.
    score += 0.001 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // class (multiples of 10, or >= 20) are rewarded; tiny dead space is penalized.
    let post_class = post_residual / 10;
    match post_class {
        0 => score += 45.0,               // dead space < 10: nearly unusable
        1 => score += 18.0,               // 10..19: awkward sliver
        2 => score += 6.0,                // 20..29: marginal
        _ => score -= 4.0,                // >= 30: still broadly usable
    }

    // Exact-harmonic fit: post_residual divisible by 10 is a "clean" residue.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: reward when the next item can reuse the post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
            // Perfect harmonic reuse: next item exactly divides the leftover class.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this leftover: mildly penalize tight fits.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Tightness reward: the fuller the bin after placement, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this is the empty bin and the item would leave a huge gap elsewhere,
    // or the stream is early and spreading is cheap).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when good open candidates exist.
        if fitting_bins_count > 0 {
            score += 55.0 - 20.0 * progress;
        }
        // Slight discount early in the stream to allow bin spreading.
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if this bin is much emptier than average, gently
    // deprioritize it (prefer filling the emptiest bins evenly to keep classes usable).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Larger residuals are partially reusable: mild reward scaled by fit potential
        score -= 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residuals that can still host a typical next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize blocking the lookahead item's fit
    if next_item_size > 0 && next_item_size > post_residual && bin_residual >= next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins that keep residual distribution balanced
    score += 0.25 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / 10.0;
        score += 15.0 + 20.0 * crowd;
    }

    // Early stream: be slightly more liberal with new bins since future packing matters
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space super-linearly relative to capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 200.0;
    }

    // 2-step lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * snug;
        } else {
            // Next item won't fit here: penalize leaving medium-size gaps
            // that are too small for the next item but large enough to waste.
            score += 50.0;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (fill nearly-full bins first), unless it creates tiny dead space.
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make it unattractive unless current placement is terrible.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Opening a fresh bin is worthwhile if the item would leave an awkward gap
        // and the next item is large (reserve space strategy).
        if next_item_size > 0 && post_residual > 0 && post_residual < 20 {
            score -= 300.0;
        }
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 40.0 * progress;
    }

    // Mild preference for bins with fewer open bins overall (pack denser early).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small for the smallest item (size 1..=100 range, min item 1).
    // Dead space below ~15 is nearly unusable; penalize quadratically.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }

    // Lookahead: reward if next item fits in the resulting residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0 * (next_item_size as f64 / cap);
        } else {
            // Penalize leaving a residual that blocks the known next item.
            score += 8.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin mildly unattractive unless
    // the current fit is bad (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if post_residual as f64 > 0.35 * cap {
            score -= 15.0; // poor fit in existing bins -> open new bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer filling bins that already deviate below the mean residual
    // (balances residual distribution, avoids many half-empty bins).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.5 * dev;
    }

    // Mild pressure to use open bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: prefer tight fits, with progress-dependent aggressiveness
    // Early: mild tightness preference; late: strong tightness preference
    score += pr_norm * (1.0 + 3.0 * progress) * 20.0;
    // Smooth quadratic penalty on wasted space, weighted by progress
    score += pr_norm * pr_norm * (10.0 + 40.0 * p2);

    // Cubic interaction: dead space becomes increasingly costly as stream advances
    score += pr_norm * p3 * 30.0;

    // Last-chance bin: strong smooth reward, scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Coupling with mean residual: bins deviating from mean residual are
    // penalized quadratically (keeps bin states homogeneous)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (bin_capacity as f64);

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item fits here too: reward chaining
            score -= 8.0 * (1.0 - ((pr - nxt) / bin_capacity as f64).abs());
        } else {
            // next item won't fit: penalize proportionally to shortfall
            let short = (nxt - pr) / bin_capacity as f64;
            score += 6.0 * short * short * 10.0;
        }
    }

    // Mild penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
        // But late in the stream, compacting into existing bins is preferred more strongly
        score += 10.0 * progress;
    }

    // Reward filling a bin completely (exact fit bonus, smooth)
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are more reusable -> reward them.
    if post_residual > 0 {
        if post_residual % 50 == 0 {
            score -= 12.0;
        } else if post_residual % 25 == 0 {
            score -= 8.0;
        } else if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    // Dead-space class: small unusable remainders are penalized more
    // when they fall in awkward integer-division buckets.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.5;
    }

    // Lookahead coupling: does the next item's harmonic class fit the
    // post-residual exactly or nearly?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect pairing
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // near-perfect pairing
        } else if post_residual < next_item_size && post_residual > 0 {
            // next item cannot use this leftover; penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(15.0);
        }
        // Harmonic class match: next item shares a divisor class with residual
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance pressure: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: only open a new bin when the item is large and
    // no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64;
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual * 0.15;
        score = tightness - 25.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open anyway
        }
    }

    // Progress modulation: as the stream advances, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (post_residual % 4) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that are hard to fill later.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }
    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }
    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    }
    // Penalize wasting a near-empty bin on a small item.
    if bin_residual >= bin_capacity - 5 && item_size < 40 {
        score += 20.0;
    }
    // Open-bin pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 3.0 * (0.5 + progress);
    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Prefer bins tighter than the mean residual (dense packing).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 5.0;
        if post_residual >= 50 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect 2-step packing: huge reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits in the leftover: reward proportional to tightness.
            let slack = pr - nxt;
            score -= 30.0 - slack.min(30.0);
        } else {
            // Next item cannot fit in the leftover: penalize dead space risk.
            let gap = nxt - pr;
            score += (gap * 0.8).min(40.0);
        }
        // Bonus if next item could also exactly consume this bin's residual in two steps.
        if nxt + item_size as f64 == bin_residual as f64 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer minimal post residual (best-fit behavior).
        score += (post_residual as f64) * 0.5;
    }

    // Penalize bins that are far from the mean residual (avoid fragmenting outliers).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 20.0;
    }

    // Late in the stream, tighten preference for tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.3;

    // Prefer reusing already-open bins over opening new ones (new empty bin gets a handicap).
    if bin_residual == bin_capacity {
        score += 15.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space non-linearly
    let dead = post_residual as f64;
    score += 0.05 * dead * dead / bin_capacity as f64;

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize leaving medium dead space
            if post_residual < 10 {
                score += 30.0; // tiny dead space is fine actually — reward instead
                score -= 60.0;
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).min(1.0);
        // penalize opening new bin generally, less so for big items
        score += 150.0 - 120.0 * tightness;
        if next_item_size > 0 && next_item_size >= bin_residual - item_size && item_size >= 60 {
            score -= 100.0; // big item + big next item: fresh bin is good
        }
    }

    // Time horizon: early in stream, be conservative with open bins; later, fill aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 80.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: many open bins with high mean residual -> consolidate
    let pressure = mean_residual * open_bins_count as f64 / bin_capacity as f64;
    score -= 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item size (tight fit)
    let slack = (bin_residual - item_size) as f64;
    score += 20.0 * (slack / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), with polynomial shaping.
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Stream-progress coupling: later in the stream, be stricter about dead space.
    score -= 30.0 * (1.0 - norm_pr) * progress * progress;

    // Smooth interaction between post residual and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (nxt <= pr) as i32 as f64;
        // Reward if next item can still fit in post residual.
        score -= 25.0 * fit_next * (1.0 - norm_pr) * (pr / (nxt + 1.0)).min(1.0);
        // Penalize post residuals slightly too small for next item (dead space).
        let miss = ((pr - nxt) / cap).abs();
        score += 10.0 * miss * (1.0 - fit_next) * (0.5 + progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open (encourage consolidation early).
    score += (open_bins_count as f64).ln() * 3.0 * norm_pr;

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // to balance residuals smoothly (polynomial deviation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate handling: discourage opening new bins unless
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score = 1.05 * cap + 50.0 * (1.0 - progress) - 20.0 * (1.0 - norm_pr);
        // If no open bin fits well (large post residual would result), allow new bin.
        if pr > 0.0 && item_size as f64 / cap > 0.7 {
            score -= 60.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in
    // "harmonic" classes (multiples of small divisors) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 5.0; }
        score -= harmony;
    }

    // Dead-space penalty: tiny unusable residuals.
    if pr < 10 {
        score += 25.0 - (pr as f64) * 1.5;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the post-residual harmonically fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack % 10 == 0 { score -= 8.0; }
            if slack < 10 { score -= 5.0; }
            score += slack as f64 * 0.15;
        } else {
            // Next item cannot use this residual; penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are crowded or the item is large.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let penalty = 30.0 + crowd * 4.0 + item_size as f64 * 0.3 + progress * 10.0;
        score += penalty;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin may help
        }
    }

    // Mild tightness reward: prefer bins that were already partially filled.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect fit of the residual (item exactly fills bin).
    if item_size == bin_residual {
        score -= 200.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 20.0;
        }
        // Strong bonus: this bin takes the item AND next item fits exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin pressure.
        score += 30.0 + bin_pressure * 5.0;
    } else {
        // Reward reusing existing bins, more so when many are open.
        score -= (bin_pressure * 0.8).min(40.0);
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (consolidating space) when this bin is a good fit.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (2-step lookahead core).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportionally to wasted chain
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fit
        score -= 15.0;
    }

    // Reward bins below mean residual (relative slack matching).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual), with a sweet spot at exact fill.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items (1..=100 range).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 15.0 {
            score += 40.0 * (15.0 - dead); // nearly-unusable sliver
        } else if dead > 80.0 {
            score += 0.5 * (dead - 80.0); // wasteful large leftover
        }
    }

    // Lookahead: if next item can fit in post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 35.0;
            // Extra reward if next item also fits tightly after this placement.
            let n_post = post_residual as u32 - next_item_size as u32;
            score -= 15.0 * (1.0 - n_post as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize slightly less if this bin was a last chance.
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 45.0;
        // But if post-residual becomes a useless sliver, soften the bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    }

    // New-bin candidate handling: an empty bin (bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin early in the stream or when many open bins exist and residuals are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Open new bins when mean residual is high (existing bins are full-ish or scattered)
        // but only late enough that we're not wasting capacity early.
        if fragmentation < 0.35 || open_bins_count == 0 {
            score -= 25.0 * (1.0 - progress);
        } else {
            score += 20.0 * fragmentation;
        }
        // Never open a new bin if a large item would leave a good chunk in an existing bin.
        if fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
    } else {
        // Existing bin: reward keeping bins balanced; prefer bins below mean residual
        // (fill emptier bins first to consolidate).
        if (bin_residual as f64) > mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Time-horizon coupling: late in the stream, be aggressive about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * tightness;

    // Slight penalty for accumulating too many open bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling: normalized post residual shaped by progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * fit_frac * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_pr).powi(2) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0) / cap;
        score += 25.0 * gap * gap * (0.5 + progress);
        // Bonus if post residual still accommodates next item
        let accommodates = ((pr - nx).max(0.0) - (nx - pr).max(0.0)) / cap;
        score -= 8.0 * accommodates.max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: smooth urgency term
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild pressure from mean residual and open bin count
    score += 0.05 * (mean_residual - pr).abs();
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate handling: discourage opening new bins unless residual is large
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are more valuable to keep.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual too small to hold the smallest item (1..=10)
    let min_item = 10.0_f64.min(cap);
    if pr < min_item {
        score += 60.0; // unusable sliver
    } else {
        // Harmonic class reward: residual divisible by small common sizes
        let r = post_residual;
        let mut class_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if r % m == 0 && r > 0 {
                class_bonus += 8.0;
            }
        }
        // Integer-division threshold: residual >= next item => lookahead fits
        if next_item_size > 0 && r >= next_item_size as f64 {
            class_bonus += 15.0;
            // extra harmony: post_residual - next_item also lands on a class
            let r2 = r as u32 - next_item_size;
            for m in [10u32, 20, 25, 50].iter() {
                if r2 % m == 0 && r2 > 0 {
                    class_bonus += 5.0;
                }
            }
        } else if next_item_size > 0 {
            class_bonus -= 5.0; // lookahead cannot use this residual
        }
        score -= class_bonus;
    }

    // Fraction-of-capacity coupling: prefer tight fills
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= 20.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // cheaper to open new bin early in stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mean residual alignment: prefer bins close to mean (keeps balance)
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: classify unusable small gaps
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // truly dead space (defensive; min item = 1)
    }

    // Penalize gaps too small for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to what we know is coming
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still host the next item
        score -= 3.0;
    }

    // Tight fits are excellent: reward small post_residual strongly
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.4;

    // Prefer bins tighter than the mean residual (good fills)
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 25.0;
        // More acceptable early in the stream or when no bin fits well
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, new bin is fine
        }
        // If next item is large, a fresh bin is more attractive
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.5 * next_item_size as f64;
        score += 0.3 * gap; // prefer tight chains
        if gap == 0.0 {
            score -= 20.0; // perfect chain
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to wasted potential
        score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Tight fit reward
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize opening a new bin when decent fits exist (empty-bin candidate)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let urgency = if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
        score += 20.0 + urgency + 0.2 * mean_residual;
        // Still allow a new bin if it enables a perfect 2-item chain
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Time horizon: later in the stream, be more conservative — favor filling
    // existing bins over opening new ones (new-bin candidate gets high score).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with progress and openness.
        score += 30.0 + 70.0 * progress + open_bins_count as f64 * 2.0;
    } else {
        // Early in the stream, opening new bins is cheaper; reward existing-bin
        // placement less aggressively so exploration happens.
        score -= 20.0 * (1.0 - progress);
    }

    // Global residual pressure: if mean residual is low, preserve bins with
    // large residuals for future large items.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += residual_frac * (mean_residual / bin_capacity as f64).max(0.0) * 10.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to item size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap; // 0..1
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 20.0 * poly;

    // Tight fits are exponentially valuable, modulated by progress
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Dead space penalty: small post_residual that is hard to fill
    if post > 0.0 && next_item_size as f64 > post {
        score += 6.0 * (1.0 - norm_post) * (0.5 + 0.5 * progress);
    }

    // Lookahead synergy: next item fits exactly into post_residual
    if next_item_size as f64 == post && post > 0.0 {
        score -= 10.0 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening new bins when many bins fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    // Mean residual divergence penalty (smooth)
    let dev = (res - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste quantized by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Dead-space penalty: residual below smallest plausible item is pure loss.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < quarter {
        score += 25.0;
    } else if post_residual < 2 * quarter {
        score += 8.0;
    }

    // Modulo-class bonus: residuals that are multiples of common item sizes
    // (10/20/25/50) are more likely reusable later.
    let pr_u = post_residual;
    if pr_u % 10 == 0 {
        score -= 12.0;
    }
    if pr_u % 25 == 0 {
        score -= 6.0;
    }
    if pr_u % 50 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect harmonic pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - pair_waste / cap);
        } else {
            // next item won't fit here; slight penalty scaled by leftover size
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer tightest fits via relative fill ratio.
    score -= 30.0 * (item_size as f64 / cap);

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but allow it when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        score += 20.0 - 0.3 * mean_residual;
    }

    // Late in the stream, consolidate: favor existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Small tie-breaker on residual to break exact ties toward fuller bins.
    score += 0.01 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1..10 typical)
    // are almost unusable; penalize them super-linearly.
    if post_residual < 10 {
        score += (10 - post_residual as i32).max(0) as f64 * 6.0;
    } else if post_residual < 20 {
        score += (20 - post_residual as i32).max(0) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving a large gap that wastes space.
            score += post_residual as f64 * 0.15;
        }
    }

    // Mean-residual coupling: prefer bins below the mean residual (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: early on, be slightly more willing to open bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by residual fraction.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if (post_f - next_f).abs() < 0.5 {
            score -= 40.0; // perfect 2-step match: chain this bin
        } else if next_f <= post_f {
            // next item fits here: mildly reward proportional coupling
            score -= 10.0 * (next_f / post_f);
        } else {
            // next item won't fit in the leftover: penalize dead space relative to next size
            score += 0.3 * (post_f - next_f).abs();
        }
    } else {
        // Last item: just minimize leftover
        score += 0.2 * post_residual as f64;
    }

    // Compare against mean residual: bins far below mean are "precious" tight bins,
    // avoid wasting them on items that leave large gaps.
    let gap = post_residual as f64 - mean_residual;
    if gap > 0.0 {
        score += 0.25 * gap;
    } else {
        score += 0.1 * gap; // small bonus for below-mean leftover
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit badly,
    // but allow it early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt().recip().min(1.0);
        // if next item is large, an empty bin is attractive
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize post_residual aggressively.
    score += 3.0 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item would fit in the post-residual,
    // reward this placement (keeps chains of items in the same bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving dead space too small for the next item.
        score += 0.25 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)).min(post_residual as f64);
    }

    // Penalize opening a new bin when decent fits exist elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + 0.3 * waste;
        // Late in the stream, opening new bins is more costly (waste is permanent).
        score += 40.0 * progress;
        // If many bins are open but none fit well, opening new bin is more acceptable.
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 15.0 {
            score += 30.0;
        }
    } else {
        // Slight reward for using bins that are already below-average residual
        // (consolidates space into fewer bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Mild reward for filling nearly-full bins completely.
        if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins -> prefer consolidating into existing ones.
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap; later, tight fits matter more.
    let tightness = (pr / cap).powi(2);
    let progress_term = 0.5 + 1.5 * progress * progress; // smooth ramp in [0.5, 2.0]
    score += tightness * cap * progress_term * 0.6;

    // Reward near-perfect fits smoothly (quadratic bonus as post_residual -> 0).
    score -= (1.0 - pr / cap).powi(4) * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, less so when the item is large
    // or the lookahead item cannot use the residual anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 18.0;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            penalty += 10.0; // existing bin could still serve the next item
        }
        score += penalty * (1.2 - 0.6 * progress);
    }

    // Lookahead coupling: bonus if the post residual nicely accommodates the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - (gap / cap).powi(2));
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving medium dead space.
        score += 4.0 * (pr / cap) * (1.0 - progress);
    }

    // Slight preference for consolidating many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * (pr / cap);

    // Nudge toward bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space analysis
    let pr = post_residual;
    if pr > 0 {
        // Post-residual in the "unusable" band (smaller than min item) is dead space
        if pr < 10 {
            score += 60.0;
        }
        // Modulo classes: residuals that are multiples of common item sizes are reusable
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if reusable {
            score -= 15.0;
        }
        // Integer-division thresholds: classify residual into harmonic buckets
        let bucket = pr / 10; // 0..10
        score += match bucket {
            0 => 40.0,          // 1..9: nearly dead
            1 => 10.0,          // 10..19: fits only small items
            2..=3 => -5.0,      // 20..39: moderate reuse
            4..=6 => -12.0,     // 40..69: good reuse zone
            _ => -20.0,         // 70..99: large residual, very flexible
        };
    }

    // Fractional capacity coupling: tightness of the fit
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 {
        score -= 25.0; // big item into this bin is great
    } else if fill_frac < 0.3 {
        score += 8.0;  // small item wasting a large residual
    }

    // Lookahead harmony: does next item fit in post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus scaled by how well next item harmonizes with post_residual
        let harmony = next_item_size as f64 / post_residual as f64;
        if harmony > 0.7 {
            score -= 30.0; // next item nearly fills leftover
        } else {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // creates dead space for the known next item
    }

    // Last-chance bin: strongly prefer using it before opening new
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        // Empty bin: baseline score = capacity; keep it competitive only when
        // existing bins have poor fits or many bins already open with waste
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 30.0;
        if open_bins_count > 3 && mean_residual > 40.0 {
            score += 25.0; // plenty of open space elsewhere; discourage new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && fragmentation < 10.0 {
            score += 15.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs().min(30.0);

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to item size (small waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 40.0 * waste_ratio;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 50.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item cannot fit in post_residual, penalize slightly (dead end).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new bins / spreading.
    score += 3.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins with residual below mean (consolidate fuller bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for using existing bins over the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Late-stream: tighten packing as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 200.0; // exact 2-step chain
        }
        // Penalize leaving dead space unusable by next item
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize wasting a large residual on a small item
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // New bin candidate: only attractive when item is large or no good fits
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 60 || next_item_size == 0 {
            score -= 50.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit, mild penalty for wasted space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current fit is poor and there is slack in the system.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 60.0;
        let crowded = open_bins_count as f64 > 4.0 + 6.0 * (1.0 - progress);
        if poor_fit || (crowded && mean_residual > item_size as f64 * 1.5) {
            score -= 12.0;
        } else {
            score += 40.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with large residuals to consolidate space.
    if open_bins_count > 2 && mean_residual > 0.0 {
        let residual_gap = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 10.0 * residual_gap;
    }

    // Mild time pressure: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space
    let mut score = norm_pr * norm_pr * cap;

    // Non-linear coupling with stream progress: waste matters more later
    score += 40.0 * norm_pr * (progress * progress);

    // Reward tight fits with smooth saturating term
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * (1.0 - progress);

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: bonus if next item fits the post-residual (smooth)
    if next_item_size > 0 {
        let fits_next = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let gap = ((pr - next_item_size as f64).abs()) / cap;
        score -= 20.0 * fits_next * (1.0 - gap * gap);
    }

    // Penalize when bin residual far from mean residual (fragmentation)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins waste space
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition residual space into
    // capacity classes via integer division thresholds.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class of post_residual in units of capacity/10 (harmonic bands).
    let band = (post_residual / 10) as f64; // 0..10 bands
    // Small residuals are dead space -> penalize bands 0..2 heavily.
    score += (3.0 - band.min(3.0)) * 12.0;

    // Perfect / near-perfect harmonic fits: post_residual divisible by
    // common item granularities (5, 10, 25) are reusable -> reward.
    let p = post_residual;
    if p == 0 {
        score -= 40.0;
    } else {
        if p % 10 == 0 { score -= 15.0; }
        if p % 5 == 0 { score -= 6.0; }
        if p % 25 == 0 { score -= 10.0; }
    }

    // Fraction of capacity filled by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 20.0;

    // Lookahead: does next item fit into post_residual? Reward exact/near couplings.
    if next_item_size > 0 {
        if next_item_size == p {
            score -= 30.0;
        } else if next_item_size <= p {
            // harmonic class match: next item's size class vs residual band
            let next_class = (next_item_size / 10) as f64;
            score -= (next_class * 1.5).min(12.0);
            // leftover after hypothetical next placement
            let post2 = p - next_item_size as f64;
            if post2 % 10.0 == 0.0 { score -= 5.0; }
        } else {
            // next item cannot follow here; penalize small residuals more
            score += (p / 10.0).min(4.0) * 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so that
    // only genuinely poor fits in open bins trigger a new bin.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Mean residual context: when open bins are already roomy, avoid
    // stuffing this bin into an over-fragmented state.
    if mean_residual > 0.0 {
        let ratio = post / mean_residual;
        if ratio < 0.25 {
            score += (0.25 - ratio) * 30.0;
        }
    }

    // Many open bins: discourage spreading, prefer tight packing.
    if open_bins_count > 4 {
        score += (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover in (0, 10) is nearly unusable
    // (items are >= 10 in classic regime; small gaps below 10 are dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty for creating unusable slivers
    }

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize mid-range leftovers that few item sizes can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // post gap blocks the next item
    }

    // New-bin candidate: only attractive when open bins are fragmented
    // (mean residual large but unusable) or this bin is empty-ish.
    if bin_residual == bin_capacity {
        // Opening a new bin costs; make it competitive only under pressure.
        score += 12.0 + (open_bins_count as f64) * 0.4;
        if mean_residual > 30.0 {
            score -= 15.0; // open bins are fragmented; fresh bin is fine
        }
    }

    // Progress term: late in stream, tighten up to avoid slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-exact fits with the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }

    // Penalize dead space that the next item cannot use at all
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Penalize leaving residual far above the mean residual (wasteful spread)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for tighter fits overall
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Penalize large dead space if post_residual is small-but-awkward
    // (too small for typical future items, i.e. < next_item_size).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Reward bins whose post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless the item fits very poorly in existing bins.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if few bins are open or the stream is early, allow new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) / 5.0;
    }

    // Global pressure: when mean residual is high, prefer consolidating
    // into bins with below-average residual (spreading usage evenly).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Prefer closing out bins with tiny residuals as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score -= 20.0 * progress;
    }

    // Mild penalty for opening too many bins relative to progress.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover residual, with non-linear (quadratic/cubic) coupling to stream progress
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * (0.5 + progress)
        + 25.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            // penalize dead space that next item cannot use
            score += 8.0 * (nxt - pr) / cap * progress;
        }
    }

    // Penalize bins that deviate from mean residual (keep packing balanced)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * cap) * 100.0;

    // Mild penalty for many open bins (encourage consolidation early)
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class boundaries at capacity fractions (1/4, 1/2, 3/4).
    let post = post_residual as f64;
    if post == 0.0 {
        score -= 40.0; // perfect fit, always great
    } else {
        let frac = post / cap;
        if frac <= 0.25 {
            // dead space: small leftover, hard to fill
            score += 25.0 * (0.25 - frac);
        } else if frac <= 0.5 {
            // half-ish class: usable by mid-size items
            score -= 6.0;
            // integer division threshold: leftover fits common small sizes
            if post_residual >= 20 && post_residual % 10 == 0 {
                score -= 4.0;
            }
        } else if frac <= 0.75 {
            score -= 10.0; // large residual still flexible
        } else {
            score -= 14.0; // mostly empty bin, very flexible
        }
    }

    // Next-item harmonic class: reward bins whose post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // modulo harmony: post_residual % next_item_size small means chained fits
        let m = post_residual % next_item_size;
        score -= (next_item_size - m) as f64 * 0.15;
    } else if next_item_size > 0 {
        score += 5.0; // this bin can't host the next item either
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only open when nothing else fits well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 30.0 + pressure * 5.0;
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 10.0;
        }
    }

    // Stream progression: later in stream, be greedier (prefer tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are unusable for any
    // future item -> heavy penalty proportional to wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Small-medium gaps (10..25) are only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening a new one.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But if the current bin would leave a clean residual and the next item
        // fits there, opening a new bin can be fine; soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Prefer bins whose residual deviates from the mean (consolidation).
    score -= (bin_residual as f64 - mean_residual).abs() * -0.1;

    // Late in the stream, tighten up: penalize any leftover residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: strong reward for chained fit
            let slack_after_next = post_residual - next_item_size;
            score -= 2.0 * next_item_size as f64;
            score += 0.5 * slack_after_next as f64;
        } else {
            // Next item won't fit: penalize leaving residual that's too small
            // but also penalize wasting too much space
            let waste = post_residual as f64;
            score += 0.3 * waste;
            if post_residual < 10 {
                score += 50.0; // tiny dead space, unusable
            }
        }
    } else {
        // Last item: just minimize post residual
        score += 0.0;
    }

    // Relative to mean residual: prefer bins that stay near the mean
    // (balanced packing) but slightly prefer tighter bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 150.0;
        // But if the item is large relative to typical residuals, allow new bin
        if item_size as f64 > mean_residual * 0.9 {
            score -= 200.0;
        }
        // Early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is ideal, tiny leftovers are dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 40.0; // awkward sliver
    } else {
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64).powi(2);
    }

    // Last-chance bonus: only one bin fits; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead coupling: reward leaving a residual that fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 - 0.2 * slack as f64;
    } else if next_item_size > post_residual {
        score += 5.0; // this bin won't help the next item
    }

    // Time horizon: early in stream, be conservative with open bins; late, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 25.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins.
    if open_bins_count > 2 && mean_residual > (post_residual as f64 + 5.0) {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when item is large or no good open bin exists.
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 - 0.15 * waste - 20.0 / pressure.max(1.0) + 30.0 * progress;
        if item_size > 70 {
            score -= 25.0;
        }
    }

    // Mild preference for filling bins with less residual overall (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, scaled by capacity.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are acceptable; late, they become costly.
    let pr_norm = pr / cap;
    let coupling = pr_norm.powi(3) * (0.5 + 2.0 * progress);
    score += coupling;

    // Tightness reward: smooth bell around perfect fit.
    let tightness = (pr / cap - 0.02).abs();
    score -= 0.6 * (-tightness * tightness * 200.0).exp();

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 0.35 + 0.25 * progress;
    }

    // Lookahead: reward if post_residual can still hold next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.15 * (1.0 - (pr - nxt) / cap).exp();
        } else {
            // Dead space penalty: post residual too small for the next item.
            let waste = (nxt - pr) / cap;
            score += 0.25 * waste * waste * (1.0 + progress);
        }
    }

    // Slight preference for bins below mean residual (balancing), smoothed.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.05 * dev * dev.abs();

    // Penalize opening a new bin when open bins exist and fit is decent,
    // more strongly as the stream progresses.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 0.2 + 0.3 * progress + 0.002 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item-size gcd classes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, best outcome
    } else {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // Dead-zone penalties via integer division thresholds
        if pr < 10 { score += 25.0; }          // unusable sliver
        else if pr < 20 { score += 10.0; }
        else if pr < 30 { score += 3.0; }
    }

    // Fractional fill of the bin: reward high occupancy non-linearly
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: if the next item exactly matches post_residual
    // (harmonic class match), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let nxt = next_item_size as f64;
            // next item leaves a harmonic residue?
            let nxt_res = pr - next_item_size;
            if nxt_res % 10 == 0 { score -= 4.0; }
            score -= 6.0 * (nxt / cap);
        } else {
            // next item cannot use this residue: mild penalty proportional to waste
            score += 2.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad,
    // but reward it early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 - 6.0 * (1.0 - progress);
        score += 0.15 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space hard
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Lookahead: if next item fits the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot use the leftover gap, penalize dead space more
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Early stream: be more conservative about spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Prefer bins with residual close to mean (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect 2-step match: item + next item fill bin
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward scaled by slack after next placement
            let after_next = post_residual as f64 - nxt;
            score -= 20.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // next item will NOT fit: post_residual becomes dead space for lookahead
            let dead = nxt - post_residual as f64;
            score += 25.0 * (dead / 100.0);
        }
    }

    // Penalize large unusable residual (fragmentation)
    if post_residual < 10 {
        score -= 30.0; // near-perfect fill
    } else {
        score += 0.15 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    } else {
        score += 10.0 + 20.0 * progress; // penalize new-bin candidate, more late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.15;
        } else {
            score += 8.0; // leftover too small for lookahead item
        }
    } else {
        score -= 10.0; // last item: prefer filling existing bins
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer packing tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.3;
    score += open_bins_count as f64 * 0.4 * progress;

    // Penalize leaving small unusable gaps (dead space below typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0 - progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 0.8 * p2 + 1.2 * p3);

    let mut score = pr + 15.0 * coupling;

    // Dead-space penalty: small post residuals are wasteful unless perfect fit.
    let tightness = 1.0 - (pr / cap).min(1.0);
    score += 20.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fit_ratio * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins with below-mean residual (conserving large residual bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for spreading across many bins early on.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: make it attractive only for poor fits / very tight residuals.
    if bin_residual == bin_capacity {
        score = pr + 30.0 * (1.0 - progress) - 10.0;
        if post_residual < item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "nice" fractions of C
    // are more reusable. Reward residuals that are multiples of common item
    // granularity (10/20/25/50), penalize awkward odd residues.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity class of post_residual
    let frac = pr / cap;
    if frac <= 0.05 {
        score -= 30.0; // near-perfect fill
    } else if frac <= 0.10 {
        score -= 18.0;
    } else if frac <= 0.25 {
        score -= 6.0;
    } else if frac >= 0.5 {
        score += 10.0; // wasteful large leftover
    }

    // Modulo arithmetic: residuals divisible by 10 or 25 are "harmonic"
    let r = post_residual;
    if r % 10 == 0 {
        score -= 8.0;
    }
    if r % 25 == 0 {
        score -= 5.0;
    }
    if r % 2 == 1 && r > 3 {
        score += 4.0; // odd dead space is hard to fill
    }

    // Lookahead coupling: can next_item_size exactly fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot follow here: penalize more when leftover small
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (1.0 - over / cap);
        }
    } else {
        // last item: just fill as much as possible
        score -= 15.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it mildly attractive only when open
    // bins are crowded (mean residual low) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (mean_residual / cap).min(1.0);
        score = cap * 0.5 + 30.0 * crowding - 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Small global tie-breaker: prefer filling bins among many open ones
    score -= 0.05 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in the post residual, mild penalty for stranding space.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure;

    // New-bin candidate handling: only attractive when item leaves a large,
    // reusable residual or no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; penalize moderately so tight fits in open
        // bins win, but allow opening when fits are poor.
        score += 15.0;
        if post_residual >= 20 && post_residual <= 50 {
            score -= 10.0; // leaves a versatile mid-size residual
        }
        if post_residual < 10 {
            score += 20.0; // opening a bin for a near-full item wastes it
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to item
    // needs (tight packing) rather than outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Stream progression: late in the stream, be slightly more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

