    // fills the post residual (creating zero dead space across two placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-step chain, extremely desirable
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the leftover
            let chain_use = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 20.0 * chain_use;
            // penalize leaving a sliver the next item barely fits into
            let after_next = post_residual as i64 - next_item_size as i64;
            if after_next > 0 && after_next < 10 {
                score += 15.0; // tiny dead sliver after chaining
            }
        } else {
            // next item will NOT fit here: this bin's leftover is likely dead space
            score += 12.0;
            // extra penalty if the leftover is small and unusable
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // last item: just minimize leftover
        score += 5.0;
    }

    // Compare against mean residual: placing in a bin far below mean residual
    // (already tight) is good; placing in a large-residual bin wastes capacity.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish base, penalize opening new bins when
    // open bins are few or the stream is early (amortize open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // opening a new bin is attractive if no open bin fits well
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain with next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Reward bins whose residual exactly matches the item (perfect fit).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that likely can't host the next item: penalize.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so when
    // open bins exist that fit well (fitting_bins_count > 0).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Global state coupling: prefer bins below mean residual when many bins open.
    let resid = bin_residual as f64;
    if open_bins_count > 1 {
        score += 0.15 * (resid - mean_residual);
    }

    // Prefer fuller bins (smaller residual) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.2 * resid;

    // Penalize leaving residuals that no plausible item (>=1) can use well:
    // tiny residuals are near-dead space.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger as stream progresses
    score -= item_size as f64 * (0.5 + progress) * (1.0 - norm_pr * norm_pr);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residue classes modulo 10
    let class = post_residual % 10;
    // Dead-space penalty: residuals that are "awkward" (nonzero, small, not
    // matching typical item sizes) get pushed up.
    let awkward = match class {
        0 => 0.0,          // clean multiple of 10
        1 | 2 | 3 => 12.0, // tiny slivers, nearly unusable
        4 | 5 | 6 => 6.0,  // medium slivers
        _ => 3.0,          // 7..9, can still host small items
    };
    score += awkward;

    // Fraction-of-capacity harmonic ladder: how close post_residual is to a
    // capacity fraction (1/4, 1/2, 3/4) — those are reusable classes.
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    let threeq = (3 * bin_capacity / 4) as f64;
    let pr = post_residual as f64;
    let dist = (pr - quarter).abs().min((pr - half).abs()).min((pr - threeq).abs());
    score += 0.4 * dist;

    // Integer-division threshold: post_residual / 10 buckets
    let bucket = post_residual / 10;
    if bucket <= 1 {
        score += 15.0; // very small residual = dead space
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64; // keep chain going
            // harmonic bonus if post_residual is an exact multiple of next item
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // this bin becomes dead after placement
        }
    }

    // Last-chance bonus: only one bin can fit; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer reusing an open bin unless it's a great fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened if the item is large
        score = (bin_capacity - item_size) as f64 + 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // next item can join the fresh bin
        }
    }

    // Stream-phase modulation: late in stream, be frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Tie-break toward bins with low mean residual (fill emptier bins first).
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Penalize large wasted gaps that no typical item can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item almost fits (small gap), mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fit relative to fleet).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: neutral-ish baseline, penalized when open bins exist
    // and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 35.0;
        } else if open_bins_count > 0 {
            score += 10.0;
        }
    }

    // Progress-based mild tightening: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: prefer bins that are nearly filled exactly.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * residual_frac * residual_frac;

    // 2-step lookahead: reward when post_residual can host next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect two-item fill is excellent.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.35 * dead;
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer them.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0) - 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        score += 55.0 - 10.0 * open_pressure;
        // If next item is small, a fresh bin is fine.
        if next_item_size <= 20 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: encourage filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - residual_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 2.0 * (1.0 - tightness) * (1.0 - tightness) * (item_size as f64);

    // Penalize dead space that can never be used by the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx * 0.5 && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / nx.max(1.0));
        } else if post_residual as u32 >= next_item_size {
            // Reward bins that can also host the lookahead item exactly.
            let combo = post_residual - next_item_size;
            score -= 4.0 * (1.0 - combo as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure waste minimization.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for wasting the "scarce" bin when alternatives exist.
        score += 3.0 / fitting_bins_count as f64;
    }

    // New-bin candidate handling: only attractive when the item is huge
    // relative to typical residuals or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items late in stream or when mean residual is small.
        let new_bin_bonus = 20.0 * item_frac * item_frac
            + 10.0 * progress
            + 12.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        score -= new_bin_bonus;
        // Discourage new bins when many open bins could absorb the item.
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).sqrt();
        }
        // Never open a new bin for a tiny item early on.
        if item_frac < 0.35 && open_bins_count > 0 {
            score += 25.0;
        }
    }

    // Slight preference for bins whose residual is already below average
    // (consolidate waste into few bins).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 1.5 * (mean_residual - res_f) / bin_capacity as f64;
    } else {
        score += 1.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Mild pressure to use many open bins rather than fragmenting.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Dead-space penalty grows smoothly as stream progresses
    let dead = (norm_post - 0.15).max(0.0);
    score += 40.0 * dead * dead * (0.5 + progress);

    // Reward filling a bin nearly completely
    let fill = 1.0 - norm_post;
    score -= 25.0 * fill * fill * fill * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let snug = (post - nxt) / cap;
            score -= 12.0 * (1.0 - snug * snug);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (norm_post - mean_residual / cap).abs();

    // New-bin candidate: penalize slightly unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: small leftovers (< 10, min item size) are nearly useless.
        if post_residual < 10 {
            score += 60.0;
        }
        // Quantize post_residual into capacity-fraction classes and reward
        // leftovers that are "harmonically useful" (multiples of common sizes).
        let q = post_residual / 10; // class index 0..10
        score += (10 - q) as f64 * 2.0; // prefer bins leaving large usable space

        // Reward leftovers divisible into harmonic chunks (10/20/25/50).
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 6.0; }

        // Lookahead coupling: if the next item fits the post residual exactly,
        // this placement chains beautifully.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size < post_residual {
                let chain_left = post_residual - next_item_size;
                if chain_left < 10 { score += 25.0; } // chain would create dead space
                else { score -= (chain_left / 10) as f64 * 3.0; }
            } else {
                // next item cannot follow here; leftover likely stranded
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let tight = post_residual == 0;
        if tight {
            score -= 100.0; // fresh bin for a full item is fine
        } else {
            score += 120.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += mean_residual * 0.1;
    score -= (bin_residual - post_residual) as f64 * 0.3; // reward filling more now

    // Late-stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot fit the smallest plausible item (size 1),
    // but practically we treat gaps below a threshold as wasteful.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // Tiny slivers: strong penalty proportional to wasted potential.
        score += (10.0 - gap) * 3.0;
    } else if gap == 0.0 {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Penalize gaps that are too small for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin becomes useless for the next item; penalize relative to
        // how close the next item is to fitting elsewhere.
        score += next_item_size as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the next item (chaining placements).
        score -= next_item_size as f64 * 0.3;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    let pressure = open_bins_count as f64 * 0.4;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize opening a new bin, more so when many
        // bins are open or mean residual suggests capacity remains.
        score += pressure + mean_residual * 0.5 + 5.0;
    }

    // Slight preference for tighter fits: reward item consuming a large
    // fraction of the bin's residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Late-stream consolidation: as the stream progresses, prefer closing
    // out bins (zero residual) more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (bin_capacity as f64 - gap) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(4) * 30.0;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 15.0;
        } else {
            // next item cannot follow here: mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: opening a new bin wastes the mean residual of open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how much space is stranded.
        score += mean_residual * 0.5 + 10.0;
        // But if current bin fits are all poor (large post_residual everywhere),
        // opening a fresh bin becomes attractive.
        let poor_fit = if bin_residual >= item_size {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        // For the empty bin itself, post_residual == capacity - item_size;
        // reward it when that residual is small (item nearly fills a fresh bin).
        if post_residual as f64 <= mean_residual {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins with high mean residual: discourage new bins.
        score += open_bins_count as f64 * 2.0;
        let _ = poor_fit;
    }

    // Mild global pressure: when mean residual is high, prefer bins above mean residual
    // (consume the roomiest slack first), keeping tight bins for future small items.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Prefer bins whose post_residual remains "reachable" by typical item sizes (10..80).
    if post_residual >= 10 && post_residual <= 80 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early (t small): prefer tight fits less aggressively; late (t large): strongly prefer small post_residual.
    let w = 0.5 + 2.5 * t * t;
    score += w * (x * x) * cap * 0.5;

    // Smooth penalty for residual that is too small to ever fit a typical item (dead space),
    // modulated by progress: dead space matters more later in the stream.
    let dead = (1.0 - x).max(0.0);
    score += 20.0 * t * (1.0 - dead * dead);

    // Lookahead coupling: reward if next item fits into post residual (smooth quadratic term).
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let fits = (x - nx).max(0.0);
        let miss = (nx - x).max(0.0);
        score -= 15.0 * (fits * (1.0 - fits)) ;
        score += 25.0 * miss * miss * (0.5 + t);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x * x);
    }

    // Mild preference to spread load when many bins are open (smooth in open_bins_count).
    score += (open_bins_count as f64).ln().max(0.0) * (x * cap) * 0.05;

    // Deviation from mean residual: prefer bins whose residual is near the mean (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // New-bin candidate: penalize opening a new bin unless residual would be perfectly usable,
    // with penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - t) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in a
    // "reusable" class (large enough to hold small future items) are rewarded.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual >= quarter {
        score -= 6.0; // leftover stays broadly useful
    } else if post_residual >= eighth {
        score += 4.0; // awkward mid-range dead space
    } else if post_residual == 0 {
        score -= 12.0; // perfect fill
    } else {
        score += 10.0; // tiny unusable sliver
    }

    // Modulo-class penalty: post_residual that is NOT congruent to any
    // plausible item size (mod 10 classes) is harder to fill.
    let mod_class = (post_residual % 10) as f64;
    score += 0.4 * mod_class;

    // Integer-division threshold: leftover can hold next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward chains where next item also fits this bin
            score -= 5.0;
            // extra reward if next item exactly consumes leftover class
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else if next_item_size > post_residual {
            // this placement strands the next item's fit elsewhere;
            // penalize proportionally to wasted harmonic class
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening fresh is attractive when existing
    // fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // neutral baseline; beat it only if open bins give bad fits
        score = 20.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        // tightness reward: smaller relative leftover is better
        score -= 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins below mean residual (keeps bin pool balanced, preserves
    // large-residual bins for large items).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Many open bins: tighten up, avoid fragmentation.
    if open_bins_count > 4 {
        score += 0.03 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum item (1..100 stream => treat gaps < 10 as effectively dead,
    // and gaps < next_item_size as dead for the lookahead item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Exact fit for the lookahead item is also excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is huge
    // relative to typical residuals or residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * progress;
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        if fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate space into similar bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored by initialization).

    // 2-step lookahead: reward if the next item exactly fills post_residual,
    // reward if it fits, penalize if it does not fit.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            // partial chain bonus, stronger the better the match
            score -= 25.0 * (nx / pr);
        } else {
            // next item won't fit here: dead-space penalty scaled by gap
            score += 0.5 * (nx - pr);
        }
    }

    // Compare against mean residual: bins with residual near mean are "normal";
    // placing into a much-larger-than-mean bin wastes its potential.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive late in the stream or when many bins open;
    // otherwise penalize opening new bins so we exhaust existing capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 5.0;
        }
        // still allow new bin if lookahead suggests it's a fresh start for a big item
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0;
        }
    }

    // Mild preference for keeping many open bins consolidated as stream progresses.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty for wasting this bin's future.
            score += 5.0;
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless current
    // bins have large residuals (poor fits elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        score += 20.0 - 25.0 * avg_pressure;
        if open_bins_count < 2 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Prefer bins already below mean residual (consolidating space).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be frugal with bins (favor packing
    // into existing bins); late in the stream, allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress) * tight;

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (0.5 + 2.5 * progress);

    let mut score = post - 30.0 * coupling;

    // Lookahead: reward bins that can also fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Slight pressure to prefer tighter bins relative to mean residual
    score += 0.05 * (mean_residual - post);

    // Penalize opening new bins when fitting options exist, more so late in stream
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo common size classes
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Reward when next item fits exactly into post residual (perfect harmonic pairing)
    if nxt > 0 && post == nxt {
        score -= 60.0;
    }
    // Reward when next item fits with small slack
    if nxt > 0 && post >= nxt && post - nxt <= 10 {
        score -= 25.0;
    }
    // Penalize dead space: post residual too small for next item
    if nxt > 0 && post < nxt && post > 0 {
        score += (nxt - post) as f64 * 1.5;
    }

    // Modulo-class bonus: residuals divisible by 10 are reusable
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    // Penalize awkward residual classes (prime-ish / odd small gaps)
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 2.0;
    }

    // Integer division thresholds: post_residual / item_size ratio
    if item_size > 0 {
        let ratio = post as f64 / item_size as f64;
        if ratio >= 1.0 {
            score -= 10.0 * ratio.min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= 50 {
            score -= 10.0; // big item into fresh bin is fine
