        if next <= pr {
            let slack = (pr - next) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * ((next - pr) / cap);
        }
    }

    // Mild penalty when many bins are open and this one is already tight.
    let open_norm = (open_bins_count as f64 / 20.0).min(1.0);
    score += 5.0 * open_norm * norm_pr;

    // New-bin candidate: discourage opening a new bin unless it genuinely looks best.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress + 0.3 * mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill is divine, small dead space is cursed.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score += 25.0; // dead space too small for min item
    } else if pr <= 20 {
        score += 8.0;
    } else if pr <= 30 {
        score += 2.0;
    }

    // Modulo-class coupling: residual divisible into fine classes pairs well with
    // next item's residue class.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            // next item fits here: strong reward, scaled by tightness of that fit
            let tight = 1.0 - ((pr as f64 - nxt) / cap);
            score -= 20.0 + 25.0 * tight;
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 0.3 * (nxt - pr as f64).min(60.0);
        }
        // modulo-10 harmonic class match
        if (pr % 10) == (next_item_size % 10) && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate: neutral-ish baseline, penalize mildly so only genuinely
    // bad fits in existing bins trigger a new bin; worse when many bins are open.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64 + 0.2 * mean_residual;
        // late in stream, opening new bins is less attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Prefer packing into bins with small residual overall (tight packing).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Integer division threshold: residual in [40,60] is the most reusable band.
    if pr >= 40 && pr <= 60 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (min size 1..100 unknown; treat < 20 as near-dead) are heavily penalized.
    if post_residual > 0 {
        let dead = (20u32.saturating_sub(post_residual)) as f64;
        score += 3.0 * dead.max(0.0);
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // with few open bins, allow consolidation elsewhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if this bin would otherwise leave a bad gap in an existing bin,
        // opening fresh may win: soften when mean residual is small.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the gap: penalize proportional dead space.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Mild preference for fuller bins relative to mean residual.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64 - (mean_residual - post_residual as f64)).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good, but only if not creating dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            // Perfect chaining: this placement sets up a perfect next placement.
            score -= 40.0;
        } else if nxt <= post {
            // Next item fits: good, reward proportional to how snugly.
            score -= 20.0 * (nxt / (post + 1.0));
            // Extra reward if it leaves near-zero residual after the next item.
            let second_post = post - nxt;
            score -= 15.0 * (1.0 - second_post / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin: penalize depending on wasted gap.
            let gap = nxt - post;
            score += 5.0 + gap.min(60.0) as f64 * 0.4;
        }
        // If next item also fits residual directly (no placement needed here), mild bonus.
        if next_item_size as u32 <= bin_residual {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: placing into a bin with residual below mean
    // concentrates waste, which is good; penalize placing into already-loose bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for opening new bins late in the stream is discouraged;
    // early stream: new empty bins are cheaper to open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, cheaper early, expensive late.
        score = 55.0 + 45.0 * progress;
        // If no open bin fits at all, opening is unavoidable-ish; reduce penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Lookahead on new bin: if next item is small, a fresh bin is attractive.
        if next_item_size > 0 && (next_item_size as f64) <= 0.5 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill * fill;
    }

    // Penalize very small post-residuals that become dead space only mildly,
    // but heavily penalize mid-range waste (10..40) that nothing small can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // perfect-ish fit bonus
    } else if post_residual >= 10 && post_residual <= 40 {
        score += 0.35 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item cannot use leftover: penalize proportional to leftover size
            score += 0.2 * (post_residual as f64);
        }
    }

    // New-bin candidate handling: empty bin should win only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and
        // how many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If the mean residual across open bins is large, opening new bins is wasteful.
        score += 0.4 * mean_residual;
        // If the next item is small, a fresh bin has flexible future; slightly cheaper.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 8.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        if progress > 0.8 {
            score += 25.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer compacting.
    if open_bins_count > 3 && mean_residual < 30.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Slight preference for bins tighter than average.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth polynomial shaping of tight fits.
    let mut score = pr - 24.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; late in the stream demand tight packing.
    let late_pressure = progress * progress;
    score += 18.0 * late_pressure * norm_pr;
    score -= 10.0 * (1.0 - late_pressure) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Interaction: next item fits well into post-residual -> reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = nxt / pr.max(1.0);
        let closeness = 1.0 - (fit_ratio - 1.0).abs().min(1.0);
        score -= 14.0 * closeness * (1.0 - late_pressure);
        // Penalize post-residual that is too small for the next item (dead space).
        if nxt > pr {
            score += 8.0 * (1.0 - pr / nxt) * (1.0 + late_pressure);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Deviation from mean residual: prefer bins with less slack than average.
    score += 3.0 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 12.0 * late_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "composable" classes (multiples of 10 / small dead space) are favored.
    let post = post_residual;
    let class = post % 10;
    // Penalize leftover classes that tend to become dead space (1..=9 non-zero
    // odd fragments), reward exact multiples of 10.
    if class == 0 {
        score -= 12.0;
    } else if class <= 3 {
        score += 6.0;
    } else if class >= 7 {
        score += 14.0;
    } else {
        score += 9.0;
    }

    // Integer-division threshold: how many size-10 slots remain after placement.
    let slots = post / 10;
    score -= 2.5 * slots as f64;

    // Perfect-fill reward: item exactly closes the bin.
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward when next_item_size fits harmonically into
    // the post residual (integer division zero remainder).
    if next_item_size > 0 && post > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if post % next_item_size == 0 {
            score -= 15.0;
        } else if next_item_size <= post {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
    }

    // Phase of stream: later, prefer tighter packing (weight residual more).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * phase;

    // Slight pull toward bins near the mean residual (balanced packing).
    score += 0.1 * (post as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 25.0; // nearly dead space
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: bonus if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item cannot use leftover space
        }
    }

    // Open bins pressure: discourage spreading across many bins early,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Prefer bins tighter than the mean residual (consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
