pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear penalty for large dead space that nothing may fill later
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: penalize if next item cannot use the post_residual (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = pr - nx;
        let mismatch = (slack / cap).abs();
        if slack < 0.0 {
            score += 6.0 * mismatch * (1.0 - progress);
        } else {
            score += 4.0 * mismatch * mismatch;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: prefer bins close to the mean (smooth diversity term)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: neutral baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize leftovers by class: tiny leftovers (<5) are dead space, huge leftovers are fine.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 4 {
        score += 25.0; // near-dead space
    } else if post_residual <= 10 {
        score += 12.0;
    }

    // Class bins by quarter of capacity: leftover in (0,25] is hard to reuse.
    if frac > 0.0 && frac <= 0.25 {
        score += 18.0 * (1.0 - frac * 4.0); // smaller leftover in this band is worse
    } else if frac > 0.25 && frac <= 0.5 {
        score += 6.0;
    } else if frac > 0.5 {
        score -= 10.0; // roomy leftover, easy to reuse
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward: this placement chains with the next item
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 - chain_waste * 0.3;
        } else {
            // next item won't fit here; penalize more if leftover is small (unusable)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    } else {
        // last item: just fill as much as possible
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Modulo-class harmonic: leftover congruence classes mod 10.
    let m = post_residual % 10;
    score -= match m {
        0 => 8.0,
        1 | 9 => -2.0,
        2 | 8 => 0.0,
        3 | 7 => 2.0,
        4 | 6 => 3.0,
        _ => 1.0, // 5
    };

    // Mild bias toward bins with residual above item (tight fits) via integer division threshold.
    if post_residual / item_size.max(1) == 0 {
        score -= 5.0; // item dominates the bin, good packing
    }

    // Slight preference to spread across many open bins when mean residual is high.
    score -= mean_residual * 0.05 + (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
