        }
    }
    // Penalize if the gap can't host the next item (dead space relative to lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; encourage consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: mild penalty so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If no open bin fits (this is the only candidate), the penalty is offset by last-chance logic;
        // also offset when mean residual of open bins is very small (all bins are tight).
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
    }

    // Prefer bins tighter than average (best-fit refinement).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits (small post_residual is good, but a post_residual
    // that exactly accommodates the next item is even better).
    if next_item_size > 0 && post_residual >= next_item_size {
        // 2-step lookahead: perfect chain match gets a big bonus.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item fill
        }
    } else if next_item_size > 0 {
        // post_residual cannot host the next item: penalize proportional dead space.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Penalize leaving residuals that are likely unusable (very small leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless the current bin residual is huge.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // fresh bin can still chain with next item
        }
    }

    // Late in the stream, consolidate harder (fewer new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual against item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 4.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoiding bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving a dead zone: post_residual too small for the smallest
    // plausible future item (sizes >= 1, but waste < ~10 is nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // reward heavily; if next item cannot fit into post_residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about filling
    // bins poorly (many items remain); later, accept tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins (penalize opening new bins).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 12.0 + open_bins_count as f64 * 1.5;
        // If mean residual across open bins is high, opening new bins is wasteful.
        score += mean_residual * 0.15;
        // But if open bins are nearly full (low mean residual), a new bin is fine.
        score -= (bin_capacity as f64 - mean_residual) * 0.05;
    } else {
        // Existing bin: slight reward proportional to how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 6.0;
        // Reward using bins when many bins are open (reduce fragmentation).
        score -= open_bins_count as f64 * 0.3;
    }

    // Exact fit is ideal regardless of anything else.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: tighten bin selection as stream advances
    let progress_coupling = 1.0 + 0.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Reward filling relative to mean residual across open bins
    score -= 0.3 * (mean_residual - post) / cap;

    // Penalize dead space that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 2.0 * gap * gap;
        // Bonus when post_residual exactly accommodates next item
        let fit_next = (post - next_item_size as f64).abs() / cap;
        score -= 0.5 * (1.0 - fit_next.min(1.0));
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - progress);
        score -= 1.5 * progress;
    }

    // Mild penalty for opening new bins when many are open and progress is late
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // But allow new bin if post_residual would be perfect for next item elsewhere
        if next_item_size > 0 && post_residual == 0 {
            score -= 1.0;
        }
    }

    // Waste-fraction polynomial: penalize large leftover fractions non-linearly
    let waste_frac = norm_post;
    score += 4.0 * waste_frac * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small unusable" classes are rewarded (dead space minimized).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score -= 40.0; // nearly-perfect: leftover likely unusable anyway
    } else {
        // modulo classes: leftover divisible by common item sizes is reusable
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 12.0;
            }
        }
        // penalize awkward leftovers in (10, 20) range — too small for most items
        if pr > 10 && pr < 20 {
            score += 15.0;
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: leftover divisible by next item is ideal
            if pr % next_item_size == 0 {
                score -= 30.0;
            } else {
                score -= (pr - next_item_size) as f64 * 0.3;
            }
        } else {
            // next item won't fit here: leftover becomes dead space
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tighter bins when many bins are open
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive if nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += pressure + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are wasted capacity.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 35.0; // unusable sliver gap
    } else if post_residual <= 20 {
        score += 12.0; // likely dead space (min item ~10)
    }

    // Lookahead coupling: a gap that cannot host the next item is dead space.
    if post_residual > 0 && next_item_size > post_residual {
        score += 18.0;
        if post_residual <= 15 {
            score += 10.0; // doubly unusable
        }
    } else if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0; // gap remains useful for the lookahead item
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize the brand-new empty bin candidate more
    // as the number of open bins grows (consolidate before expanding).
    if bin_residual == bin_capacity {
        score += 20.0 + 4.0 * open_bins_count as f64;
    }

    // Mild mean-residual alignment: prefer bins whose residual is near the mean
    // to keep the pool of usable gaps balanced.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Slight late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-perfect match: next item fits with little waste
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack / 10.0);
    }
    // Next item will not fit here: penalize proportionally to dead space risk
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize residuals too small to be useful for any plausible item (min size 1)
    if post_residual < 5 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average (good packing)
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive late in the stream or when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score += 8.0 + 12.0 * (1.0 - progress) - crowding.min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Chain fit: exact pairing bonus
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // New-bin candidate: discourage opening a new bin unless current item is large
    // or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = (bin_capacity - item_size) as f64 + 20.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // if item is huge and nothing fits well, new bin is fine
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count == 0 {
