        }
        // opening new bins early can be strategic when many small items remain
        if progress < 0.3 && item_size < 30 {
            score -= 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor filling them.
    if open_bins_count > 4 && mean_residual > (item_size as f64) {
        score -= 3.0;
    }
    // Penalty proportional to leaving residual far from mean (fragmentation control)
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * poly * (1.0 + progress);
    // Reward tight fits more as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);
    // Penalize dead space: small unusable residuals
    let next = next_item_size as f64;
    if next > 0.0 {
        if pr < next {
            score += 8.0 * (next - pr) / cap;
        } else {
            score -= 5.0 * (pr - next) / cap;
        }
    }
    // Last-chance bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }
    // Mildly discourage new bins when many open bins have room
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }
    // Coupling with mean residual: prefer bins deviating from mean (balance)
    score += 0.1 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes w.r.t. capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residuals in "dead" harmonic classes (hard to fill later).
    let dead_class = post_residual % quarter;
    if post_residual > 0 && dead_class < 5 {
        score += 12.0; // near-zero modulo quarter => awkward sliver
    }
    if post_residual % 10 < 3 && post_residual < eighth {
        score += 10.0; // tiny unusable residue
    }

    // Reward residuals that sit on nice harmonic boundaries (divisible by 10/20).
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 {
        score -= 4.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here: penalize small leftovers more
            score += (post_residual as f64).min(20.0) * 0.3;
        }
    }

    // New-bin candidate handling: only open a new bin when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; attractive when existing fit is wasteful.
        score = (bin_capacity as f64) * 0.55
            - (fitting_bins_count as f64) * 2.0
            - (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 5.0;
        }
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
    }

    // Progress-aware mild tightening late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

