    if bin_residual < bin_capacity {
        score -= 0.35 * (bin_capacity - bin_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to spread pressure via open_bins_count.
    if fitting_bins_count > 1 {
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
