    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.08 * pressure;

    // New-bin candidate handling: only attractive when no tight fit exists.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        // If the mean residual barely fits the item, prefer a fresh bin.
        if mean_fit_gap < 5.0 {
            score -= 30.0;
        } else {
            score += 15.0 + 0.5 * mean_fit_gap;
        }
        // Late in the stream, opening new bins is riskier.
        score += 20.0 * progress;
    }

    // Lookahead: avoid leaving a gap that wastes the next item's placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // residual stays usable for the next item
        } else if post_residual > 0 {
            score += 10.0; // residual becomes dead space relative to next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_waste = post_residual - next_item_size;
        score -= 25.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving residuals that no plausible next item can use (dead space).
        if post_residual < 10 {
