    // Compare post_residual to mean residual: penalize making this bin an outlier of wasted space.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
