    // Early in the stream, be more willing to open new bins (keep residuals flexible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 15.0 * progress; // new-bin candidate: cheap early, costly late
    } else {
        score -= 3.0 * progress; // prefer filling existing bins as stream matures
    }

    // Mild preference for tighter bins among equals.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
