    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        // Open a new bin if existing bins are congested; otherwise penalize.
        let congestion = avg_fullness * (open_bins_count as f64).ln_1p().max(0.5);
        score += 40.0 - congestion * 35.0 + (1.0 - progress) * 5.0;
        // Never open a new bin when a near-perfect fit exists.
        if post_residual == 0 || (next_item_size > 0 && next_item_size >= post_residual && post_residual < 12) {
            score += 60.0;
        }
    }

    // Mild preference for bins tighter than the current mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Time-horizon modulation: late in the stream, waste is costlier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * fit_norm * fit_norm);
    // penalize large dead space quadratically, scaled by progress
    score += 0.35 * pr * pr / cap * (0.5 + progress);
    // reward tight fits (small post_residual) more strongly as stream advances
    score -= (cap - pr) / cap * 12.0 * (0.3 + 0.7 * progress);
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - fit_norm);
    }
    // lookahead: bonus if next item fits the resulting residual exactly-ish
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }
    // mildly prefer consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * fit_norm;
    // new-bin candidate: make it moderately attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score = 10.0 + 20.0 * frag * (1.0 - progress) - 8.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "dead zones" (very small) are bad.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual (harmonic classes of C/16)
    let class = post_residual / (bin_capacity / 16).max(1);
    let class_penalty = match class {
        0 => 40.0,                 // 0..6  : nearly dead space
        1 => 18.0,                 // tiny sliver
        2 => 4.0,                  // usable for very small items
        3 | 4 => -6.0,             // sweet spot for small items
        5 | 6 => -10.0,            // mid residual, very reusable
        7 | 8 => -4.0,             // half-ish capacity
        _ => 2.0,                  // large residual: fine but less urgent to fill
    };
    score += class_penalty;

    // Modulo-arithmetic harmony: does the post residual pair well with the
    // next item (lookahead)? Reward when next item fits exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // perfect / near-perfect follow-up fits
            if slack == 0 {
                score -= 30.0;
            } else if slack <= bin_capacity / 16 {
                score -= 15.0;
            } else {
                score += slack as f64 * 0.25;
            }
        } else {
            // next item cannot follow here: mild penalty scaled by overshoot
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // Harmonic pairing: next_item_size near a divisor-class of residual
        let nclass = next_item_size / (bin_capacity / 16).max(1);
        if (nclass + class) % 2 == 0 {
            score -= 3.0; // complementary harmonic classes
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (would leave open bins fragmented) or nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // Large items fragment small residuals anyway; allow new bin more readily
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0; // reserve space for a big follower
        }
        // Late in the stream, prefer consolidating into open bins
        score += progress * 15.0;
        // If many bins already fit the item, opening new is wasteful
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 8.0;
        }
    }

    // Prefer tighter bins overall (fill fuller bins first)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;
    // Slight bonus when this bin is below the mean residual (i.e. fuller)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Penalize gaps too small for the lookahead item (dead space for next step).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward exact-ish fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer consolidation into existing bins
    // (penalize opening new bins / spreading).
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins).
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Slight late-stream tightening: keep gaps small as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Penalize new empty bin candidate mildly unless it's a near-perfect split.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size % 10 == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post-residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0 + item_size as f64 * 0.5;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 4.0;
        } else {
            // Penalize residuals that are large but not matchable by next item.
            score += diff * 0.15;
        }

        // Chain feasibility: next item must also be placeable in what remains after this placement.
        if next_item_size > post_residual {
            // Next item can't use this bin anyway; mild penalty scaled by wasted residual.
            score += 0.1 * (post_residual as f64);
        }
    }

    // Reward filling bins tightly relative to mean residual (avoid spreading load).
    if (post_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable dead space (< 10) unless it's a near-perfect fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-full bin is good
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) / (1.0 + step_index as f64);
        // Prefer new bin early or when open bins are crowded (mean residual low).
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        } else {
            score += 10.0 + 20.0 * open_pressure.min(1.0);
        }
    }

    // Mild progression bias: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight fit reward: penalize large post_residual relative to capacity
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * tightness * tightness;
    }

    // New-bin candidate handling: only prefer opening a new bin when the item
    // is large and fits poorly in existing bins (would create dead space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.55 && post_residual > 0 {
            // Large item alone in a fresh bin is often good (avoid splitting)
            score -= 25.0 * fit_ratio;
        } else {
            // Small/medium items should reuse open bins when possible
            score += 60.0;
        }
        // Discourage hoarding bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // Lookahead: if the next item can use the post_residual exactly, reward it
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item still fits after placement: mild reward
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving awkward residue
            score += 8.0;
        }
    }

    // Prefer bins whose residual is below the mean (packing tight bins first)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Prefer bins with small residual overall (best-fit bias), non-linear
    if bin_residual < item_size {
        score += 500.0; // should not happen (bin can't fit), safety guard
    }

    // Time-horizon coupling: late in the stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: tightness of the fit, with non-linear sharpening so near-perfect
    // fits are strongly preferred over merely acceptable ones.
    let pr = post_residual as f64;
    let mut score = pr + (pr / cap).powi(3) * 60.0;

    // Smooth polynomial coupling with stream progress: early on, keep bins
    // flexible (penalize small residuals mildly); late, pack tightly.
    let flexibility = (pr / cap) * (1.0 - progress) * 40.0;
    score += flexibility;

    // Interaction term: progress * post_residual^2 rewards tight packing as
    // the stream advances (smooth non-linear coupling).
    score += progress * (pr / cap).powi(2) * 30.0;

    // Lookahead: if the next item fits exactly into the post residual, reward
    // this placement strongly (smooth bell around zero slack).
    if next_item_size > 0 {
        let slack = post_residual as i64 - next_item_size as i64;
        if slack >= 0 {
            score -= 25.0 * (1.0 - (slack as f64 / cap)).powi(2);
        } else {
            // Next item cannot use the leftover; mildly penalize large leftovers.
            score += (-slack as f64 / cap) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the bin that wastes the least, but avoid
        // fragmenting the single most flexible bin.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: only attractive when it fits better than anything
    // open, or when open bins are badly fragmented. Penalize mildly by default
    // so open bins are used; reward when mean residual is low relative to item.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / cap);
        score += 15.0 - fragmentation * 30.0 + progress * 10.0;
    }

    // Slight penalty for bins far below mean residual (keeps a balanced pool).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod capacity fractions.
    // Residuals that are "usable" (>= 10, or divisible into common slots) are penalized less.
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    // Residues 0 are perfectly reusable; small residues 1..=9 are dead space
    score += match class {
        0 => -5.0,
        1..=5 => (6 - class as f64) * 2.0, // small dead space penalty
        _ => 0.0,
    };

    // Dead-space penalty: residuals too small for the minimum item size
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Harmonic divisibility: post_residual divisible by next_item_size => next item fills it exactly
    if next_item_size > 0 {
        if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 15.0;
        }
        // If next item fits exactly in post_residual, strong reward
        if pr == next_item_size {
            score -= 30.0;
        }
        // Penalize if post_residual cannot hold next item but is small-ish (wasted)
        if pr < next_item_size && pr > 0 {
            score += (next_item_size as f64 - pr as f64) * 0.5;
        }
    }

    // Integer division threshold: post_residual in "half bin" class
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr == half {
        score -= 8.0; // half-empty bin is a nice reusable state
    } else if pr < quarter && pr > 0 {
        score += 10.0; // awkward sliver
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless current fits are bad
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduced late in the stream or when few bins fit
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 40.0 - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for fuller bins early on
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Softer penalty for gaps too small to fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    }
    // Reward perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = (open_bins_count as f64) * (0.3 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + new_bin_penalty;
    } else {
        score -= 2.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if the lookahead item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

