        // Perfect chain match: next item exactly consumes post_residual.
        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            // Proximity bonus: closer post_residual to next_item_size is better.
            score -= 200.0 / (1.0 + gap / 10.0);
            // Penalize leaving dead space the next item cannot use.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
