        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Penalize bins whose residual deviates below the mean (wasting capacity elsewhere).
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Discourage opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 60.0; // new bin could still be chained, but prefer reusing
        }
    }

    // Slight preference for larger fill (smaller post_residual) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
