    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many fitting bins: mild penalty for consuming scarce large residual.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Time horizon: early on, keep residuals flexible; late, just pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if open bins are mostly empty (high mean residual),
    // discourage opening yet another bin; if residuals are low, allow new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base score equals post_residual = capacity.
        let pressure = mean_residual / (bin_capacity as f64);
        score -= 20.0 * pressure; // when open bins are full-ish, new bin is cheap
        if fitting_bins_count == 0 {
            score -= 15.0; // forced option
        } else {
            // Only open new bin if existing fits are bad (large post_residual elsewhere).
            score += 6.0 * (1.0 - pressure);
        }
    }

    // Mild penalty for accumulating many open bins when residuals are small.
    score += 0.02 * open_bins_count as f64 * (1.0 - mean_residual / (bin_capacity as f64)).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;

    // Base: prefer small post-residual, with non-linear quadratic coupling
    let mut score = pr + 40.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 25.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (nxt / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - fit_ratio);
    }

    // Mild penalty when this bin is far from the mean residual (imbalance)
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize slightly unless existing bins are very poor fits
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (1.0 - item_size as f64 / cap);
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: partition post_residual into capacity fractions.
    // Residuals in a "dead" class (too small for typical future items) are penalized.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual < eighth {
        score += 25.0; // tiny dead space, nearly unusable
    } else if post_residual < quarter {
        score += 10.0;
    } else if post_residual < half {
        score -= 3.0; // usable half-class
    }

    // Integer-division harmonic classes on post_residual: multiples of 10 align
    // with the common item-size lattice, making residual reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0);
            if slack == 0 {
                score -= 20.0; // chained perfect fit
            }
        } else {
            // next item won't fit here: residual becomes terminal; penalize if large
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to typical residuals or no good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 20.0;
        // if many bins fit the item, discourage opening a new one
        score += fitting_bins_count as f64 * 8.0;
        // large items pair well with a fresh bin (room for next_item too)
        if item_size >= half {
            score -= 10.0;
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 10.0;
            }
        }
    }

    // Stream progression: early on, be conservative about dead space;
    // later, tighter fits matter more since mean residual rises.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mild penalty when this bin's residual is far below mean (fragmented bin)
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty scales with how "unusable" the gap is relative to
    // the next item: if the leftover cannot host the lookahead item, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 3.0 * gap.min(30.0);
    }
    // But if the leftover exactly hosts the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; encourage
    // filling existing bins so fewer bins stay open.
    let pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 0.6 * pressure;
    } else {
        // New empty bin candidate: penalize slightly more when many bins open,
        // less when few (opening may still be right for tiny items).
        score += 0.8 * pressure;
        // Opening a new bin is attractive only if the item is small enough
        // that the resulting residual stays broadly reusable.
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    // Match against mean residual: bins whose residual is near the mean are
    // "typical" slots; deviating bins (very tight) should be drained first.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if bin_residual < bin_capacity {
        score -= 0.3 * dev.min(50.0);
    }

    // Stream progression: early on, allow opening bins more freely; late in
    // the stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt) / bin_capacity as f64;
            // Reward small gap (post_residual ≈ next_item_size).
            score -= 120.0 * (1.0 - gap);
            // Penalize dead space that next item cannot use.
            score += 0.6 * gap * post;
        } else {
            // Post residual too small for next item: dead space penalty,
            // softened if it was already a tight fit for the current item.
            score += 40.0 * (nxt - post) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (relative tightness coupling).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 80.0 - 60.0 * pressure - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if post_residual == 0 { score += 30.0; } // fresh bin stays pristine
    }

    // Mild stream-progression bias: consolidate more as stream ends.
    score *= 1.0 - 0.05 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space: post-residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item can use this bin's post-residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 18.0;
    }
    // Penalize if post-residual would block the next item while other bins could chain.
    if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how many bins already fit the item.
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 10.0 * (fitting_bins_count as f64).ln().max(1.0) };
        score += fit_pressure;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += (mean_residual / cap).clamp(0.0, 1.0) * 25.0;
        // Exception: big items with no good fit elsewhere — soften penalty.
        if item_size as f64 > 0.6 * cap && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Slight preference for fuller bins (larger item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Mild global load balancing: many open bins -> favor bins below mean residual.
    if open_bins_count > 1 {
        score += 0.15 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear quadratic coupling: penalize residual that is either too small
    // (wasted bin) or awkwardly large relative to capacity, modulated by progress.
    let norm = pr / cap;
    let curve = norm * (1.0 - norm); // peaks at half-full residual
    score += 30.0 * curve * (1.0 + progress);

    // Reward tight fits with smooth exponential decay of post_residual.
    score -= 12.0 * (-(pr / cap) * 4.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive when few bins fit or item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let big_item = item_size as f64 / cap;
        score -= 20.0 * scarcity * big_item * (1.0 + progress);
    } else {
        // Prefer bins whose residual deviates smoothly from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev * dev;
        // Encourage matching residual to next item for lookahead synergy.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Mild pressure to close out bins as the stream progresses.
    score += progress * (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect-fit classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 60.0; // near-perfect residual, hard to reuse
    } else if pr <= 20 {
        score += 15.0;
    } else if pr <= 35 {
        score -= 20.0; // usable mid-window
    }

    // Modulo-class dead space: residuals that few item sizes can fill are bad.
    let class = pr % 10;
    if class != 0 && class < 3 {
        score += 25.0; // awkward small remainder
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 10.0; // round residual, likely reusable
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0; // chains perfectly
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 40.0 - (gap as f64).min(40.0); // reward closeness
        } else {
            score += 30.0; // next item won't fit here
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin is very full already.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 100.0 - 15.0 * progress; // later in stream, more willing to open
        score = threshold + mean_residual * 0.5 + open_bins_count as f64 * 0.5;
        if item_size > 70 {
            score += 10.0; // big item into fresh bin is fine, slight nudge
        }
    }

    // Prefer filling fuller bins overall.
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10)
    // can use are pure waste; penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately awkward gap: usable but risky.
        score += 25.0;
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Tightness ratio: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax if no open bin fits well (last-chance handled below).
        score += 30.0 + pressure;
        // If this item would leave a good gap for the next item in a fresh bin,
        // soften the penalty slightly.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using bins, more so under pressure.
        score -= 5.0 + 0.5 * pressure * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if placing here leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 45.0; // next item fits snugly afterwards
        } else {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in the leftover: mild penalty for fragmenting.
        score += 12.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins),
    // leaving emptier bins flexible for future large items.
    if bin_residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 8.0;

    // Exact fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // extra reward if next item almost exactly fills remaining space
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving awkward residual
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: bins with residual near mean are "average" candidates;
    // placing into bins with large residual wastes packing potential
    if bin_residual as f64 > mean_residual + 20.0 {
        score += 8.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when no good open bin exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // if item is large, opening a fresh bin is more reasonable
        if item_size > 50 {
            score -= 20.0;
        }
        // if the next item is large too, fresh bin gives flexibility
        if next_item_size > 50 {
            score -= 10.0;
        }
        // many open bins already: discourage spreading
        if open_bins_count > 5 {
            score += 5.0 * (open_bins_count as f64 - 5.0).min(10.0);
        }
    }

    // Early in stream: slight preference to consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good).
    let tight_fit = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight_fit) * (1.0 - tight_fit);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize slightly more when few bins can fit current item.
        score += 8.0 + 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * open_pressure * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Time horizon: later in the stream, be more conservative (avoid opening new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * progress * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 0.0;
    score -= 10.0 * progress * (1.0 - tight_fit);

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — use it.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // New-bin candidate: penalize opening a new bin unless the item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 35.0 - 20.0 * large_item - 25.0 * poor_options;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * progress * base - 1.2 * progress * base * base;

    // Penalize large dead space more as stream advances
    let dead = (base * base) * (2.0 + 3.0 * progress);

    // Reward tight fits (small post_residual), stronger early
    let tight = -3.0 * (1.0 - base) * (1.0 - base) * (1.0 + progress);

    // Last-chance bin bonus
    let last_chance = if fitting_bins_count == 1 { -2.5 } else { 0.0 };

    // Lookahead: reward leaving room for next item, penalize blocking it
    let look = if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr { -1.5 * (n / cap) } else { 2.0 * (1.0 - pr / n.min(cap)) }
    } else { 0.0 };

    // Slight penalty for bin proliferation relative to mean residual
    let spread = 0.3 * (pr - mean_residual) / cap;

    let mut score = base * poly + dead + tight + last_chance + look + spread;
    // New-bin candidate: mild bias so it wins only when clearly better
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Penalize "dead" residuals that are too small to be useful for typical items (1..100)
    // Residuals < 10 are nearly unusable -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 50 {
        score += 8.0;
    }

    // Reward residuals that are exact harmonic divisions of capacity (perfect future fits)
    // e.g. residual in {0, 20, 25, 33, 50, 100} style classes via modulo checks
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if bin_capacity % post_residual == 0 {
        score -= 15.0; // divides capacity evenly, likely reusable
    }

    // Modulo-class coupling: residual classes of 10 align with typical item sizes
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else {
        score += class as f64 * 0.8; // rougher alignment = slight penalty
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward if next item leaves a harmonic remainder too
            let next_post = post_residual - next_item_size;
            if next_post == 0 || bin_capacity % next_post == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to how close it was
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity (post_residual == 100)
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor fits
        // and the item is large (would create big dead space in a partially filled bin).
        let large_item = item_size as f64 > 0.6 * cap;
        let poor_existing = mean_residual < item_size as f64 * 1.2;
        if large_item && poor_existing {
            score -= 20.0;
        } else {
            score += 30.0; // prefer existing bins generally
        }
    }

    // Mild pressure toward bin consolidation as the stream progresses
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0 * (open_bins_count as f64).ln().max(1.0) * 0.2;

    // Slight preference for bins whose residual is below the mean (tighter bins fill first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
