    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward leaving space that could fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Pressure from number of open bins: prefer tighter bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Slight penalty for deviating from mean residual (balance load).
    score += ((bin_residual as f64 - mean_residual) * 0.05).abs();

    // Mild progression bias: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // New-bin candidate: mild default penalty so it only wins when open bins are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward when next item fills this bin's post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // Next item can fit here afterwards: reward closeness of match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 40.0; // perfect 2-item fill
            }
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.3 * diff;
        }
    }

    // Compare residual against mean residual of open bins: prefer bins tighter than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in the
    // stream or when no good existing option exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more as the stream progresses.
        score += 35.0 + 40.0 * progress;
        // But if next item is large and would leave a fresh bin well-balanced, ease up.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 10 {
            score -= 45.0;
        }
    }

    // Mild pressure against bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.0 * fit_ratio * (bin_residual as f64);

    // Penalize dead space: post_residual that no typical item can use.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 30.0; // tiny dead space is bad
        } else if post_residual < 20 {
            score += 12.0;
        }
    }

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * pair_waste;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally.
        score += 0.15 * (next_item_size as f64 - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let bad_fit = fit_ratio < 0.5;
        let mean_tight = mean_residual < item_size as f64;
        if bad_fit || mean_tight {
            score -= 10.0 + 20.0 * crowding;
        } else {
            score += 15.0 + 10.0 * (1.0 - crowding);
        }
    }

    // Time horizon: late in stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // Prefer filling bins with larger residuals when mean residual is high (fragmentation risk).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild penalty for opening bins when many are already open.
    if bin_residual == bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    // Small post-residuals are great (tight fit) -> subtract; large waste -> add.
    let mut score = pr;

    // Smooth cubic coupling of post_residual with stream progress:
    // early on, waste is more tolerable; late, tight fits matter more.
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 30.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space in a super-linear way (quadratic waste term).
    score += 0.5 * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward using a bin whose post-residual matches the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt) / cap).abs();
        if match_term > 0.0 {
            score -= 12.0 * match_term * match_term;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for scattering across many open bins vs mean residual.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (norm_pr * cap / (mean_residual + 1.0));

    // New-bin candidate: make it attractive only when no good fit exists,
    // via smooth function of mean residual and progress.
    if bin_residual == bin_capacity {
        let pressure = ((mean_residual / cap) * (1.0 - progress)).clamp(0.0, 1.0);
        score = cap - 40.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact quarter divisions are valuable slots.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr == quarter || pr == half || pr == 3 * quarter {
        score -= 25.0; // harmonic slot, easy to refill later
    } else if pr < 10 {
        score += 30.0; // dead space below minimum item size
    }

    // Penalize non-harmonic residue via modulo structure
    let m = pr % quarter;
    if m != 0 {
        score += (quarter - m) as f64 * 0.6;
    }

    // Lookahead coupling: does post_residual fit next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let nx = next_item_size as f64;
            score -= 12.0 * (nx / cap);
            // harmonic match between next item and post-residual class
            if pr % next_item_size.max(1) == 0 { score -= 15.0; }
        } else {
            score += 8.0; // next item can't use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let waste = (post_residual as f64) - cap * 0.5;
        score += 20.0 + waste.max(0.0) * 0.8;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Late in stream: tighten packing, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        // Larger leftovers are mildly penalized proportional to waste potential
        score += (post_residual as f64) * 0.05;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness);

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
