    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // If next item cannot fit post_residual but could fit a fresh bin, penalize less-worsening choice
    if next_item_size > post_residual {
        score += 10.0;
    }

    // New-bin candidate: penalize so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if this is the only option, the last-chance logic already applied to others;
        // soften slightly so new bin is viable when all fits are bad
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Late in the stream: prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact/near-exact chain fits.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact chain match: post_residual == next_item_size -> bin becomes perfectly full.
        if diff < 0.5 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 30.0 - diff * 3.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to tightness.
            score -= 8.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item cannot fit in this bin after placement: penalize.
            score += 6.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Favor tight fits in general (small post_residual relative to capacity).
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Penalize deviating from the mean residual (keep bin population balanced).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Late in the stream, prefer closing bins out tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Never prefer a brand-new empty bin over a reasonable existing fit.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
