        let mut new_bin_penalty = 35.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, opening fresh bins is more costly.
        new_bin_penalty *= 1.0 + 0.5 * progress;
        // If item is large, a fresh bin wastes less potential.
        new_bin_penalty -= 0.2 * (item_size as f64);
        score += new_bin_penalty;
    }

    // Prefer filling bins below the mean residual (balance-aware).
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for bins with small residuals overall (best-fit flavor).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, non-linearly weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space with a smooth cubic term
    score += 30.0 * prn * prn * prn;

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 25.0 * (1.0 - prn) * (1.0 - prn) * progress;

    // Penalize if post residual cannot fit the next item (smooth penalty)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0) / cap;
        score += 20.0 * waste * (1.0 + progress);
