        let gap = (nx - pr).abs() / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - prn);
    }

    // Mild penalty proportional to number of open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * prn;

    // Coupling with mean residual: prefer bins whose residual is below mean (tighter)
    let mr = mean_residual / cap;
    score += 10.0 * (prn - mr) * (1.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
