    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 0.25 * mean_residual;
        if open_bins_count == 0 {
            score = -1000.0; // must open first bin
        }
        // Open a fresh bin when the item is huge and would leave a bad remainder elsewhere.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild preference for bins already below mean residual (keeps balance).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post-residual in (0, 10) is a "dead zone" — nothing can ever fill it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling: penalize leaving gaps that are too small for the known next item
    // but large enough to tempt — they trap the next item elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0;
    }
    // Reward leaving exactly room for the next item.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress)) * 0.4;
    score += pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make empty bins moderately unattractive so we only
    // open when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect next-item match gets a big bonus; decays with slack.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.5 * shortfall;
    }

    // Penalize unusable dead space (post_residual too small for anything typical).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer tight fits: reward small post_residual relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 0.4 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild bonus for keeping bins count low early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: default neutral-ish cost, slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically: small post-residuals are efficient.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Strongly reward near-perfect fits (wasting nothing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chain packing); otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 15.0 + 0.3 * (next_item_size as f64);
        } else {
            score += 0.15 * (next_item_size as f64);
        }
    }

    // Time horizon: early in the stream, be conservative and prefer tight fits
    // to preserve flexibility; late in the stream, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual suggests scattered
    // space; prefer consolidating into bins with residual close to mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: only attractive when no existing bin fits well
    // (post_residual == bin_capacity) — make it moderately expensive so it is
    // chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the item is large relative to capacity, a fresh bin is natural.
        score -= 0.2 * (item_size as f64);
        // Late in stream with many open bins, discourage yet another bin.
        score += progress * 20.0;
    }

    // Small tie-breaker favoring fuller bins.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
