}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "clean" leftover classes
    // (multiples of 10 or exact halves are more reusable under typical streams).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: strongly favored
    } else if pr % 10 == 0 && pr >= 10 {
        score -= 8.0; // round leftover is reusable
    } else if pr < 10 {
        score += 15.0; // dead space below min item size
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it is chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.15 * open_bins_count as f64;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 10.0 * fill;
    }

    // Mild dispersion penalty: prefer bins near the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (1.0 - post / 10.0);
    }
    // Mid-range gaps (10..25) are semi-unusable; penalize softly.
    if post >= 10.0 && post < 25.0 {
        score += 8.0 * (1.0 - post / 25.0);
    }
    // Perfect or near-perfect fits get strong reward.
    if post == 0.0 {
        score -= 40.0;
    } else if post <= 5.0 {
        score -= 15.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // If many bins fit the item, mildly discourage spreading across all of them;
    // prefer bins where the item is a larger fraction of the residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Open-bin pressure: with many open bins, discourage new bins and encourage
    // consolidating into existing ones.
    let open_pressure = (open_bins_count as f64 / 20.0).min(1.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + 40.0 * open_pressure;
        // But if no open bin fits well (large dead space would result), allow it.
    } else {
        score -= 5.0 * open_pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;
        } else if (slack as f64) < 10.0 {
            score -= 8.0;
        }
    }
    // If next item would NOT fit here but could fit elsewhere, slight penalty for wasting.
    if next_item_size > post_residual && next_item_size > 0 && post > 0.0 && post < 10.0 {
        score += 10.0;
    }

    // Mean residual coupling: when mean residual is high, prefer bins below mean
    // (tighter bins) to normalize gaps.
    score += 0.3 * (mean_residual - post);

    // Early in the stream, be slightly more willing to open bins for structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain match strongly rewarded.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 40.0; // exact 2-step chain
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally to wasted potential.
        score += 12.0 + 0.25 * post_residual as f64;
    }

    // Dead-space penalty: residuals too small for any item (min size 1, but small usable range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // creates near-unusable sliver
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tighter bin) keeps loose bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (item is large relative to typical residuals)
    // or late in the stream with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bin mildly; reward it when item is big and residuals are small.
        score += 45.0 - 35.0 * item_frac - 15.0 * (1.0 - mean_residual / bin_capacity as f64) - 10.0 * progress;
        if next_item_size > bin_capacity {
            score += 50.0; // next item can't fit anywhere anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits (low post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.35 * wasted;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Prefer using bins with residuals below the mean (consolidate small leftovers).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Dynamic time horizon: early in the stream, keep bins flexible (mild new-bin
    // tolerance); late in the stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, increasingly penalized later.
        score += 6.0 * (1.0 - progress) - 10.0 * progress;
        // Never open a new bin when several bins already fit.
        if fitting_bins_count >= 2 {
            score += 15.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with quadratic sharpening.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (fewer chances to fill it).
    let coupling = (pr_norm * pr_norm) * (1.0 - progress) * (1.0 - progress) * 30.0
                 - pr_norm * progress * progress * 20.0;
    score += coupling;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild crowding penalty scaled by number of alternatives
        score += 2.0 * ((fitting_bins_count - 1) as f64).ln().max(0.0);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (avoid fragmenting many similar bins).
    score += 0.3 * ((pr - mean_residual).abs());

    // New-bin candidate handling: neutral-ish baseline; open new bin only when
    // all open bins would leave large dead space and stream is early.
    if bin_residual == bin_capacity {
        let new_bin_score = 55.0 + 40.0 * progress;
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: dead space in low-value residue classes is worse.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity wasted after placement

    // Classify post_residual by capacity fractions (harmonic classes).
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if post_residual <= bin_capacity / 4 {
        // Small dead space, hard to fill: penalize.
        score += 12.0 * (1.0 - frac) * frac * 4.0;
    } else if post_residual <= bin_capacity / 2 {
        // Medium class: neutral-ish, slight penalty scaled by waste.
        score += 4.0 * frac;
    } else {
        // Large residual still usable: reward proportionally.
        score -= 6.0 * frac;
    }

    // Modulo-arithmetic coupling: residuals that are multiples of small
    // harmonics (e.g., divisible by 10 or 5) pair better with typical items.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            // Next item cannot use this bin's remainder: penalize small remainders.
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // If mean residual is small (bins nearly full), opening a new bin is fine.
        score = 20.0 * (1.0 - pressure) + (post_residual as f64);
        if fitting_bins_count <= 1 {
            // No good alternative exists; new bin is acceptable.
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, prefer consolidating (tight fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - frac);

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.05 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= ~10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residuals in the awkward 10..=25 range are only usable by small
    // items; penalize proportionally to how "awkward" they are.
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.8 * (25.0 - post_residual as f64);
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward leaving space that can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0; // dead space for the next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; favor tighter
    // fills. With few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Deviation from mean residual: prefer bins near the mean (balanced fill),
    // but reward filling bins that are already much emptier than average.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Slight progression term: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Brand-new empty bin candidate: penalize mildly so it is chosen only when
    // open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Aggressive 2-step lookahead: reward if the next item can fit into the post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: next item fits exactly or very well
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: just minimize post_residual
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with less residual than the mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin opening when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // Allow new bin if lookahead chaining is impossible anywhere (soften)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight progression bias: as stream advances, be more conservative about residual waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is nearly consumed.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that can never host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize if we leave a gap the next item cannot use but is not tiny.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin should only win when no good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).min(3.0) };
        // Base penalty for opening a new bin, reduced when stream is late (fewer future chances to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 * pressure - 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 18.0 * (fitting_bins_count as f64).min(4.0);
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low (bins are tight overall).
    score -= 0.3 * mean_residual;

    // Prefer using existing open bins when many are open (avoid bin proliferation).
    if bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild exploration noise-free coupling with stream progression: tighten criteria over time.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr
        - 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + progress)
        + 8.0 * pr_norm * pr_norm * progress;

    // Reward tight fits smoothly (post_residual near zero).
    score -= 20.0 * (1.0 - pr_norm).powi(3);

    // Lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / cap;
        score -= 15.0 * (1.0 - gap_norm.min(1.0)).powi(2) * (1.0 - progress);
    } else {
        // Last item: strongly prefer minimal waste.
        score -= 25.0 * (1.0 - pr_norm).powi(2);
    }

    // Last-chance bin bonus: only fitting bin should be favored smoothly.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (0.5 + progress);

    // Penalize opening new bins more as the stream progresses.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 + progress) - 6.0 * (1.0 - (it / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    // Small post_residual (0..=9) is near-perfect packing -> strong reward.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 25.0 + (5 - pr) as f64 * 4.0;
    } else if pr <= 9 {
        score -= 8.0 + (9 - pr) as f64 * 2.0;
    } else {
        // Larger residuals: penalize unusable dead space, worse for awkward classes.
        let dead = (pr - 10) as f64;
        // Classes that pair badly with common item sizes get extra penalty.
        let awkward = matches!(class, 1 | 2 | 3 | 6 | 7) as f64;
        score += dead * 0.6 + awkward * 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_pr = pr - next_item_size;
            if nxt_pr <= 5 {
                score -= 18.0 - nxt_pr as f64;
            } else {
                score += (nxt_pr as f64) * 0.3;
            }
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Tight-fit reward relative to capacity fractions.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Harmonic integer-division threshold on bin_residual: bins whose residual
    // falls in "half-full or less" bands are valuable to consolidate into.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if bin_residual <= quarter {
        score -= 10.0;
    } else if bin_residual <= half {
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin is much tighter than average, favor it.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Stream progression: early on, be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // New-bin candidate handling: empty bin should lose unless all open bins are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if item is huge and would leave a fresh bin with clean residual, soften.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let open_pressure = (open_bins_count as f64).min(40.0);
    let mean_norm = if mean_residual.is_finite() && capacity > 0.0 {
        (mean_residual / capacity).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;
    let mut dead_for_next = false;

    let mut score = post;

    if post_residual == 0 {
        score -= 24.0 + 0.06 * item + 0.12 * open_pressure;
    } else if next > 0.0 && post < next {
        dead_for_next = true;
        let deadness = ((next - post) / next).clamp(0.0, 1.0);
        score = capacity + 22.0 + 55.0 * deadness * deadness + 0.02 * item + 4.0 * mean_norm;
    } else if next > 0.0 {
        score -= 1.0 + 0.02 * next;
    } else {
        score += 0.015 * post;
    }

    if is_new_bin {
        let mut new_penalty = 15.0 + 0.35 * open_pressure + 7.0 * progress + 9.0 * mean_norm;
        if fitting_bins_count == 0 {
            new_penalty -= 30.0;
        }
        score += new_penalty;
    } else {
        let mut existing_bonus = 2.0 + 0.18 * open_pressure + 2.0 * mean_norm;
        if dead_for_next {
            existing_bonus *= 0.35;
        }
        score -= existing_bonus;

        if fitting_bins_count == 1 {
            let last_chance_bonus = 9.0 + 7.0 * progress;
            if dead_for_next {
                score -= 0.35 * last_chance_bonus;
            } else {
                score -= last_chance_bonus;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 {
        // penalize creating dead space unusable by the next item
        score += 15.0;
    }

    // Reward tight fits relative to bin capacity
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Compare post_residual against mean residual: prefer leaving less than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Late in stream: consolidate into fewer bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of the bin consumed by this item
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits (small post_residual already in base score, amplify non-linearly)
    score -= fill * fill * 30.0;

    // Penalize dead space that is too small to be useful (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
        // Exact chaining bonus: post residual exactly matches next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against global state: penalize bins far from mean residual
    // (prefer placing into bins close to average fill to keep bin states balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Crowding: with many open bins, prefer filling existing ones rather than spreading
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate handling: empty bin gets a dynamic premium.
    // Early in the stream, opening a new bin is cheap; later, it is expensive
    // unless the item is large (would leave big residual elsewhere anyway).
    if bin_residual == bin_capacity {
        let time_premium = 20.0 + 60.0 * progress;
        let size_relief = (item_size as f64 / bin_capacity as f64) * 45.0;
        score += time_premium - size_relief;
        // If no open bin can fit the item, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual). Late: tolerate larger residuals
    // to keep bins consolidated, so residual penalty is damped by progress.
    let damp = 1.0 - 0.6 * progress * progress;
    score *= damp;

    // Smooth convex penalty on large residuals (dead space), modulated by progress.
    score += 0.35 * fit_frac * fit_frac * cap * (1.0 - progress);

    // Reward filling a bin nearly perfectly, smoothly.
    score -= 12.0 * (-pr * pr / (0.5 * cap * cap)).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize opening new bins when many bins are already open (smoothly).
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (fit_frac);

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - pr / (pr + nxt)) * (1.0 + progress);
        } else {
            // Next item won't fit here: mild penalty proportional to leftover.
            score += 3.0 * fit_frac * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (tighter than average), smooth quadratic interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 - progress) - 1.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modular structure of leftover space ---
    // Residuals divisible by 10 are "harmonic" and easy to refill; odd/prime-ish
    // residuals create dead space. Reward harmonic classes, penalize awkward ones.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else if post_residual < 10 {
        // tiny dead space: nearly useless residual
        score += 14.0;
    }

    // Small post_residual generally good (tight fit), but keep a floor bonus
    // for perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // --- Integer-division thresholds: how many "typical" items still fit ---
    let slots = post_residual / 10; // items of min size that could still fit
    score -= slots as f64 * 1.5;

    // --- Lookahead coupling with next_item_size harmonic classes ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by how snugly
            let slack = post_residual - next_item_size;
            score -= 18.0 + (10 - slack.min(10)) as f64 * 0.8;
            // harmonic chain: both residuals harmonic
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize more if this bin is a bad host
            score += 6.0;
            if next_item_size % 10 == 0 && post_residual < next_item_size {
                score += 3.0; // big round next item prefers a roomier bin
            }
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // only this bin can host the item: strongly prefer it over a new bin
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // plenty of alternatives: be pickier about loose fits
        score += (post_residual as f64) * 0.15;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // fresh bin: attractive if current open bins are fragmented or few
        let fragmentation = mean_residual - (post_residual as f64);
        score = 100.0 - 0.4 * open_bins_count as f64 - 0.2 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin guarantees room for lookahead
        }
        if harmonic && post_residual == bin_capacity {
            score -= 2.0;
        }
        // late in the stream, avoid scattering into new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // --- Mild preference for consolidating into low-residual bins ---
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // total dead space (below min item size)
        } else if post_residual <= 20 {
            score += 40.0; // very hard to fill
        } else if post_residual <= 35 {
            score += 12.0; // moderately hard
        } else {
            score -= 8.0; // roomy leftover is good
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward exact fit of the next item into the leftover (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 30.0 + pressure; // penalize new bin, more so later in the stream
    } else {
        score -= 2.0 * pressure.min(10.0); // mild reward for consolidating into open bins
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(25.0) * 0.6;
    } else {
        score += (res - mean_residual).min(25.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snug the chain is.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 200.0 - chain_waste * 1.5;
        } else {
            // Next item will NOT fit: dead space likely; penalize by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize creating tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (tighter bins get filled), penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: only attractive when it enables a good
    // 2-step chain (item + next item both fit) or few fitting bins exist.
    if bin_residual == bin_capacity {
        let chain_ok = next_item_size > 0 && (item_size + next_item_size) <= bin_capacity;
        if chain_ok {
            score -= 120.0;
        } else {
            score += 80.0;
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
        // Many open bins: discourage opening yet another.
        score += open_bins_count as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward dead space: post residual that is small but
    // unlikely to fit future items (below typical item floor ~ 1..100 unknown,
    // so penalize very small nonzero residuals mildly, reward exact fills).
    if post_residual == 0 {
        score -= 8.0;
    } else if post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item cannot use remaining space: mild penalty scaled by waste
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be conservative (prefer filling existing
    // bins); late in stream, allow more new-bin freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // "ragged" — prefer packing it down; if above mean, slight penalty.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.03 * dev;

    // New-bin candidate handling: empty bin gets a base cost that shrinks as
    // the stream progresses or when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let base = 30.0 - 15.0 * progress;
        // If many bins are open already, discourage adding more.
        score += base + (open_bins_count as f64) * 1.5;
        // But if the item is huge relative to capacity, new bin is natural.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Prefer bins whose residual is only slightly above the item (snug fit).
    let slack = (bin_residual - item_size) as f64;
    score += 0.08 * slack * slack / bin_capacity as f64;

    // Small global-load bonus: spreading items when few bins open.
    if open_bins_count > 0 && fitting_bins_count > 2 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = pr_norm * (1.0 + 0.8 * t - 0.6 * t * t);

    let mut score = pr * (1.0 + 0.8 * t - 0.6 * t * t);

    // Penalize small-but-nonzero dead space quadratically (wasted capacity)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.05;
    }

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (cap - pr) * 0.1 * (1.0 + t);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // New-bin candidate: penalize mildly unless residual is very fragmented
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * t;
        // If current bin would leave awkward remainder, opening new bin is attractive
        if pr > 0.0 && pr < 10.0 {
            score -= 20.0;
        }
    }

    // Lookahead: reward bins whose post residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Prefer bins deviating from mean residual (extreme-fit selection)
    score -= 0.3 * (pr - mean_residual).abs();

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small item sizes) are penalized less.
    let pr = post_residual;
    // Dead-space class: leftover too small for the minimum item (<= 10) is worthless.
    if pr <= 10 {
        score += 25.0; // waste class
    } else if pr % 10 == 0 {
        score -= 8.0; // harmonic residue: leftover aligns with 10-multiple items
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Perfect fit: exact fill is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the leftover still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 10.0; // creates a gap the next item cannot use
        }
        // Harmonic pairing: post_residual divisible by next item's class
        if next_item_size <= pr && pr % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // but if the item is huge relative to capacity, opening fresh is fine
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: penalize leftover in awkward mid ranges
    let cls = pr / 20; // coarse harmonic class
    score += 3.0 * (cls as f64 - (pr as f64 / 20.0)); // tiny class-boundary nudge

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear "gap penalty")
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (exact fill is ideal)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if this is the last chance bin, opening new is less attractive
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // If next item is large and current residual is small, opening new bin may be better
        if next_item_size > bin_residual {
            score -= 10.0;
        }
    }

    // Last chance bin: strongly favor using it before it's wasted
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open bins pressure: more open bins -> slightly favor consolidating into existing bins
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if mean residual is high, prefer bins below mean (compact them)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward if next item fits the post_residual exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_gap = post_residual as f64 - next_item_size as f64;
        // Perfect chain (post_residual == next_item_size) is highly desirable
        if lookahead_gap == 0.0 {
            score -= 60.0;
        } else {
            score -= 30.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize dead space
        score += 15.0;
    }

    // Reward bins whose residual is close to mean residual (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream, new bins are cheaper; later, discourage more
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
        // If next item is large, a fresh bin may be valuable
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large leftover dead space relative to capacity (wasted capacity).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead;

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if post residual is a small unusable sliver for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // leftover too small for next item: penalize more if it's tiny
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: later in the stream, avoid opening new bins; consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus escalation with stream progress
        // and with the number of already open bins.
        score = 45.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // If nothing else fits well, new bin becomes attractive; but if this is
        // a last-chance situation for another bin, that bin already got -25.
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0; // fresh bin can host next item too
        }
    } else {
        // Slight preference for bins with residual near the mean (balance load),
        // and mild consolidation pressure as stream progresses.
        score += 0.05 * progress * (bin_residual as f64 - mean_residual).abs();
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: smooth polynomial in normalized post-residual
    let mut score = x * (1.0 - 0.5 * x) * cap;

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = (1.0 - x).powi(3);
    score -= tightness * (0.5 + progress) * 30.0;

    // Penalize dead space that no plausible next item can use,
    // coupled smoothly with progress.
    let usable = (next_item_size as f64 / cap.max(1.0)).min(1.0);
    let waste = (x - usable).max(0.0);
    score += waste * waste * cap * (1.0 + 2.0 * progress);

    // Reward filling bins tightly when they are scarce options.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual gap.
    let gap = (mean_residual - pr) / cap;
    score += gap * gap * 20.0;

    // Smooth new-bin handling: empty bin gets neutral-ish score, slightly
    // worse early (prefer using open bins), better late if fits are poor.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 10.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits are golden
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class of small dead-space residues (unusable slivers)
    let small = post_residual < 10;
    if small {
        score += 40.0;
    }

    // Modular class: residues divisible by 10 pair well with typical item sizes
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // reward leaving room for the next item, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: penalize slightly, more if this bin was the only option
            score += 10.0 + 8.0 * (post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer bins with below-average residual (consolidate fullness)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) - 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * open_bins_count as f64;
    }

    // Late-stream pressure: fill existing bins more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits that leave a still-usable residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.4;

    // Open-bins pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: prefer bins below mean residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default mild penalty, waived when existing fits are poor
    // (item leaves dead space everywhere) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual < 10 || item_size > 70;
        if poor_fit && fitting_bins_count >= 1 {
            score -= 30.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Late-stream consolidation: as stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item can still fit here: reward tighter coupling
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space relative to the next item
            score += 8.0 + diff * 0.15;
        }
    } else {
        // last item: minimize leftover waste strongly
        score += post_residual as f64 * 0.5;
    }

    // Compare against mean residual: bins already below-average residual are precious.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    // Slight preference for tighter fits overall (non-linear waste penalty).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 120.0;

    // Exact fit is extremely attractive.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly good, scaled by how well it packs.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack_after_next as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual: penalize leaving medium gaps.
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.5 {
                score += gap * 0.5;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 60.0 + 40.0 * pressure * (1.0 - progress);
        // If this bin is the only fitting option, soften the new-bin penalty.
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    }

    // Discard bins whose residual becomes a "dead" fragment unlikely to fit
    // typical small items (below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins with residual below the mean (consolidate space).
    score += (mean_residual - bin_residual as f64).max(-100.0).min(100.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits (low post residual), with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.35 * progress * fill * fill);

    // Reward high fill ratio non-linearly (quartic coupling)
    score -= 8.0 * fill.powi(4) * (0.5 + progress);

    // Penalize dead space that can't fit a typical item: smooth threshold via polynomial
    let dead = (pr - next_item_size as f64).max(0.0);
    score += 0.4 * (dead / cap).powi(3) * cap;

    // Lookahead synergy: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 + 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.6 + 0.4 * progress);
    } else {
        // Slight penalty when many bins compete, to avoid fragmenting
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.8;
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidate small residuals)
    score += 0.15 * (pr as f64 - mean_residual) * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a moderate penalty that grows early,
    // shrinking late when fragmentation risk rises
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        // But if item is large relative to capacity, opening fresh is less bad
        score -= 4.0 * (it / cap).powi(2);
    }

    // Open bins count pressure: more open bins -> discourage spreading
    score += 0.03 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small leftovers are good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits (post_residual in low harmonic classes).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize dead space that is too small for the smallest item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more likely to be filled later.
    if post_residual % 10 == 0 { score -= 5.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    // Integer-division threshold: residual in [next_item_size, next_item_size + 15)
    // means the next item fits almost perfectly -> strong reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 25.0;
            } else if slack <= 15 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here; slight penalty.
            score += 3.0;
        }
        // Penalize residuals in the awkward band just below next_item_size.
        if next_item_size > post_residual && post_residual > 0 {
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
        // Coupling: if next item is large, prefer conserving space in this bin.
        if n > 0.5 * cap && post_residual > 40 {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish score, opened only when no
    // open bin offers a decent fit (i.e., all open bins score high).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; slightly cheaper late in the stream
        // when opening bins is less costly long-term.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 10.0 * progress;
        if next_item_size > 0 && (next_item_size as u64) <= bin_capacity as u64 {
            score -= 2.0;
        }
        // If few bins fit the item, opening a new one is less painful.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        return score;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (filling the fullest bins first keeps many partial bins usable).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Mild pressure to consolidate when many bins are open.
    score -= 0.02 * open_bins_count as f64;

    // Capacity-fraction bonus: filling fractions 1/2, 3/4, etc. of the bin.
    let filled = (bin_capacity - post_residual) as f64 / cap;
    if (filled * 4.0).round() as u32 == 4 { score -= 6.0; } // ~full
    else if (filled * 2.0).round() as u32 == 2 { score -= 2.0; } // ~half

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Reward leaving a gap exactly usable by the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize gaps too small for the next item but not dead (wasted potential).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // New-bin candidate: penalize opening a bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Open-bins pressure: fewer open bins is better; reward consolidating.
    score -= 3.0 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack -> strong reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 2.0;
    } else if next_item_size > 0 {
        // Next item does not fit here after placement: penalize proportionally.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 1.5;
    }

    // Reward tight fits relative to capacity (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 50.0;

    // Penalize residuals far from the mean residual (fragmenting the pool).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early, or when item leaves huge dead space in others.
        score += 150.0 - item_frac * 250.0 + progress * 30.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 100.0; // fresh bin chains perfectly with next item
        }
    }

    // Mild preference for filling bins as stream progresses.
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 + step_index as f64 / (total_items.max(1) as f64)) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize (subtract) when post_residual is small relative to item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 35.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 18.0;
            // Extra reward when the next item perfectly consumes remaining space.
            let gap = post_residual as i64 - next_item_size as i64;
            score -= 12.0 * (-gap as f64).exp();
        } else {
            // Next item won't fit here; mild penalty proportional to wasted lookahead.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // When many bins are open, prefer consolidating into existing bins rather
    // than opening new ones (penalize the new-bin candidate implicitly via residual).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // If no open bin fits well, opening new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer reusing bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * t;
    }

    // Global residual balance: prefer bins whose residual deviates from mean
    // in a way that keeps the pool of usable residuals diverse.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev;

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let t = progress;
    // Quadratic-cubic interaction of residual with progress
    score += 12.0 * pr_norm * pr_norm * (0.5 + t) * bin_capacity as f64 * 0.1;
    score -= 8.0 * pr_norm * (1.0 - t) * t * bin_capacity as f64 * 0.1;

    // Penalize dead space more aggressively as the stream progresses
    score += t * t * (post_residual as f64 - mean_residual).abs();

    // Reward tight fits via smooth exponential decay of post_residual
    score -= 6.0 * (-(pr / 20.0)).exp();

    // Last-chance bin bonus (smooth, not piecewise)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: prefer bins whose post residual matches the next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.35 * diff;
        score -= 5.0 * (-(diff / 15.0)).exp();
    }

    // Mild penalty for many open bins to discourage bin proliferation
    score += 0.15 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate handling: make fresh bins attractive for large items
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 (capacity tenths)
    let post = post_residual as u32;
    let residue_class = post % 10;
    let class_bonus = match residue_class {
        0 => -30.0,                       // perfect tenth: highly reusable
        1 | 2 | 8 | 9 => 6.0,             // awkward near-tenth edges
        3 | 4 | 5 | 6 | 7 => -8.0,        // mid-tenth: decent slots
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: does next item fit in a harmonic slot?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post as f64) >= nxt {
            score -= 12.0; // lookahead fits exactly here
        }
        // harmonic pairing: post_residual is a near multiple of next_item_size
        let q = post / next_item_size.max(1);
        let rem = post % next_item_size.max(1);
        if rem == 0 && post > 0 {
            score -= 15.0; // exact harmonic division, slot fully usable by repeats
        } else {
            score += (rem as f64) * 0.4; // waste fraction penalty
        }
        if q >= 2 {
            score -= 6.0; // slot can host multiple next-sized items
        }
    } else {
        // last item: prefer minimal waste
        score += 0.0;
    }

    // Capacity fraction coupling: small residual relative to capacity is dead space
    let frac = post as f64 / cap;
    if frac < 0.10 {
        score += 20.0; // dead space zone
    } else if frac < 0.25 {
        score += 5.0;
    } else if frac > 0.5 {
        score -= 8.0; // roomy bin, keep flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into tighter bins
    if open_bins_count > 4 {
        score += (mean_residual - post as f64).abs() * 0.3;
    }

    // Stream progression: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..100, but small gaps < ~15 are nearly dead)
    // are heavily penalized, with a super-linear ramp.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 25.0;
    }

    // Reward tightness relative to item size (waste ratio).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins; penalize opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it unattractive unless the item fits badly
    // everywhere (handled by last-chance bonus above) or stream is early.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement; if the next item would be blocked, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 15 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chaining of placements).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 / (1.0 + diff);
        // Bonus when next item fits exactly into the residual left behind.
        if next_item_size == post_residual {
            score -= 30.0;
        }
        // Penalize leaving residual that is too small for the next item
        // (dead space the next item cannot use).
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 5.0;
    }

    // Penalize post_residual that is unusably small relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against the mean residual across open bins: prefer bins whose
    // post-residual stays in line with (or below) the average fill state.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress);
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 12.0;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 8.0;
        } else {
            // Penalize placements that leave post-residual too small for the lookahead item
            // (dead space relative to the known future demand).
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 5.0 * progress;
    }

    // Penalize using a very full bin for a small item when many alternatives exist.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.5 && fitting_bins_count > 2 {
        score += (0.5 - fill_ratio) * 15.0;
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        let mut new_bin_score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is mandatory.
            new_bin_score -= 200.0;
        } else {
            // If the best existing fit would leave large dead space, opening a new bin
            // becomes competitive.
            let mean_tight = mean_residual / bin_capacity as f64;
            new_bin_score -= mean_tight * 6.0;
            // Early in the stream, spreading load across bins is cheaper.
            new_bin_score -= (1.0 - progress) * 8.0;
            // If the lookahead item is large, a fresh bin pairs well with the current item.
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                new_bin_score -= 4.0;
            }
        }
        score = new_bin_score;
    }

    // Mild global pressure: with many open bins, prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // base: prefer tight fits (small post residual), with non-linear penalty growth
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // smooth interaction: residual quality weighted by stream progress
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= 8.0 * fits_next * (1.0 - (pr - nxt).abs() / cap);
    } else {
        // end of stream: pure tight packing
        score += 5.0 * norm_pr;
    }

    // penalize bins deviating from mean residual (fragmentation control), smooth coupling
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is it?
    // Residuals divisible by 10 are prime targets for typical item sizes.
    let residual_class = post_residual % 10;
    let class_bonus: f64 = match residual_class {
        0 => 25.0, // perfectly harmonic leftover
        5 => 10.0, // half-harmonic
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: leftover >= 20 is comfortably reusable.
    let big_leftover = post_residual / 20; // 0,1,2,3,4
    score -= big_leftover as f64 * 8.0;

    // Penalize tiny dead space (post_residual in 1..=9 is nearly unusable
    // since items are >= 1, but small leftovers rarely match future items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover harmonically fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact fit for the next item is gold.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 40.0;
            } else if slack <= 5 {
                score -= 22.0;
            } else if slack % 10 == 0 {
                score -= 14.0;
            }
        } else {
            // This bin becomes dead after placement if leftover < next item
            // and no other capacity remains: penalize proportionally.
            let waste = next_item_size - post_residual;
            if waste <= 10 {
                score += 6.0;
            } else {
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class.
    if bin_residual == bin_capacity {
        // Prefer a fresh bin when the alternative leaves awkward leftovers.
        if residual_class != 0 && post_residual < 10 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 1.5;
        // If mean residual is large, reuse existing bins instead.
        if mean_residual > item_size as f64 * 1.5 {
            score += 18.0;
        }
    }

    // Slight preference for tight fits overall (small post_residual already low,
    // amplify with a mild quadratic shaping).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals that are too small to plausibly accept a future item (1..=12)
    // are nearly worthless dead space: penalize heavily beyond their face value.
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 + (12 - post_residual) as f64 * 3.0;
    }
    // "Awkward zone" residuals 13..=19: usable only by tiny items, mildly penalized.
    else if post_residual > 12 && post_residual < 20 {
        score += 8.0;
    }
    // Perfect fill is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward a fit that leaves exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize residuals that block the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // --- Open-bins pressure on the new-bin candidate ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a bin while others can fit the item is wasteful.
        if fitting_bins_count > 0 {
            score += 40.0 + 10.0 * (fitting_bins_count as f64);
        }
        // Extra pressure when many bins are already open.
        score += open_bins_count as f64 * 2.0;
    }

    // --- Last-chance bonus ---
    // If this is the only open bin that fits, using it avoids a new bin entirely.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild preference for keeping residuals near the mean (balanced spread),
    // so one bin is not drained into dead space while others stay fat.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    // Late-stream tightening: as the stream ends, prefer closing bins out.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space the next item can't use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward tight fits (small post_residual) with extra weight.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins that are already more filled than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when existing bins could fit reasonably.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + 2.0 * item_size as f64 / 10.0;
    }

    // Slight bonus for using bins as the stream progresses (consolidation).
    score -= 0.05 * (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 30.0;

    // Penalize dead space that is too small to be useful for future items
    // (typical item sizes up to 100; residual < ~15 is nearly dead).
    if post_residual > 0 {
        let dead = (15u32).saturating_sub(post_residual) as f64;
        score += dead * dead * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item can use the post_residual, reward; if next item
    // would be blocked by leaving this residual, penalize lightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Late in the stream, prefer filling existing bins tightly (reduce bin count).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * fit_ratio;

    // Many open bins: discourage opening new ones / encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that grows with open bins and mean residual.
        score += 20.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        // But if the item is huge and mean residual is small, new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Existing bin: mild bonus scaled by how average it is vs. mean residual.
        score -= 5.0;
        if (bin_residual as f64 - mean_residual).abs() < 10.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping.
    let mut score = pr + 0.5 * (pr * pr) / cap;

    // Smooth coupling of post_residual with stream progress:
    // early in the stream, keep bins flexible (penalize small residuals more);
    // late in the stream, prioritize filling tightly.
    let flexibility = 1.0 - progress;
    score += flexibility * 20.0 * (pr / cap) * (1.0 - pr / cap);

    // Penalize residual below the next item's need when lookahead exists (smooth quadratic gap).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 3.0 + 0.05 * gap * gap;
        } else {
            // reward residual that fits the next item, scaled by closeness
            score -= 2.0 * (1.0 + gap / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + fit_ratio);
    }

    // Mild penalty for spreading bins when many are open relative to mean residual.
    score += 0.01 * open_bins_count as f64 * (mean_residual - pr).abs();

    // New-bin candidate: penalize empty-bin opening unless current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * fit_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny residuals are golden.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty for residuals that few item sizes can ever reuse.
    // Residuals in (10, 20) are awkward: too small for most items (>=10 but tight).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space (min item is 10 in classic regime)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Modulo-class bonus: residuals that are multiples of common size classes
    // (10, 20, 25, 50) tile well with future items.
    let r = post_residual;
    if r % 50 == 0 && r > 0 { score -= 18.0; }
    else if r % 25 == 0 && r > 0 { score -= 10.0; }
    else if r % 20 == 0 && r > 0 { score -= 8.0; }
    else if r % 10 == 0 && r > 0 { score -= 4.0; }

    // Lookahead coupling: reward if next item exactly fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: slight reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize large leftover more.
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Crowding pressure: when many bins are open, prefer tighter packing
    // (lower post_residual already does this); when few bins, opening new is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score -= 0.15 * open_bins_count as f64;
    }
    // Mean residual alignment: prefer bins below mean residual (tighter bins).
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // no open bin well (post_residual here would be capacity - item_size).
    if bin_residual == bin_capacity {
        // Neutral base: real bins with good fits already score below this.
        score += 25.0;
        // Late in the stream, or when this is the only fitting option, opening
        // a new bin is more attractive.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if progress > 0.8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Gap too small for the minimum item (sizes >= 1..=100, but tiny gaps waste space).
        score += (10.0 - pr) * 12.0;
    }
    if pr == 0.0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize creating many open bins unless residual is small.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.3 * progress);
    score += pressure * 0.8;

    // New-bin candidate: only attractive when the current bin's residual is large
    // (item barely fills it) and the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, mitigated if mean residual across open
        // bins is small (open bins are nearly full anyway).
        score = bin_capacity as f64 - 15.0 + mean_residual * 0.5;
        // If lookahead item would fit in the fresh residual, opening is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 20.0;
    }

    // Lookahead synergy: if the next item exactly matches the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack.min(200.0) * 0.5;
            // perfect chain fit
            if post_residual == next_item_size {
                score -= 400.0;
            }
        } else {
            // post residual too small for next item: penalize dead space
            let dead = post_residual as f64;
            score += dead * 1.5;
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Last chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize leaving large residuals relative to typical item range
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // Early in stream: keep bins flexible; late: consolidate tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * (post_residual as f64) * 0.3;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > bin_residual {
            // Bin cannot hold next item anyway; using it for current item is fine.
            score -= 2.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Time horizon: early in stream, tolerate opening bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate handling: discourage opening a new bin unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        // If no existing bin fits well, opening may be justified: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if post_residual as f64 > mean_residual {
            score += 2.0;
        }
    }

    // Slight preference for bins with above-mean residual (balance load).
    if (bin_residual as f64) > mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post residual, scaled by a smooth progress-dependent factor
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear polynomial coupling: small post residuals are penalized
    // more as the stream progresses (dead space becomes costly later).
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Reward tight fits via cubic term on fill ratio
    score -= 25.0 * fit * fit * fit;

    // Interaction between fill and progress: prefer filling bins well early,
    // but strongly prefer perfect fits late.
    score -= 15.0 * fit * fit * progress * (1.0 - progress) * 4.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits into the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to wasted potential
        score += 5.0 * (1.0 - norm_pr);
    }

    // Discourage spreading across too many bins when mean residual is high
    score += 3.0 * (open_bins_count as f64 / 10.0) * (mean_residual / cap).max(0.0);

    // New-bin candidate handling: neutral baseline so it wins only when
    // open bins have poor fits (their scores already carry penalties).
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity divided into 5 classes
    let post_f = post_residual as f64;
    let class = (post_residual * 5 / bin_capacity.max(1)) as f64; // 0..4
    // Dead-space penalty: residuals too small for the smallest item (<=9) are worthless
    if post_residual < 10 {
        score += 40.0;
    } else {
        // reward residuals likely reusable by next item (harmonic match)
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += gap * 0.5;
            if post_residual == next_item_size {
                score -= 25.0; // perfect next-fit
            }
            // modulo arithmetic: next item fits into same harmonic class
            let next_class = (next_item_size * 5 / bin_capacity.max(1)) as f64;
            if (next_class - class).abs() < 0.5 {
                score -= 8.0;
            }
        }
    }

    // Fractional tightness: reward small post_residual fraction of capacity
    score += (post_f / cap) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless residual situation is bad
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // opening fresh bins early in stream is more acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += (post_f - mean_residual).abs() * 0.1;

    // Integer-division threshold: prefer post_residual in {0, 25, 50, 75} harmonic marks
    let marks = [0u32, 25, 50, 75];
    if marks.contains(&post_residual) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward post_residuals that can still fit future items (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead penalty: next item would leave this bin's residual stranded.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New-bin candidate: only attractive when open bins are tight or mean
    // residual is very low; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        if mean_residual < 10.0 || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 30.0 + mean_residual * 0.5;
        }
    }

    // Prefer filling bins whose residual is close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let match_gap = (post_residual as f64 - next).abs();
            score -= 60.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize wasted residual
            score += 0.5 * post_residual as f64;
        }
    }

    // Penalize small dead space that is hard to reuse (below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer tighter bins relative to mean residual
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference to use existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next item size is unusable — penalize that specifically.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bin can host the lookahead item: strong reward
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // dead space created relative to the lookahead item
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.6 * crowding;

    // Prefer bins whose residual is close to mean (avoid fragmenting outliers)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when residuals are large relative
    // to the item (i.e. no open bin is a good host) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 10.0 + 40.0 * avg_fill * (1.0 - progress);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for pairing in fresh bin
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, lightly damped by progress (late stream: tighter packing preferred)
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 8.0 * norm_pr * norm_pr * (1.0 - t) * (1.0 - t) * (1.0 - t);
    score -= 6.0 * norm_pr * (1.0 - norm_pr) * t * t;

    // Penalize very small dead space (unusable slivers), smoothly via cubic
    let sliver = norm_pr * norm_pr * norm_pr;
    score += 10.0 * sliver * (1.0 + t);

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 4.0 * (1.0 - slack * slack) * (0.5 + t);
        } else {
            score += 3.0 * (1.0 - (pr / n)) * (1.0 - t);
        }
    }

    // Last-chance bonus: few fitting bins -> strongly favor using this one
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 + t);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0) * (1.0 - t);
    }

    // Spread from mean residual: prefer bins far from average (keep balance of sizes)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 2.5 * dev * dev * (1.0 - t);

    // Mild penalty for bin proliferation early on
    score += 0.15 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // 0..3 quartile classes
    score += match class {
        0 => -20.0,   // tiny leftover is fine
        1 => 10.0,    // quarter-dead
        2 => 25.0,    // half-dead
        _ => 40.0,    // mostly-empty bin wasted on small item
    };

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // penalize leftovers that are just barely too small (worst dead space)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0 * (11.0 - gap);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer tighter bins overall relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Modulo-class logic on post_residual: common small-item sizes (1..=10 classes)
    let m = post_residual % 10;
    if m >= 1 && m <= 3 {
        score += 8.0; // awkward sliver
    } else if m == 0 && post_residual > 0 {
        score -= 5.0; // round leftover, reusable
    }

    // Stream progression: early on, be picky; late, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin: keep it competitive but not dominant
        score = 45.0 - 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Penalize moderate dead space that cannot fit a typical next item.
    if post_residual > 0 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 8.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow spreading when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // But if mean residual is tiny (all open bins nearly full), new bin is fine.
        if mean_residual < 10.0 {
            score -= 30.0;
        }
        // If next item is large and this item fills the bin, opening is reasonable.
        if post_residual == 0 && next_item_size > 50 {
            score -= 20.0;
        }
    } else {
        // Favor reusing existing bins mildly as open-bin count grows.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Slight preference for bins below mean residual (balancing load).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item's size (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize post_residual that is too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 12.0;
        }

        // Reward post_residual that can still host the next item with room to spare
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Prefer bins with residual below mean (densely packed bins)
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only bin that fits, use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Slight penalty for very large post_residual (wasteful placement)
    if post_residual > 60 {
        score += 0.15 * (post_residual as f64 - 60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to fit a typical small item.
    if post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < item_size.min(20) {
        score += 12.0; // likely dead space
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize more if this was a tight fit anyway.
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global residual balance: prefer bins below mean residual (fill emptier bins less
    // when they're rare, fill fuller bins when mean is low).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    // New-bin candidate: make it attractive only when item is large or fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 15.0 - 20.0 * large_item - 25.0 * poor_fits;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth interaction: as stream progresses, prefer tighter fits more strongly.
    score += pr * progress * (pr_norm * 2.0);

    // Reward filling bin nearly exactly (small post_residual) via smooth cubic bonus.
    score -= (1.0 - pr_norm).powi(3) * item_size as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = if pr > 0.0 { (nxt / pr).min(1.0) } else { 0.0 };
        score -= fit_ratio * fit_ratio * 12.0;
        // Penalize leaving residual that is awkwardly large but unusable for next item.
        let waste = (pr - nxt).max(0.0);
        score += (waste / cap) * (waste / cap) * 30.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open and residual is large (dead space).
    score += (open_bins_count as f64).ln() * pr_norm * 2.0;

    // New-bin candidate: make it moderately attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) - (mean_residual / cap) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via integer division
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class of leftover space

    // Penalize unusable dead space: residuals below smallest plausible item
    if pr > 0 && pr < 10 {
        score += 60.0;
    }
    // Perfect fit / tiny leftover is excellent
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= pr {
            // fraction of next item's size consumed by this residual
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= 20.0 * fit_frac;
            // modulo harmony: pr % next small => good follow-up packing
            let m = pr % next_item_size;
            score -= 5.0 * (1.0 - (m as f64 / next_item_size as f64));
        } else {
            // next item won't fit here: leftover is likely dead
            score += 12.0;
        }
    }

    // Class-based residual quality: prefer residuals in "useful" harmonic bands
    match class {
        0 => score -= 10.0,              // empty-ish leftover, near-perfect
        1..=3 => score -= 4.0,           // small useful gap
        4..=6 => { /* neutral */ }
        _ => score += 3.0,               // large leftover: bin underfilled
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let tight = (bin_residual - item_size) as f64 / cap;
        // opening new bin penalized unless it yields a very tight fill
        score += 45.0 - 40.0 * (1.0 - tight);
