        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins far below mean residual (reduces spread of dead space)
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Slight preference for denser packing as stream progresses
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
