        score = 25.0 + 40.0 * crowded * pressure - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 8.0; // nothing open can hold the next item anyway
        }
    }

    // Mild global balance: prefer bins near the mean residual (spread waste evenly).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let fit = fitting_bins_count as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Base: prefer small post_residual, but weight it by progress.
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Smooth interaction: large post_residuals are penalized more as stream advances
    // (dead space becomes costlier later in the stream).
    let pr_norm = pr / cap;
    score += 18.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.6 + 0.4 * progress);

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins fit (encourage concentrating items).
    score += 2.0 * fit.ln().max(0.0);

    // Lookahead: if next item could fill the post_residual, reward leaving this residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 4.0 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }

    // Mean residual coupling: penalize bins deviating from mean residual smoothly.
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: empty bin gets a smooth progress-dependent penalty
    // so early stream favors filling open bins, late stream allows opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common size
    // classes are more reusable, so reward them (subtract from score).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional fill of the bin after placement: tighter packs favored.
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill;

    // Harmonic class bonus: post_residual divisible by 10, 20, 25, 50
    // aligns with typical item-size lattices -> easier future fits.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 2.0; }
    if post_residual % 50 == 0 { score -= 3.0; }

    // Penalize tiny dead space that nothing (min size 1, but practically
    // small items are rare) can use: residual in awkward band 1..=5.
    if post_residual >= 1 && post_residual <= 5 {
        score += 8.0;
    }

    // Next-item lookahead: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit in post_residual but this
    // bin would otherwise be a good choice, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
        // Harmonic pairing: next item matches a divisor class of post_residual
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual;
    // make it attractive only when current fit is poor or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer reusing bins mid-stream; new bins get a mild base penalty
        // that shrinks when mean residual across open bins is small.
        let scarcity = (mean_residual / cap).max(0.0);
        score += 4.0 - 6.0 * (1.0 - scarcity) - 2.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 2.0; // big items pair well in fresh bins
        }
    }

    // Slight preference to spread load when many bins open (keeps
    // residuals balanced): compare post_residual to mean residual.
    if post > mean_residual {
        score += 0.5;
    } else {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are "dead" unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 20.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to capacity.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.3 * pressure;

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // dead space relative to lookahead
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (large residual elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let desperation = (mean_residual / 100.0).clamp(0.0, 1.0);
        score += 40.0 - 35.0 * desperation - 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count <= 1 {
            score -= 25.0; // allow opening when alternatives are poor
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            // next item still fits; reward tighter chaining
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.25 * miss;
        }
    }

    // Penalize dead space (small unusable residuals), especially tiny ones.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins with below-average residual (compact fills) mildly.
    score += 0.15 * (mean_residual - post_residual as f64).abs().signum()
        * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive late in the stream or when many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 25.0 * progress + 0.5 * open_bins_count as f64;
        // If lookahead chains perfectly into a fresh bin, allow it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: later in stream, prefer filling existing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;

    // Global residual coupling: if mean residual is high, prefer bins below mean (balance)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Penalize many open bins slightly to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize unless item is huge and no bin fits well
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * big_item;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth non-linear coupling with progress
    let r = post / cap;
    let mut score = post;

    // Quadratic/cubic shaping: reward very tight fits, penalize mid-range waste
    score -= 30.0 * (1.0 - r) * (1.0 - r);
    score += 12.0 * r * r * (1.0 - r);

    // Progress coupling: later in the stream, tighten tolerance on waste
    score += 25.0 * progress * r * r;

    // Dead-space penalty: residuals too small for plausible future items
    let dead = ((cap * 0.2 - post) / cap).max(0.0);
    score += 40.0 * dead * dead;

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 18.0 * fits_next * (1.0 - 0.5 * progress);
        score += 8.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild pressure toward consolidating into few bins
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - r);

    // Mean-residual coupling: prefer bins deviating below mean (tighter bins)
    score += 5.0 * (mean_residual - post) / cap;

    // New-bin candidate handling: neutral-ish score, slightly penalized so it's
    // chosen only when open bins have poor fits
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit (minimize post residual) is the core signal.
    // Harmonic classes: classify post_residual into residue classes mod 10
    // to detect "usable" vs "dead" leftover space.
    let post = post_residual;
    let class = post % 10;

    // Dead-space penalty: residuals that few item sizes can fill are costly.
    // Items are 1..100; small residuals (< ~10) are hard to reuse unless
    // exactly fillable. Penalize awkward classes.
    if post > 0 {
        let dead_penalty = match class {
            0 => -6.0,   // exact decade residual: highly reusable
            1 | 9 => 5.0, // awkward off-by-one classes
            2 | 8 => 3.0,
            5 => -2.0,   // half-class: many items fit
            _ => 1.0,
        };
        score += dead_penalty;
    }

    // Perfect fit reward: strong subtraction for exact fills.
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward heavily; if next item is slightly larger than post_residual
    // (near-miss), penalize since this bin will be stranded.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 18.0;
        } else if next_item_size < post {
            let slack = (post - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 8.0; // near-perfect chain fit
            }
        } else {
            let miss = (next_item_size - post) as f64;
            if miss <= 5.0 {
                score += 6.0; // next item almost fits: bin becomes stranded
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when all fitting
    // open bins would leave large dead space, or stream is early with
    // many items remaining to fill a fresh bin.
    if bin_residual == bin_capacity {
        // Neutral base for empty bin: post_residual == capacity.
        // Compete with open bins: penalize slightly so only genuinely
        // poor fits in open bins trigger a new bin.
        score += 4.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 6.0; // early stream: fresh bins have long fill horizons
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0; // next item can stack into the fresh bin too
        }
    }

    // Mild pressure toward bins with residual close to item_size even
    // when not exact: quadratic tightening of the fit gap.
    let gap = (bin_residual - item_size) as f64;
    score += gap * gap / (bin_capacity as f64 * 4.0);

    // Cap open-bin sprawl: with many open bins, prefer consolidation
    // into existing bins over opening new ones.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1..100,
    // but treat gaps below a "useful threshold" as wasted) get heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += 60.0 * (1.0 - gap / 20.0); // small unusable gaps are worst
    }
    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is close to the item (tight packing ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when unnecessary.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // the lookahead item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 10.0 + 30.0 * progress; // default cost of a new bin
        if fitting_bins_count == 0 {
            nb -= 100.0; // forced: no alternative
        }
        if next_item_size > 0 && next_item_size >= bin_residual - item_size && post_residual > 0 {
            nb -= 15.0; // fresh bin may serve the lookahead item
        }
        if post_residual == 0 {
            nb += 20.0; // don't open a bin for a perfect-fit-only scenario
        }
        score += nb;
    }

    // Mild lookahead coupling: prefer leaving gaps that fit the next item.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() < 5 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with mild superlinearity
    // to punish leaving awkward dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64) * 0.5;

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as i64) >= (next_item_size as i64) {
            let slack = post_residual as f64 - next;
            // Exact or near-exact 2-step match is highly desirable.
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
            // Penalize large leftover slack after the hypothetical next placement.
            score += 0.15 * slack;
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much dead space remains relative to next item.
            score += 0.35 * (next - post_residual as f64);
        }
    } else {
        // Last item: just minimize post_residual tightly.
        score += 0.2 * post_residual as f64;
    }

    // Compare against mean residual: bins tighter than average are precious,
    // reward using them; bins looser than average absorb overflow cheaply.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid);
    } else {
        score += 0.25 * (resid - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish baseline; add pressure so it's chosen only when open bins
        // would waste a lot of space (their scores already carry dead-space terms).
        score += 40.0 + 0.1 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If the next item is huge, a fresh bin has good lookahead value.
        if next_item_size > 0 && next_item_size >= post_residual + item_size.min(1) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 8.0; // residual smaller than typical item -> dead space risk
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit quality: leftover after hypothetically placing next item
            let chain_left = post_residual - next_item_size;
            score += 10.0 * (chain_left as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into fuller bins (higher mean residual spread).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * fit_ratio;
    }

    // Prefer bins below mean residual (fill the emptier side) early, tighten later.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev * (0.5 + progress);

    // New-bin candidate handling: empty bin only wins when current fit is bad.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin, reduced if item is huge (poor fit elsewhere likely)
        score = 55.0 - 0.4 * item_size as f64;
        if next_item_size > 0 && item_size >= 60 {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) coupling
    // so tiny dead space is rewarded super-linearly.
    let mut score = post + 0.6 * (post / cap).powi(2) * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight packing dominates.
    let coupling = (post / cap).powi(3) * (1.0 - progress) * 30.0;
    score += coupling;

    // Reward near-full usage smoothly (small post_residual gets a discount).
    score -= 25.0 * (-post / 12.0).exp();

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post - nxt;
        if slack >= 0.0 {
            score -= 12.0 * (-slack / 15.0).exp() * (0.5 + 0.5 * progress);
        } else {
            // Post-residual too small for next item: penalize dead space smoothly.
            score += 6.0 * (post / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; shrinks slightly with progress.
        let mut open_cost = 45.0 - 10.0 * progress;
        // If open bins exist that fit, opening is worse when their residuals
        // are large (mean_residual high).
        if fitting_bins_count > 0 {
            open_cost += 0.5 * mean_residual;
        }
        // If the item is small relative to capacity, opening a bin wastes space.
        open_cost += 0.4 * (cap - item);
        score += open_cost;
    } else {
        // Slight preference for bins with less residual (best-fit flavor),
        // scaled smoothly by open bin count pressure.
        score += 0.05 * (bin_residual as f64) * (1.0 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into deciles of capacity.
    let class = post_residual / 10; // 0..=10
    // Dead space penalty: residuals in awkward classes (1..=9 small slivers) are bad.
    match class {
        0 => score -= 30.0,                       // perfect fit
        1 => score += 25.0,                       // tiny unusable sliver (1..9)
        2 => score += 8.0,                        // 10..19: fits only smallest items
        3 | 4 => score += 2.0,                    // mid slivers
        5 => score -= 6.0,                        // ~half bin: very reusable
        6 | 7 | 8 => score -= 3.0,                // large residuals: reusable
        _ => score -= 10.0,                       // near-empty bin
    }

    // Harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward smoothness: how tightly the next item fills the leftover
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to overshoot class
            let over = next_item_size - post_residual;
            score += 4.0 + (over / 10) as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should win only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain and bins are congested.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = mean_residual / bin_capacity as f64;
        score = 55.0 - 20.0 * congestion - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin gives lookahead freedom
        }
    }

    // Mild tie-break: prefer bins whose residual is close to the mean (balanced packing),
    // with a harmonic (quantized) nudge on the difference.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += (diff / 10.0).floor() * 0.5;

    // Slight preference to fill more-open bins when bin count grows (limit bin proliferation).
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (sizes >= 1
    // but realistically small gaps < 15 are near-useless) get a heavy penalty.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        // Gap that could still fit a small item: mild reward scaled by usability.
        score -= 5.0;
    }

    // Tightness reward: fraction of the bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Open-bin pressure: discourage spreading across many bins when few are open,
    // encourage using existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere else (dead-space logic above may override this).
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the next item is large and this bin would be nearly filled,
        // opening fresh is attractive.
        if next_item_size as f64 > post_residual as f64 {
            score -= 15.0;
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits with small slack: still very good.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - 8.0 * slack;
    }
    // Next item does NOT fit: penalize proportional to how much usable space
    // is left (dead space risk), scaled by stream progress.
    else if next_item_size > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (post_residual as f64 / bin_capacity as f64) * (150.0 + 250.0 * progress);
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Reward bins tighter than the mean residual (well-packed bins).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize creating tiny unusable slivers (dead space < 10).
    if post_residual < 10 {
        score -= 50.0; // sliver is effectively full: actually good, reward
    }

    // Mild penalty for spreading across too many open bins when a tight fit exists.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize proportionally wasted space more aggressively.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post-residual exactly or nearly matches next item.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Post-residual becomes dead space relative to lookahead.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // bins are fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins.
        score += 20.0;
        // More attractive when many open bins exist but fits are scarce.
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        // Attractive when mean residual is small (open bins nearly full).
        score -= (mean_residual / 10.0).min(15.0);
        // Early stream: consolidating is cheap, discourage new bins slightly less
        // as stream progresses and fragmentation grows.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // Large items deserve fresh bins if they'd leave awkward residue elsewhere.
        if item_size >= bin_capacity / 2 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    // (encourage filling fuller bins first).
    score += 0.05 * mean_residual * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with less residual overall (fill fuller bins).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with a convex quadratic penalty
    let mut score = pr / cap;
    score += 0.35 * (pr / cap) * (pr / cap);

    // Smooth stream-progress coupling: as stream advances, tighten residual tolerance
    let tightness = 0.5 + 0.5 * progress;
    score += tightness * 0.4 * (pr / cap);

    // Interaction: post_residual * progress polynomial coupling
    score += 0.15 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space that no small item can use (post_residual < typical min size)
    let dead = ((20.0 - pr).max(0.0)) / 20.0;
    score += 0.5 * dead * dead;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - pr / cap;
    score -= 0.6 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 0.4 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.2 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.02 * open_bins_count as f64 / (1.0 + mean_residual / cap);

    // New-bin candidate handling: empty bin gets neutral-ish score unless current fits are poor
    if bin_residual == bin_capacity {
        score = 1.2 - 0.5 * fit_quality + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
    } else {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Dead-space penalty for tiny unusable residuals, modulo-classified.
    if pr > 0 && pr < 10 {
        score += 30.0 - (pr as f64); // small leftovers are nearly worthless
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic bonus scaled by how snugly the next item fits.
        let snug = (next_item_size as f64) / (post_residual as f64);
        score -= 15.0 + 10.0 * snug;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here; penalize proportional to how much it misses.
        let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 0.15 * miss;
    }

    // Capacity fraction thresholds on the current residual.
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac > 0.9 { score -= 8.0; }       // very full bin: good to keep filling
    else if frac > 0.5 { score -= 2.0; }  // moderately full: mild preference

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // More competing bins: slight tie-breaking toward tightest fit.
        score += 0.5 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate: allow opening a fresh bin only when open bins are
    // congested (high mean fill) or this is a large item.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        if congestion < 0.35 && open_bins_count > 0 {
            score -= 20.0; // open bins are roomy; prefer them, discourage new bin
        } else {
            score -= 5.0; // fresh bin is a reasonable fallback
        }
        if item_size >= 50 { score -= 5.0; }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: when average residual is small, tight fits matter more.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Favor bins whose residual after placement can still host typical items
    // (>= 10), penalize creating gaps just below usable thresholds.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; opening a
    // new bin is penalized via its residual == capacity baseline.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good existing fit,
        // but below heavily dead-spaced bins.
        score += 30.0 + open_pressure * 0.5;
    } else {
        score -= open_pressure * 0.5;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 300.0;
        } else if slack < 10 {
            score += 40.0; // would strand dead space for next item
        }
    }

    // Late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    // Mean-residual coupling: prefer bins close to the mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post residual is gold).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose leftover
    // after this item exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize slack beyond what the next item consumes,
            // but less harshly when slack is small.
            score += slack * 0.8;
            // Bonus if the chain keeps the residual in a "usable" band.
            if slack <= 20.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit here afterwards; dead space penalty
            // proportional to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins that are already "tight"
    // (residual below mean) so we consolidate fragmentation.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize the brand-new bin candidate unless the item is large
    // relative to capacity or no real alternative exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 150.0 - 120.0 * fill_ratio;
    }

    // Late in the stream, prefer closing bins out (tighter packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0 + 2.0 * (5 - post_residual) as f64;
    } else {
        // Dead-space penalty grows super-linearly for large leftovers.
        score += 0.02 * (post_residual as f64).powi(2) * 0.1;
    }

    // Perfect-fit style reward when residual becomes unusable for typical items.
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-slack / 20.0).exp();
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline penalty so we prefer reusing bins...
    if bin_residual == bin_capacity {
        let mut new_bin_score = 40.0;

        // ...but open a new bin when the fit in existing bins would be poor:
        // if post_residual (in a fresh bin) is large, the item is small relative
        // to capacity and pairing it elsewhere wastes little.
        if post_residual as f64 > mean_residual + 15.0 {
            new_bin_score -= 20.0;
        }
        // When many bins are open and fragmented, fresh space is valuable.
        new_bin_score -= 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 30.0 * progress;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 70 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins whose residual deviates favorably from the mean (consolidation).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let coupling = progress * prn * (1.0 - prn);
    score -= 12.0 * coupling;

    // Penalize dead space more as stream progresses (quadratic in progress)
    score += 8.0 * progress * prn * prn;

    // Reward tight fits: post_residual close to zero
    let tightness = 1.0 - prn;
    score -= 6.0 * tightness * tightness;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 5.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // penalize leaving residual that cannot host the next item
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild penalty proportional to open bins count to discourage spreading
    score += 0.05 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins with residual near mean (polynomial)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residues near "dead space"
    // thresholds are penalized, residues that leave room for common item
    // classes (multiples of 10) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space bands: residual below smallest item class is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    } else if post_residual < 20 {
        score += 60.0;
    }

    // Reward if next item fits exactly into post residual (chained fit)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + 0.5 * (next_item_size as f64);
        } else {
            // next item won't fit here: penalize more if residue is small
            score += 0.4 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Modulo-10 harmonic bonus: residues divisible by 10 align with item grid
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Prefer filling bins tightly relative to capacity fraction
    let fill_frac = 1.0 - post / cap;
    score -= 50.0 * fill_frac * fill_frac;

    // Mild preference for keeping few open bins when mean residual is high
    if (mean_residual as u32) >= item_size * 2 && open_bins_count > 1 {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 150.0 + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // Reward tight fits: small usable residual relative to capacity.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving a gap that the next item almost fits but not quite (future dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.8 * shortfall;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidating into few bins when fit is decent.
    if fitting_bins_count > 1 {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: acceptable early, discouraged late in the stream or when
    // other bins fit and mean residual is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0 * mean_residual / bin_capacity as f64;
        }
    } else {
        // Prefer bins with residual closest to the item (best-fit flavor on top).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.1 * (tightness - post_residual as f64).abs();
    }

    // Mild penalty for creating residual far from typical item sizes.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * drift;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot.min(40.0);
        }
    } else {
        // Last item: minimize post_residual strongly
        score += 20.0 * fit_ratio;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" -> favor using them
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving dead space below the minimum item size (unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Late in the stream, consolidate into open bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 30.0 + 40.0 * progress;
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= bin_residual {
            score += 10.0; // an open bin could chain the next item too
        }
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scaled by fraction of bin consumed by the item.
    let fill_frac = item_size as f64 / cap;
    score -= 30.0 * fill_frac * fill_frac;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 12.0 * next_fit;
        } else {
            // next item won't fit here; penalize leaving awkward medium gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 8.0; // tiny dead space is fine actually
            } else if gap >= 10.0 && gap < 25.0 {
                score += 15.0; // awkward medium gap
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residual below mean (tighter bins) to consolidate.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Penalize creating many near-empty bins early; encourage packing into existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it competitive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap + 25.0 - 0.02 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // pairing potential in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) - norm_pr * (1.0 - progress) * 0.5;
    score += poly * cap;

    // Penalize dead space more strongly late in the stream (quadratic in progress).
    score += (pr * pr / cap) * progress;

    // Reward tight fits (small post residual) with smooth decay.
    score -= 10.0 * (-(norm_pr * 4.0)).exp() * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - (next_item_size as f64 / pr.max(1.0) - 1.0).abs().min(1.0));
    }

    // Mild penalty for spreading across too many open bins early.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Deviation from mean residual: prefer bins whose residual is near the mean.
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fraction bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Dead space penalty: residuals that are too small to fit the smallest
    // plausible item are pure waste. Harmonic tiers at 1/10, 1/5, 1/3.
    if frac < 0.10 {
        score += 60.0; // nearly dead bin
    } else if frac < 0.20 {
        score += 25.0;
    } else if frac < (1.0 / 3.0) {
        score += 8.0;
    } else {
        score -= 5.0; // roomy leftover is good
    }

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize if it almost fits (teasing near-miss).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_f {
            score -= 18.0;
            // Harmonic bonus: exact modulo closure (next divides residual nicely)
            if (post_residual % next_item_size.max(1)) <= 5 {
                score -= 10.0;
            }
        } else if next - post_f <= 10.0 {
            score += 12.0; // near-miss: wasted lookahead opportunity
        }
    }

    // Integer-division threshold on post_residual: multiples of capacity/4
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual % quarter.max(1) == 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // relative to mean residual across open bins.
    if bin_residual == bin_capacity {
        score += 35.0;
        if (item_size as f64) > mean_residual {
            score -= 45.0; // item too big for typical open bin -> new bin is fine
        }
        // Late in stream, prefer consolidation less strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
    }

    // Mild pressure to keep number of open bins small when residuals are healthy.
    if mean_residual > 0.5 * cap_f && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= item_size {
        score += 6.0;
    }

    // Progress-based pressure: later in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (fill the emptier-fitting bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: make it slightly costly so we prefer existing bins unless dead space risk is high.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly into the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Sliding match quality: closer fit -> bigger reward.
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize large dead space, scaled by dead fraction.
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.4;
        }
    }

    // Penalize residuals that are hard to fill later (small unusable slivers),
    // but only when this bin is not a perfect chain match.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // no open bin offers a good (tight) fit.
    if bin_residual == bin_capacity {
        let tightness = if post_residual as f64 <= mean_residual { 1.0 } else { 0.0 };
        // Base cost of opening a new bin, discounted when current open bins are loose.
        score += 20.0 - 10.0 * (mean_residual / bin_capacity as f64) - 15.0 * tightness;
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for tighter-than-average bins to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base term.
    // Bonus (subtraction) when this bin is the ONLY one that fits the item:
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize bins whose post_residual becomes a tiny unusable gap
    // (dead space < 10 can never hold any item).
    if post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting
    // post_residual, strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits after this placement: mild bonus, scaled by
        // how well the residual is used.
        let use_ratio = next_item_size as f64 / post_residual as f64;
        score -= 5.0 * use_ratio;
    } else if next_item_size > 0 {
        // Next item would NOT fit here: mild penalty proportional to overflow.
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins generally; add a dynamic pressure term that
        // shrinks as the stream matures (later items tolerate new bins more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 25.0 * (1.0 - 0.4 * progress);

        // If few bins fit the item, opening a fresh bin becomes more attractive.
        if fitting_bins_count <= 1 {
            open_penalty -= 18.0;
        }
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable.
        if mean_residual < item_size as f64 {
            open_penalty -= 10.0;
        }
        score += open_penalty.max(0.0);
    } else {
        // Open-bin mild preference toward fuller bins (low residual).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global-state coupling: many open bins with high mean residual -> encourage
    // consolidation into existing bins (penalize new bins implicitly via
    // fitting bonus above; here we slightly reward filling fragmented bins).
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual >= item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction with stream progress: later in stream, tighter packing valued more
    score -= 25.0 * norm_pr * progress * (1.0 - progress * 0.5);

    // Penalize dead space that cannot fit the lookahead item (smooth via lookahead ratio)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) as f64;
        score += 0.6 * gap * (0.5 + progress);
        // Reward if post residual fits next item smoothly
        let fit_next = (pr / nxt).min(1.0);
        score -= 12.0 * fit_next * fit_next * (1.0 - progress * 0.3);
    }

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let scarcity = 1.0 / fitting_bins_count as f64;
    score -= 18.0 * scarcity * (1.0 - progress * 0.4);

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev - 6.0 * dev;

    // Mild penalty for opening new bins when many open bins exist
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (8.0 + 4.0 * progress * open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into modulo classes.
    let pr = post_residual as f64;
    let class = (post_residual % 25) as f64;

    // Reward small residuals, but modulate by harmonic class:
    // leftovers near multiples of 25 are "harmonic sweet spots" (usable by mid items).
    score -= 30.0 * (1.0 - pr / cap) * (class / 25.0);

    // Penalize dead space that no plausible item (1..=100) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item can't fit here; penalize proportional waste
            score += 10.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // current residuals are poor (mean residual small relative to capacity)
    // or many bins already fit the item (spread load).
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
        // prefer existing bins when mean residual is healthy
        score = cap - 40.0 * mean_frac - 20.0 * pressure;
        // early in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 70.0; // never open new bin when only one bin fits
        }
    }

    // Tie-break: prefer fuller bins slightly (best-fit flavor with harmonic tilt).
    score -= 5.0 * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for the smallest plausible item) are heavily penalized.
    let dead_floor: f64 = 8.0;
    let dead_ceiling: f64 = 20.0;
    if (post_residual as f64) < dead_ceiling {
        // Dead space zone: smaller residual (wasted) => bigger penalty.
        let depth = (dead_ceiling - post_residual as f64).max(0.0);
        score += 25.0 * depth;
        if (post_residual as f64) < dead_floor {
            score += 40.0;
        }
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 4 {
        score -= 12.0;
    }

    // Last usable bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> allow opening new ones.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or item is large
        // and would leave a good residual; penalized when bins are plentiful.
        score -= 20.0 - 2.5 * pressure;
        score += (item_size as f64) * 0.15;
    } else {
        score += pressure * 0.8;
    }

    // Lookahead: favor bins whose post_residual still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creates a gap that blocks the next item
        }
    }

    // Prefer bins tighter than the current mean residual (fill the fullest).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (small post_residual).
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover dead space
            let dead = (post_residual as f64).powi(2);
            score += 0.05 * dead;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.1 * post_residual as f64;
    }

    // Penalize creating unusable fragments relative to smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // tiny dead fragment is worse than a clean empty-ish residual
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad fits.
    if bin_residual == bin_capacity {
        score += 120.0; // default cost of opening a new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin can chain the next item too
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    // Context: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Prefer bins below mean residual (consolidate space) slightly.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that cannot fit a plausible future item.
    // Assume future items average ~ (bin_capacity / 4); residuals below that are nearly dead.
    let dead_threshold = bin_capacity as f64 / 4.0;
    if (post_residual as f64) < dead_threshold {
        let dead = dead_threshold - post_residual as f64;
        score += 2.5 * dead;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; penalize proportionally to waste.
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress);
        // Extra penalty if decent fitting bins already exist.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= item_size {
            score -= 5.0;
        }
    } else {
        // Reward using already-open bins, slightly more when many bins are open.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Coupling with global state: prefer bins whose residual is near the mean
    // (keeps residuals balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-horizon term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // vanishes at x=0 and x=1
    score -= 30.0 * poly * (0.5 + progress);

    // Reward tight fits, more strongly late in the stream
    score -= 10.0 * (1.0 - x) * (1.0 - x) * progress;

    // Penalize dead space relative to mean residual
    score += 0.5 * (pr as f64 - mean_residual) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = (pr - nx) as f64 / cap;
            score -= 8.0 * gap * (1.0 - gap) * (1.0 - progress);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity split into 4 bands (quarter classes).
    let q = (item_size * 4) / bin_capacity; // 0..3
    // Harmonic class of post_residual: which quarter of capacity remains.
    let pq = (post_residual * 4) / bin_capacity;

    // Reward tight fits: post_residual in the lowest harmonic class.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if pq == 0 {
        score -= 60.0;   // leaves small dead space -> good
    } else if pq == 1 {
        score -= 20.0;   // moderate
    }

    // Penalize dead space that is too small for the smallest item (1) but awkward:
    // dead space in (0, next_item_size) can't host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving exactly enough room for the lookahead item.
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 80.0; // lookahead fits perfectly after this
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight.
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins with decent fits.
        score += 40.0;
        // Open a new bin when existing bins are crowded (small mean residual)
        // and current item is large (big harmonic class).
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (q as f64) / 3.0;
        score -= 120.0 * crowding * (0.5 + 0.5 * large_item) * (0.5 + progress);
        // Never open a new bin for a tiny item when plenty of room exists.
        if q == 0 && mean_residual > item_size as f64 * 2.0 {
            score += 200.0;
        }
    }

    // Modulo coupling: prefer post_residuals that are "harmonious" multiples,
    // i.e. divisible into likely future item sizes (small divisors).
    let mut harmony = 0.0;
    for d in [2u32, 4, 5, 10] {
        if post_residual % d == 0 && post_residual > 0 {
            harmony += 3.0;
        }
    }
    score -= harmony;

    // Mild tie-break: spread load across bins when many are open.
    if bin_residual != bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..=100) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps below ~15 are rarely usable by typical items; soft penalty.
    if post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> penalize spreading further, favor filling.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or item is large relative to residual of others.
    if bin_residual == bin_capacity {
        // Neutral-ish base; slight penalty so tight fits in open bins win.
        score = 45.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host the pair
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap == 0.0 {
                score -= 800.0; // next item exactly fills this bin afterwards
            } else if gap <= 10.0 {
                score -= 250.0 - gap * 12.0;
            } else {
                score -= 80.0 - gap * 0.8;
            }
        } else {
            // next item cannot fit here: penalize proportionally to wasted lookahead
            let overflow = nxt - post_residual as f64;
            score += overflow * 1.5;
        }
    } else {
        // last item: only tight fits matter
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins tighter than average are more precious.
    let tightness = mean_residual - post_residual as f64;
    if tightness > 0.0 {
        score -= tightness * 1.2;
    } else {
        score += (-tightness) * 0.6;
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when reasonable fits exist among open bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 40.0 + waste * 0.3;
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // Early stream: slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
    }

    // Mild preference for consolidating into bins with small residuals overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits strongly (nonlinear).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize large dead space after placement, especially if unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fit bonus
    } else if post_residual > 40 {
        score += 6.0; // large leftover: keep flexible? mild penalty
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize wasting the residual
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * fill_ratio;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // but reward it if all fits are loose and mean residual is high.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else {
            score += 30.0;
            // if mean residual is large, a fresh bin is attractive
            score -= (mean_residual - 20.0).max(0.0) * 0.5;
            // large items fit better in a fresh bin
            if item_size > 60 {
                score -= 15.0;
            }
        }
    }

    // Time horizon: early in stream, favor flexibility (balanced residuals);
    // late in stream, favor packing tightly to close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.3;
    score -= progress * fill_ratio * 10.0;

    // Spread pressure: prefer bins whose residual is far from mean
    // (balances residuals across bins, keeping many usable bins).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Many open bins: prefer filling existing ones to consolidate.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly.
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, leave flexible space; later, squeeze harder.
    let phase = progress * std::f64::consts::PI;
    let w_early = 0.5 * (1.0 + phase.cos());   // 1 -> 0
    let w_late = 1.0 - w_early;                // 0 -> 1
    score += 12.0 * w_early * norm_pr * norm_pr;
    score -= 8.0 * w_late * norm_pr * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual (smooth quadratic).
    let dead = norm_pr - (mean_residual / cap);
    score += 4.0 * dead * dead * cap * 0.1;

    // Reward last-chance bins smoothly.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: penalize if next item cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0) / cap;
        let unusable = if nxt > pr { 1.0 } else { 0.0 };
        score += 10.0 * waste * waste * cap * 0.1 + 20.0 * unusable * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins as stream advances.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * w_late;

    // New-bin candidate: make empty bins moderately attractive only when
    // this bin would leave a large unusable remainder late in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * w_late * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual % quarter) as f64;

    // Reward post_residuals near 0 (perfect fit) and near quarter boundaries
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score += class * 0.15; // penalize awkward remainders within a quarter
        if post_residual < 10 {
            score += 40.0; // dead space too small for any item (min size 1..100: still risky)
        }
    }

    // Lookahead: if next item fits in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 + slack * 0.3;
    } else if next_item_size > 0 {
        // next item won't fit: residual becomes waste; penalize proportionally
        score += (post_residual as f64) * 0.2;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if item is large or current residuals fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let bonus = 20.0 + 50.0 * fragmentation * (1.0 - progress);
        if item_size >= 50 {
            score -= bonus;
        } else {
            score += bonus * 0.5;
        }
    }

    // Prefer bins with residual close to item size (tight fit reward)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Slight preference for fuller bins among many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Integer division threshold: reward post_residual divisible into halves
    if post_residual % (bin_capacity / 2) == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to bin residual (high fill fraction).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer filling bins with larger residuals less
    // when the mean residual is already low (consolidate).
    if (post_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post residual is too small for the next item (dead space for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no
    // open bin offers a good fit (large dead space otherwise).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0 + open_bins_count as f64 * 0.5;
        // If the only fitting bin is this new one, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match with the lookahead item: strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Leftover still fits next item; reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover cannot fit next item: penalize dead space.
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 10.0;
    }

    // Reward placements that push residual toward unusable-but-small zones
    // (small residuals are easier to fill later with small items).
    if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: placing into a bin tighter than average
    // is good (keeps big residuals available for big future items).
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if (post_residual as f64) < mean {
        score -= 0.5 * (mean - post_residual as f64);
    } else {
        score += 0.5 * (post_residual as f64 - mean);
    }

    // New-bin candidate: only attractive when it truly beats reusing space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins are open, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // partial reward proportional to how well next item nests
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += 5.0 * (next_item_size as f64) / (post_residual as f64);
        }
    }

    // Time horizon: early in stream, be more conservative (penalize small residuals less);
    // late in stream, squeeze bins harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Global residual state: if mean residual is high, prefer filling existing bins
    // rather than opening new ones; if mean residual is low, allow new bins more freely
    let mean_gap = (mean_residual - post_residual as f64) / (bin_capacity as f64);
    score += 10.0 * mean_gap;

    // Discourage spreading across many open bins when this bin is already fairly full
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when existing bins would leave large waste
    if bin_residual == bin_capacity {
        score += 20.0;
        // late in the stream, new bins are cheaper (fewer future items to consolidate)
        score -= 15.0 * progress;
    }

    // Slight bonus for many open bins: consolidate rather than open more
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post). Late: tolerate larger post_residual
    // slightly less to avoid dead space accumulation.
    let poly = post_norm * post_norm * (1.0 - progress) * 120.0
             + post_norm * progress * 60.0;
    score += poly;

    // Reward near-perfect fits with a smooth cubic term.
    let fit_quality = 1.0 - post_norm;
    score -= fit_quality * fit_quality * fit_quality * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - post_norm);
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // with the penalty easing as the stream progresses.
    score += is_new * (35.0 - 20.0 * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = (post - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack);
    }

    // Discourage spreading when many bins are open relative to progress.
    score += open_bins_count as f64 * 0.5 * progress;

    // Mean residual alignment: prefer bins close to the mean residual.
    let dev = (post - mean_residual).abs() / cap;
    score += dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space (integer division into capacity bands)
    let cap = bin_capacity as f64;
    let residual_class = post_residual / 10; // 0..=10 harmonic classes of leftover space

    // Reward tight fits: small post_residual is good, but penalize "dead" classes
    // that are too small for the minimum item (1..=100 range, min item 1).
    if post_residual > 0 && post_residual < 10 {
        // Dead space: leftover below the smallest useful band
        score += 15.0;
    }

    // Reward bins whose leftover lands in a harmonic class divisible by common sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 12.0; // near-perfect chain fit
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: leftover likely wasted
        score += (post_residual as f64) * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, plus pressure to reuse bins over time
        score += 30.0 + 40.0 * progress;
        // If the current item is large relative to capacity, opening a fresh bin is fine
        if item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (keeping large spaces for big items)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Non-linear coupling: penalize leaving exactly awkward mid-band leftovers
    if residual_class == 1 || residual_class == 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to capacity.
    score -= 25.0 * (item_size as f64 / bin_capacity as f64);

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: with many open bins, prefer filling
    // existing ones (penalize new-bin candidate implicitly via open count).
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when it avoids creating
    // dead space that existing bins would cause.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: zero dead space initially.
        score -= 20.0;
        // But if an existing bin would fit reasonably well (post_residual
        // large enough to be reusable), discourage opening a new bin.
        if post_residual >= 20 && bin_residual == bin_capacity {
            score += 35.0;
        }
        // Late in the stream, closing out existing bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If next item cannot fit in the post residual but this bin could have
    // held it, slightly penalize to preserve room.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: perfect-fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // chained fit: penalize leftover after two placements
            let chained_left = post_residual - next_item_size;
            score += chained_left as f64 * 0.6;
            score -= 15.0; // small reward for being chainable at all
        } else {
            // next item can't follow; dead space risk grows
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Penalize large post_residual (wasted capacity) superlinearly
    score += (post_residual as f64).powi(2) * 0.01;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral baseline, slightly worse than a decent fit
    if bin_residual == bin_capacity {
        score += 40.0;
        // open a new bin early in the stream to build flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // but if next item is huge, a fresh bin is valuable
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Mild penalty for opening bins when many are already open
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is already favored by base).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical items.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 1.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into this bin's post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Mild bias toward mean residual alignment: pick bins near the mean to keep balance,
    // but only early in the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - t);

    // Late in the stream, be more conservative about opening new bins:
    // penalize the empty new-bin candidate more as t grows.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * t;
    } else {
        score -= 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; late, penalize dead space quadratically.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * (pr * pr) / cap;

    // Reward tight fits via smooth sigmoid-like term of fill ratio.
    let fill = 1.0 - pr / cap;
    score -= 6.0 * fill * fill * fill;

    // Penalize bins whose residual becomes awkwardly small but nonzero,
    // with a smooth bump centered at mid-range residuals.
    let x = pr / cap;
    score += 4.0 * (4.0 * x * (1.0 - x) - 0.5).abs();

    // Last-chance bonus: smooth exponential reward when few fitting bins.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 5.0 * scarcity * (1.0 - progress);

    // Lookahead: reward if next item fits smoothly in post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mild pressure toward consolidating bins as stream progresses.
    score += 0.02 * (open_bins_count as f64) * progress;

    // Diverge slightly from mean residual to spread loads smoothly.
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: smooth penalty scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "dead zone" (too small for typical items) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Dead-space penalty: leftover in (0,10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - frac);
    }

    // Harmonic bucket: quantize post_residual into classes of size 10.
    let class = post_residual / 10;
    // Classes that exactly match common small-item sizes (10,20,...) are good.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += (class as f64) * 0.8;
    }

    // Integer-division coupling with next item: does the next item fit
    // exactly in the post residual? Reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // Reward small gaps (near-exact fits), penalize large dead gaps.
            score -= 12.0 * (1.0 - gap as f64 / cap);
            if gap < 10 {
                score += 18.0; // creates new dead space
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score += 15.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it
    // only wins when open bins would waste a lot.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.25;
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Congestion coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins.
    if open_bins_count > 2 {
        score += (open_bins_count as f64).ln() * (mean_residual - pr) * 0.05;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Modulo-3 harmonic tiebreak on item class vs residual class.
    if (item_size % 10) == (post_residual % 10) && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual tightly matches the item (low slack ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Penalize wasting a large residual on a small item (dead-space creation).
    if item_size < bin_residual / 2 {
        score += (bin_residual - item_size) as f64 * 0.4;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins,
    // penalize opening yet another one.
    score += open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good existing option.
        let scarcity = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        let big_next = if next_item_size >= bin_residual as u32 && next_item_size > 0 { 15.0 } else { 0.0 };
        score -= scarcity + big_next;
        score += 5.0; // mild default preference for reusing bins
    }

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / 100.0);
    }

    // Late in the stream, tighten up: avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual - post_residual as f64).max(0.0) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when item exactly fills the bin
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable gaps)
        let pr = post_residual as f64;
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits: mild bonus scaled by how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a gap smaller than next item
            let gap_waste = (post_residual as f64).min(next_item_size as f64);
            score += 0.5 * gap_waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(1.0);
        score += 200.0 - 100.0 * progress - 20.0 * crowd.min(5.0);
        // still allow new bin if lookahead suggests a great follow-up fit
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: small post_residual that is still unusable is fine,
    // but moderate leftover space is wasted unless the next item fits it.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // Lookahead bonus: this placement enables the next item here.
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Next item cannot use the leftover; penalize stranded space.
            score += 0.25 * (post_residual as f64).powf(1.3);
        }
    } else {
        // Last item: purely minimize post_residual.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and residual is far above mean
    // (prefer bins closer to the average fill to balance closure).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight time-horizon coupling: early in the stream, be more conservative
    // about leaving awkward gaps; late in the stream, prioritize closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.08 * post_residual as f64;
    score -= progress * 2.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; reduced when item is large
        // (a large item pairs well with a fresh bin).
        score = (bin_capacity as f64) * 0.9 - 0.4 * (item_size as f64);
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good existing home; new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Non-linear reward for tight fits, modulated by stream progress:
    // normalized post residual raised to a power that grows with progress.
    let norm_post = post / cap;
    let tightness_reward = -40.0 * norm_post.powf(1.0 + 2.0 * progress) * (1.0 - norm_post);
    score += tightness_reward;

    // Smooth quadratic coupling between post residual and mean residual:
    // penalize leaving gaps larger than the average gap (wasted space).
    let gap_diff = post - mean_residual;
    score += 0.15 * gap_diff * gap_diff / cap;

    // Penalize dead space that can't fit the next item (lookahead), smoothly scaled.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let unusable = (nxt - post) / cap;
            score += 30.0 * unusable * (1.0 + progress);
        } else {
            // Reward bins that can still host the next item, with saturation.
            let fit = post / (post + nxt);
            score -= 10.0 * fit * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin early,
    // more acceptable late in the stream when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 55.0 + 40.0 * (1.0 - progress) - 20.0 * fragmentation;
    }

    // Small entropy-like regularizer on open bins count.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiple of a small quantum) are rewarded.
    let quantum: u32 = 10;
    let residue_class = post_residual % quantum;
    if residue_class == 0 {
        score -= 6.0; // clean leftover, likely reusable by 10-multiple items
    } else if residue_class <= 3 {
        score += 4.0; // sliver dead space penalty
    }

    // Integer-division tier of post_residual: big leftover chunks are good.
    let tier = post_residual / (bin_capacity / 4);
    score -= tier as f64 * 3.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 12.0; // dead space below minimum item size
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic match: next item is a divisor-like fit (post % next == 0)
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer keeping it closed when a decent fit exists.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 18.0 + pressure * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 6.0; // reserve fresh bin for pairing current+next
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (mean_residual / bin_capacity as f64);

    // Penalize bins far from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual < 10 cannot fit any item).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Dead space that cannot fit the lookahead item is also bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) with a bonus.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Open bins pressure: with many open bins, prefer reusing rather than opening new.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // If mean residual is large, prefer bins with residual close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Slight preference for opening new bins early in the stream is discouraged;
    // make new-bin candidate less attractive as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core waste: squared residual discourages dead space super-linearly.
    score += (post_residual as f64).powi(2) / 200.0;

    // 2-step lookahead: reward residuals that exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // tight-but-fitting
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(80.0);
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += post_residual as f64 * 0.5;
    }

    // Exact fill of the bin is always excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: only attractive when this bin would be left
    // with unusable tiny residual AND open bins are already numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let unusable = post_residual > 0 && post_residual < 10;
        let crowded = open_bins_count as f64 > mean_residual / 5.0;
        if unusable && (crowded || progress < 0.2) {
            score -= 20.0; // opening fresh is better than fragmenting
        } else {
            score += 45.0; // prefer existing bins by default
        }
    }

    // Mild normalization relative to mean residual: prefer bins below-mean
    // residual (tighter bins) to keep loose bins available for big items.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, especially near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Penalize dead space relative to capacity fraction.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can also land here: good chaining
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize if we waste a large residual
            score += 10.0 * dead_frac;
            // If next item is large and this bin's residual is small anyway, mild bonus
            if next_item_size > bin_residual {
                score -= 8.0;
            }
        }
    }

    // Time horizon: early in the stream, be more liberal about opening new bins
    // (keep residuals flexible); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (60.0 - 50.0 * progress);

    // Many open bins with high mean residual: discourage opening yet another bin.
    if new_bin > 0.0 && open_bins_count > 0 {
        score += (mean_residual / bin_capacity as f64) * 30.0 * (open_bins_count as f64).ln();
    }

    // Prefer bins whose residual is close to the mean (balanced packing) when many bins open.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 5.0 * dev / bin_capacity as f64;
    }

    // Mild penalty for placing large items into nearly-full bins leaving slivers.
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, large residuals are acceptable; late, they are dead space.
    let dead_weight = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += dead_weight * cap * 0.5;

    // Reward near-perfect fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 1.5 * (0.5 + 0.5 * progress);
    }

    // Lookahead: penalize if post_residual cannot fit next item but barely misses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 0.4 * nx * (1.0 - norm_pr);
        } else {
            let miss = (nx - pr) / cap;
            score += miss * cap * (0.8 + 1.2 * progress);
        }
    }

    // Coupling with mean residual: avoid bins far from the mean when open bins are many
    let mean_coupling = (pr - mean_residual) / cap;
    score += mean_coupling.abs() * cap * 0.1 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for opening new bins early when fits are poor
    if bin_residual == bin_capacity {
        score += cap * 0.6 * (1.0 - progress) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space that is a small
    // remainder modulo common item sizes is more likely to be reusable.
    let pr = post_residual;
    if pr > 0 {
        // Penalize dead space that cannot hold even the smallest plausible item.
        if pr < 10 {
            score += 40.0 * (10 - pr) as f64;
        }
        // Reward residuals that fall into "harmonic" classes: multiples of 10/20/25
        // align well with typical item sizes and future packing.
        let harmonic_bonus = if pr % 50 == 0 {
            18.0
        } else if pr % 25 == 0 {
            12.0
        } else if pr % 20 == 0 {
            10.0
        } else if pr % 10 == 0 {
            7.0
        } else if pr % 5 == 0 {
            3.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Quotient classes: integer division thresholds on post_residual.
        let q = pr / 10; // coarse capacity fraction class (0..10)
        score -= (q as f64) * 2.5;
        // Nonlinear coupling: quadratic penalty on mid-range waste.
        let frac = pr as f64 / bin_capacity as f64;
        score += 15.0 * frac * (1.0 - frac);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic alignment of next item with post residual.
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: mild penalty for stranding this bin.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Early in the stream, allow opening new bins more freely; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
        score += 10.0 * progress;
        // Don't open a new bin if a perfect-ish fit exists elsewhere.
        if post_residual == 0 {
            score += 60.0;
        }
    }

    // Tight fit reward: near-exact fills are always good.
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Modulo coupling between item and residual: item divides residual evenly.
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual that can still host a plausible future item (>= 10).
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post residual, this is a great chain placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // If next item leaves this bin stranded but another bin could take the next item,
    // mildly penalize consuming space needed for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += 2.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (tighter bins get priority for tight fits).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when it beats poor fits; make it moderately costly
    // but competitive when post_residual is large (fresh capacity for future items).
    if bin_residual == bin_capacity {
        score += 20.0 + 1.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is less useful.
        score += 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item barely fits nowhere else, allow the new bin to win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
