pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward filling bins nearly exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward small gaps.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // End of stream: strongly favor closing bins out.
        score -= 20.0;
    }

    // Prefer bins with residual below the mean (consolidate waste in fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Mild preference for more full bins as stream progresses (compaction pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0;

    // Avoid scattering across too many open bins early; encourage new-bin use
    // when open bins are fragmented but residual is large.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive for large items or when open bins are mostly full.
        let fullness_pressure = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score -= 12.0 + 30.0 * fullness_pressure + progress * 10.0;
        // Discard new bin for tiny items when many bins fit.
        if item_size < 25 && fitting_bins_count > 3 {
            score += 25.0;
        }
    }

    // Penalize leaving residual that is too small for any plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
