    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fit_norm * (1.0 - fit_norm) * 4.0);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighten tolerance for leftover space
    let progress_weight = 0.6 * progress * progress + 0.4 * progress;
    score += progress_weight * fit_norm * fit_norm * cap;

    // Penalize dead space that cannot plausibly fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        } else {
            // reward bins whose leftover still fits the next item
            score -= (1.0 - (nx / pr).min(1.0)) * 4.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: make it slightly unattractive unless residuals are poor
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap + 6.0 - 8.0 * avg_tightness * progress;
    }

    // Mild regularization against bin proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // quarter-capacity integer division (capacity fractions).
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class

    // Reward tight fits: class 0 (almost full) strongly preferred.
    score -= match class {
        0 => 40.0,
        1 => 25.0,
        2 => 12.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Dead-space penalty: leftover that no plausible item (1..100) can
    // pair with is worse than a moderate leftover. Penalize residuals
    // in the "awkward" band 1..=9 (too small for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post residual exactly,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot follow here: mild penalty scaled by waste
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is poor. Give it a baseline cost plus small discount
    // when many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.75
            + (open_bins_count as f64).sqrt() * 2.0
            - (mean_residual / bin_capacity as f64) * 10.0;
        // If nothing else fits well, new bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild progression scaling: early in the stream keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 100.0;
    }

    // Penalize leaving a gap that is too small for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item.
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Relative waste: compare post_residual to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item would leave dead space elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            score += 80.0; // an existing bin fits: keep using it
        } else {
            score += 20.0; // several options exist; prefer consolidation
        }
    }

    // Early stream: be slightly more willing to open bins (build diverse residuals);
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact match with next item (2-step lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here: mild reward proportional to tightness.
        let tight = (post_residual - next_item_size) as f64;
        score -= 20.0 - tight * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space the next item cannot use: penalize.
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Penalize tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.1;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.05;
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize moderately so it's chosen only
    // when open bins would leave large waste, but keep it competitive
    // when residuals are all poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, prefer closing out bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - 2.0 * tightness).abs();

    // Strongly penalize small unusable post-residuals (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Last chance: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: prefer leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Global pressure: when few bins fit the item, discourage wasting large-residual bins.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 10.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger post_residual);
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 20.0 * (1.0 - congestion);
        if open_bins_count > 0 {
            score += (mean_residual - post_residual as f64).abs() * 0.2;
        }
    } else {
        // Slight preference for bins deviating from the mean residual in a useful way.
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Discourage opening too many bins when mean residual is already large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 18.0 * norm_pr * norm_pr * (1.0 + p2) - 12.0 * norm_pr * p3;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: penalize leaving space that can't fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - (ni / cap)) * (0.4 + 0.6 * progress);
        } else {
            score += 9.0 * (ni - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.6 + 0.4 * progress);
    }

    // Penalize proliferation of open bins with high mean residual late in stream
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap) * progress;

    // New-bin candidate: smooth penalty encouraging reuse of open bins
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "dead space" classes.
    // Residues 1..9 (small unusable slivers) are heavily penalized; 0 is ideal.
    let r = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += (10.0 - r) * (10.0 - r) * 0.35; // quadratic penalty, worst near residue 9
    } else {
        score -= 40.0; // perfect closure bonus
    }

    // Integer-division thresholds: post_residual in (0,10] is a near-closed bin -> reward.
    if post_residual > 0 && post_residual <= 10 {
        score -= 25.0;
    }

    // Capacity fraction classes: how full the bin becomes.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.75 { score -= 15.0; }
    else if fill_frac >= 0.5 { score -= 6.0; }
    else if fill_frac < 0.25 { score += 8.0; } // wasteful low fill

    // Harmonic check on next_item_size: does post_residual hold next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // next item closes this bin exactly
        } else if post_residual >= next_item_size {
            let nr = (post_residual - next_item_size) % 10;
            score -= if nr == 0 { 12.0 } else { 4.0 };
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Empty new-bin candidate: penalize unless current bins are crowded or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
        score += 45.0 - crowded * 2.0 - (item_size as f64 - 50.0) * 0.2 - progress * 5.0;
        if mean_residual < item_size as f64 { score -= 30.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item (min item size 1..100 unknown, so treat tiny gaps < 10 as
    // unusable dead space) get an escalating penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Moderate dead space (10..=20): mild penalty, could still fit small items.
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward heavily; if next item cannot fit here, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate opening a new bin for better fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (balanced packing), penalize outliers.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: neutral-ish baseline so it only wins when open bins
    // are genuinely poor fits; penalize slightly when many bins already fit.
    if bin_residual == bin_capacity {
        score += 12.0 + fitting_bins_count as f64 * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits
    score -= 3.0 * (1.0 - (post_residual as f64) / cap);

    // 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 25.0; // exact chain fit
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - diff / cap); // next item fits here
        } else {
            score += 6.0 * (diff / cap); // next item won't fit, dead space risk
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 2.0 * ((post_residual as f64) - mean_residual) / cap;

    // Last fitting bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 5.0; // fresh bin useful for big next item? keep mild
        }
    }

    // Late-stream consolidation: avoid leaving many small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space that cannot host typical items: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * next_item_size as f64;
    }
    // Penalize bins whose post-residual just barely misses the next item (stranding).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage fragmenting across bins, favor tight fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64) * t;
    }

    // Global residual pressure: if mean residual is high, prefer bins below mean
    // (drain the fullest usable bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Late in stream: prefer filling existing bins rather than opening new ones.
    if t > 0.8 {
        score -= 10.0 * t;
    }

    // New empty bin candidate: baseline so it only wins when open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.3 * item_size as f64;
        // Opening a new bin is more attractive early (room to plan) and when
        // few bins exist; late with many bins, strongly discourage.
        score += 30.0 * (1.0 - t) - 25.0 * t;
        if open_bins_count > 6 {
            score += 20.0;
        }
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0; // big item into fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = norm_post * norm_post * 60.0 + norm_post * 20.0;

    // Non-linear coupling with stream progress: early on tolerate slack, later punish it
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits relative to current item size (smooth quadratic in fill ratio)
    let fill_ratio = item_size as f64 / cap;
    score -= 30.0 * fill_ratio * (1.0 - norm_post);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (post / nx).min(1.0);
        score -= 15.0 * usable * usable * (post / cap);
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 40.0 * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Mild penalty for spreading across many open bins (smooth in count)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    // (consolidate slack into few bins)
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: make empty bins less attractive unless residuals are all tiny
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create dead-space classes.
    let post = post_residual as i64;
    let residue = post % 10;

    // Penalize awkward residues (dead space that rarely fits future items 1..100 well).
    match residue {
        0 => score -= 25.0,                 // perfect fit, zero waste class
        1 | 2 | 3 => score += 12.0,         // nearly-full but unusable slivers
        4 | 5 | 6 => score += 4.0,          // moderate slivers
        7 | 8 | 9 => score += 8.0,
        _ => {}
    }

    // Integer-division threshold classes on post_residual (harmonic bands).
    let band = post / 25; // 0..4
    score += match band {
        0 => 18.0,   // post_residual < 25: bin nearly sealed, good if it was a big item
        1 => 6.0,
        2 => 0.0,
        _ => -6.0,   // large leftover: bin still very usable
    };

    // Lookahead: reward if next item fits exactly into the post residual (harmonic match).
    if next_item_size > 0 {
        if next_item_size as i64 == post {
            score -= 30.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 10.0 - (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    // or the item is large relative to typical residuals.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual - bin_residual as f64;
        // Penalize new bin normally; relax when fragmentation is high or item is huge.
        score += 55.0
            - fragmentation.clamp(0.0, 60.0)
            - (item_size as f64 - 50.0).max(0.0) * 0.4
            - progress * 10.0;
    } else {
        // Prefer filling bins tighter than the mean residual (reduce average waste).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Mild pressure against bin sprawl when many bins are open.
    score += open_bins_count as f64 * (if is_new_bin { 0.5 } else { -0.15 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small unusable gaps (1..10) are wasted capacity
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Moderately awkward residuals (10..25) get a mild penalty scaled by open bins pressure
    if post_residual >= 10 && post_residual < 25 {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 4.0 * open_bins_count as f64;
        // but if the new bin yields a residual that future small items can use, soften
        if post_residual <= 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // exact chained fit is excellent
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }
    // penalize leaving a gap just barely below next item
    else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Open bins pressure: mild preference to fill existing bins as count grows
    score += 0.3 * open_bins_count as f64;

    // Slight preference for tighter current fit (residual closeness)
    score += 0.1 * (bin_residual - item_size) as f64;

    // Stream progression: later in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Dead space: leftover smaller than the smallest possible next item is wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    if post_residual < 10 {
        score += 15.0; // unusable sliver under minimum item size
    }

    // Reward bins whose residual is already below average (tight bins get filled first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild preference for filling many-bin states down.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead * dead / bin_capacity as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for hoarding space.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidation onto tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = (open_bins_count as f64).ln() + 1.0;
    score -= 4.0 * crowd * (1.0 - progress) * tightness;

    // Mean residual context: if this bin is far below mean residual, it is a
    // "small hole" — prefer filling small holes with small items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev * (1.0 - tightness);

    // New-bin candidate handling: make fresh bins attractive only when the
    // item is large or existing fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if large_item > 0.6 || (fitting_bins_count == 1 && post_residual > 20) {
            score -= 8.0; // opening fresh is competitive for big items
        } else {
            score += 15.0 + 0.2 * open_bins_count as f64; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early on, leave room
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * prog_poly * pr_norm * (1.0 - pr_norm);

    // Penalize large dead space more strongly as the stream advances
    score += 20.0 * pr_norm * pr_norm * prog_poly;

    // Reward near-perfect fits (small post_residual) with a smooth bump
    let fit_bump = (-pr / 12.0).exp();
    score -= 15.0 * fit_bump * (0.5 + prog_poly);

    // Last-chance bin: reward strongly to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0 * (next_item_size as f64 / cap) * (1.0 - prog_poly * 0.5);
        } else {
            score += 5.0 * pr_norm;
        }
    }

    // Discourage scattering across too many bins when residuals are similar
    let mean_gap = (mean_residual - bin_residual as f64).abs() / cap;
    score += 4.0 * mean_gap * mean_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful (harmonic classes).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else {
        // Penalize post_residuals that fall into awkward modulo classes
        let r = post_residual % 10;
        if r == 1 || r == 9 {
            score += 6.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; slightly penalize leaving big residual anyway
            score += 0.05 * post_residual as f64;
        } else {
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 25.0;
            } else if rem2 < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it unattractive unless the item is huge
    // or this bin is a poor fit.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // opening a new bin is only good for very large items or many open bins
        score += 25.0 + 30.0 * (1.0 - frac);
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let fill = 1.0 - (bin_residual as f64 / cap);
    score -= 8.0 * fill;

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / cap);

    // Distance from mean residual: prefer bins below mean (fuller than average).
    score += 0.10 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: tight fit preferred (low post_residual)
    let mut score = post;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..=10)
    // are "dead space" — penalize heavily, with a cliff below size 10.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that the lookahead item can use (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for near-exact lookahead match
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is dead relative to the next item: penalize proportionally
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidation
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // New-bin candidate: only attractive when current fit is poor or bins are fragmented
    if bin_residual == bin_capacity {
        // neutral base for new bin; make it competitive with bad fits only
        score = cap * 0.5 + pressure * 4.0;
        if post_residual == 0 { /* unreachable, keep symmetric */ }
        // Discourage opening a new bin when a good fit exists elsewhere
        let fit_quality = item_size as f64 / cap;
        if fit_quality < 0.5 && fitting_bins_count > 1 {
            score += 15.0;
        }
        // Late in stream, prefer consolidation over new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for bins already below mean residual (balance residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain fit: strong reward
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space creation
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are flexible targets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening new bins when plenty of open bins could fit
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current item is large relative to capacity
        // or very few fitting bins exist
        let openness = open_bins_count as f64;
        score += 5.0 + openness * 0.5 - (item_size as f64 / bin_capacity as f64) * 10.0;
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    // Early stream: be slightly more conservative (keep bins flexible)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space that can never be filled (post_residual too small)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Last-chance bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 4.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0; // mild default penalty for opening new bin
        if fit_ratio < 0.35 && fitting_bins_count > 1 {
            score -= 12.0; // poor fit elsewhere => open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 8.0; // new bin can host the next item too
        }
    }

    // Time horizon: early in stream, be more willing to open new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= (1.0 - progress) * 6.0;
    } else {
        score += (1.0 - progress) * 2.0;
    }

    // Global state: many open bins with high mean residual -> consolidate
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Tighter packing demanded as stream progresses: penalize residual more aggressively
    score += 30.0 * norm_pr * norm_pr * (0.4 + 1.2 * progress);
    score -= 18.0 * norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 12.0 * norm_pr * p3 * (norm_pr - 0.5);

    // Reward near-perfect fits with smooth cubic falloff
    let fit_tightness = 1.0 - (pr / cap);
    score -= 25.0 * fit_tightness * fit_tightness * fit_tightness;

    // Last-chance bin: smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: penalize if next item cannot use this post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr - nxt).max(0.0);
        let waste = (nxt - pr).max(0.0) / cap;
        score += 10.0 * waste * (1.0 + progress);
        score -= 8.0 * (usable / cap) * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins below mean when many bins open
    let mr = mean_residual / cap;
    let open_f = open_bins_count as f64;
    score += 6.0 * (norm_pr - mr) * (1.0 - (1.0 / (1.0 + open_f)));

    // New-bin candidate: mild penalty so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins that leave small post_residual (tight fit).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    // since min item size is 10 -> penalize hard; classes of 10 are "reusable".
    let dead = (post_residual > 0 && post_residual < 10) as i32;
    if dead == 1 {
        score += 60.0;
    }
    // Modulo-10 class: residual exactly divisible by 10 is a "harmonic" state,
    // maximally reusable; reward it.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Integer-division thresholds: small post_residual classes are good.
    let cls = post_residual / 10; // 0..=10
    score -= (10 - cls.min(10)) as f64 * 0.5;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // this bin is a perfect two-step chain -> strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits in post_residual, mild reward; if next item would
    // leave the same dead-space trap, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            let next_post = post_residual - next_item_size;
            if next_post > 0 && next_post < 10 {
                score += 15.0;
            }
        } else if next_item_size > bin_residual {
            // next item can't fit here anyway; neutral.
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (residual == capacity): only attractive when current
    // placements are all poor fits. Make it costly by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large relative to capacity and mean residual is low,
        // opening a fresh bin may be wise.
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 55.0;
        }
        // Late in the stream with many open bins, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Slight preference for tighter bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
