    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Baseline: neutral residual; make new bin attractive when existing
        // residuals are fragmented or item is large
        score = (bin_capacity as f64) * 0.85
            - item_size as f64 * 0.5
            - progress * 20.0
            + (open_bins_count as f64) * 2.0
            + (mean_residual - bin_capacity as f64 * 0.5).abs() * 0.2;
        if item_size >= 60 {
            score -= 30.0; // large items start fresh bins more readily
        }
    }

    // Slight preference for consolidating into fewer bins early on
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling: penalize mid-range residuals, favor tight fits,
    // with strength growing over the stream.
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 60.0 * progress * poly;

    // Reward tight fits increasingly late in the stream.
    score -= 25.0 * progress * (1.0 - pr_norm);

    // Last-chance bonus: strongly prefer this bin when it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize opening new bins when open bins could fit, more so early on.
    if bin_residual == bin_capacity {
        score += 15.0 + 35.0 * (1.0 - progress);
        // But if next item is large and this bin would pair well, soften.
        if next_item_size as f64 > pr {
            score += 10.0 * progress;
        } else {
            score -= 8.0 * progress;
        }
    }

    // Waste-awareness via mean residual coupling.
    score += 0.15 * (mean_residual - pr).powi(2) / cap;

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * progress * (1.0 - gap / cap);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead-space classes".
    // Residues near 0 (tight fit) are excellent; residues 1..9 are increasingly wasteful.
    let pr = post_residual;
    let class = pr % 10;
    let class_penalty = match class {
        0 => -30.0,
        1 => 8.0,
        2 => 6.0,
        3 => 5.0,
        4 => 4.0,
        5 => 3.0,
        6 => 2.0,
        7 => 1.0,
        8 => 0.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: post_residual buckets via capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= quarter / 2 {
        score -= 12.0;
    } else if pr <= quarter {
        score -= 4.0;
    } else if pr >= half {
        score += 10.0; // large leftover waste in an existing bin
    }

    // Coupling with lookahead: if next item can exactly fill the post residual,
    // strongly reward this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // next item fits: how harmonically does it divide the residual?
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 15.0;
            } else {
                score += (npr % 10) as f64 * 1.5;
            }
        } else {
            // next item cannot use this residual: residual likely dead space
            score += (next_item_size - pr).min(20) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is huge relative to
    // capacity or existing residuals are poor (mean residual already large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // reward new bin when item is big and open bins are fragmented
        let new_bin_bonus = 55.0 - 40.0 * item_frac - 30.0 * mean_frac - 10.0 * (1.0 - progress);
        score += new_bin_bonus;
        // opening a bin for a small item is wasteful
        if item_size <= quarter {
            score += 25.0;
        }
    }

    // Mild pressure against accumulating many open bins with slack.
    score += 0.05 * open_bins_count as f64;
    score += 0.15 * ((mean_residual - post_residual as f64).abs());

    // Small tie-break toward tighter fits.
    score += 0.1 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score += (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: gaps too small for any item (min size 1..100 unknown,
    // assume items >= 10) are dead space; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Small-but-usable residual: mild penalty to prefer leaving room for medium items.
    if post_residual >= 10 && post_residual < 30 {
        score += 0.5 * post_residual as f64;
    }

    // Large residual left behind: mild reward (bin stays flexible).
    if post_residual >= 60 {
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= 0.05 * pressure;
    } else {
        // New-bin candidate: only attractive when current bins are crowded or fit is bad.
        score += 0.1 * pressure;
        if post_residual as f64 > mean_residual {
            score += 20.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 80.0;
    }
    // If next item would be blocked by this placement, penalize slightly.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));
    }

    // 2-step lookahead: perfect chaining (next item exactly fills post_residual).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // Next item fits with a small leftover -> good chain.
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize large dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Prefer bins tighter than average (leave big residuals for big future items).
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it available unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        // Neutral baseline; exact fits elsewhere already dominate.
        score += 40.0;
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * (1.0 - progress);
    }

    // Slight preference for using more bins when many are open with slack.
    if open_bins_count > 0 {
        score -= 0.05 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space: residual too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to waste
            score += 3.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into bins with small residual
    // to close them out mentally; few open bins: be more permissive.
    let congestion = (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);
    score += congestion * (post_residual as f64) * 0.5;

    // Mean residual coupling: if this bin is far below mean residual (wasteful bin),
    // prefer filling it; if above mean, mild penalty.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Time horizon: late in the stream, be greedier (tight fits matter more,
    // avoid spreading across bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Base penalty that shrinks when open bins are congested
    // or the item is large.
    if bin_residual == bin_capacity {
        let mut penalty = 18.0;
        // If item is large relative to capacity, opening fresh is more acceptable.
        penalty -= 10.0 * ((item_size as f64) / (bin_capacity as f64));
        // If open bins are mostly full (low mean residual), opening is fine.
        penalty -= 10.0 * (1.0 - (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0));
        // If many bins compete for this item, prefer one of them.
        penalty += 2.0 * ((fitting_bins_count as f64).min(5.0));
        // Early stream: opening bins is cheaper; late: avoid it.
        penalty += 6.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward tight fits (low post residual), with non-linear polynomial coupling
    let mut score = x * (1.0 + 2.0 * x * x);

    // Smooth interaction: tight fits matter more as stream progresses
    score -= (1.0 - x) * (1.0 - x) * progress * 6.0;

    // Penalize post residual that is small but unusable (dead space) — smooth polynomial
    let dead = (x * (1.0 - x)).max(0.0); // peaks mid-range
    score -= dead * 3.0;

    // Lookahead coupling: if next item fits exactly into post residual, reward strongly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs() / cap;
        score -= (1.0 - gap.min(1.0)) * (1.0 - gap.min(1.0)) * 8.0;
        // penalize leaving residual slightly above next item (awkward fit)
        if pr > ni {
            let slack = (pr - ni) / cap;
            score += slack * slack * 10.0;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Mean residual coupling: prefer bins deviating from mean to balance residuals
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * 2.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize unless item is large relative to capacity or stream is early
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 4.0 - big * 5.0 - progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills (0), near-perfect (<=5),
    // and dead-space bands via modulo arithmetic
    if post_residual == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0; // residual divisible into harmonic classes of 10
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        score += (post_residual % 5) as f64 * 1.5; // odd remainders are dead space
    }

    // Penalize large unusable residuals: dead space threshold via integer division
    let dead_class = post_residual / 20; // 0..=4 harmonic dead-space class
    score += dead_class as f64 * 8.0;

    // Last-chance bin: strong reward, avoid opening new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual - next_item_size;
        score -= 20.0 - (chain as f64) * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; residual becomes dead space unless small
        if post_residual > 30 {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score = (bin_capacity - post_residual) as f64 + desperation;
        // discourage opening new bin when mean residual across open bins is large
        score += mean_residual * 0.6;
        // discourage new bin late in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference to consolidate when many bins are open
    score -= (open_bins_count.min(20)) as f64 * 0.3;

    // Small tie-break toward tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1, but practically tiny gaps) are waste.
    if post_residual > 0 {
        // unusable-gap penalty: quadratic blowup for very small residuals
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 2.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to item size (relative waste)
    let rel_waste = post_residual as f64 / bin_capacity as f64;
    score += rel_waste * 20.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless the
    // current item leaves a good residual for the lookahead item or open bins
    // are very tight.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5;
        // open new bin if lookahead fits nicely in a fresh bin and no open bin fits well
        if next_item_size > 0 && next_item_size <= bin_capacity {
            if (bin_capacity - next_item_size) <= item_size {
                score -= 10.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // favor filling existing bins (lower score for existing bins).
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.5;
        // prefer bins tighter than the mean residual (better consolidation)
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Lookahead coupling: reward residual that exactly accommodates next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 5 {
            score -= 12.0;
        }
    }

    // Progress term: late in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable bin: reward proportionally to how snugly the next item fits too.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 25.0 - chain_tightness.min(25.0);
        } else {
            // Post residual becomes dead space relative to the lookahead item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Last-chance bin: strong penalty for opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless it enables a clearly better 2-step chain.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference for bins with residuals above the mean (keep small slivers for small items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness: reward small post_residual non-linearly.
    let tight = (post_residual as f64 / bin_capacity as f64).powf(1.7);
    score += 60.0 * tight;

    // Reward filling the bin well relative to what the item takes.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 45.0;
        } else {
            score -= 18.0 * (1.0 - diff as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item would be stranded by this placement.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 12.0;
    }

    // Global state coupling: when many bins are open, prefer consolidation
    // into existing bins (avoid bin proliferation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 3.0 * open_pressure;

    // Prefer bins whose residual deviates from mean residual in a useful way:
    // placing into a bin with residual below mean helps level residuals.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make empty bin attractive only when the
    // item is large relative to capacity or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = fill_ratio < 0.5;
        let late_stream = progress > 0.5;
        if (large_item > 0.6 || (poor_fit && late_stream)) && open_bins_count > 0 {
            score -= 15.0 + 20.0 * large_item;
        } else {
            // Default: discourage opening new bins when existing bins fit.
            score += 45.0 + 10.0 * open_pressure;
        }
    }

    // Mild time-horizon modulation: earlier in the stream, be more picky
    // about tight fits (future items may use residual better).
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, residual waste matters more (no future to amortize it)
    let coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * norm_pr;
    score *= coupling;

    // Last-chance bonus: strongly reward the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else {
        // mild penalty when many bins compete (waste a scarce residual elsewhere)
        score += 2.0 * ((fitting_bins_count as f64).ln() + 1.0) * norm_pr * (0.5 + progress);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // penalize leaving a residual that wastes space relative to the next item
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.15 * gap * (0.5 + progress);
        }
    }

    // Deviation from mean residual: prefer bins whose leftover deviates
    // smoothly from the average (keeps a diverse residual portfolio)
    let dev = pr - mean_residual;
    score += 0.1 * dev * dev / cap;

    // New-bin candidate: opening a bin early is cheap, late is expensive
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 1.2 * progress * progress) - 20.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            // never open a new bin when an existing bin is the last resort
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it aligns with typical item sizes (1..100 unknown dist)
    // Residuals divisible by small classes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is ideal
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 6.0; }
        if pr % 50 == 0 { bonus += 8.0; }
        // dead-space penalty grows for small unusable residuals
        if pr < 10 {
            score += 30.0; // nearly unusable sliver
        } else if pr < 20 {
            score += 12.0;
        }
        score -= bonus;

        // Harmonic pairing: can next item exactly divide the post residual?
        if next_item_size > 0 && pr >= next_item_size {
            if pr % next_item_size == 0 {
                score -= 18.0;
            } else {
                let q = pr / next_item_size;
                if q >= 1 && pr - q * next_item_size < 10 {
                    score -= 9.0; // near-exact second fit
                }
            }
        }
        if next_item_size > 0 && next_item_size > pr {
            score += 6.0; // this bin can't help the lookahead item
        }
    }

    // Tightness reward: fraction of bin consumed
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Many open bins: favor closing bins out (low post residual) over spreading
    if open_bins_count > 4 {
        score += 0.35 * (open_bins_count as f64);
        score -= (bin_capacity - post_residual) as f64 * 0.15;
    }

    // New-bin candidate logic: only attractive early in the stream or when residual is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = pr > 0 && pr < 15;
        if progress < 0.15 || bad_fit || mean_residual < 25.0 {
            score -= 20.0;
        } else {
            score += 45.0; // penalize opening new bins mid-stream with decent fits available
        }
    }

    // Mean residual coupling: prefer bins near the mean (keeps residuals homogeneous)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Soft penalty: small-ish gaps that likely waste space relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.10 {
        score += 25.0 * (0.10 - frac) / 0.10;
    }

    // Reward near-perfect fits strongly (post_residual close to zero is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading across many open bins; encourage
    // consolidation by penalizing placements that keep bin count high.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    // (chaining placements in the same bin is efficient).
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0;
    }
    // If next item would leave a dead gap after being placed here, slight penalty.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer opening a new bin when existing bins are badly fragmented
    // (high mean residual dispersion) or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But reduce the cost if current bins are crowded (mean residual low relative to item)
        // or if this item is large and fits nowhere tightly.
        let mean_r = mean_residual;
        if mean_r < item_size as f64 * 1.2 {
            score -= 30.0; // existing bins too full; new bin is reasonable
        }
        if item_size > 70 {
            score -= 10.0; // large items benefit from fresh space
        }
        // Late in the stream, slightly cheaper to open bins (less future to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Mild preference for filling bins that are already mostly full (tight packing).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-step match
        } else if post_residual > next_item_size && post_residual - next_item_size <= 15 {
            score -= 10.0; // near-perfect chain
        }
        // Penalize if post_residual is large but next item cannot use it well
        if post_residual > 40 && next_item_size < post_residual - 30 {
            score += 8.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 6.0; // creating an outlier large residual
    } else if (post_residual as f64 - mean_residual).abs() <= 10.0 {
        score -= 3.0; // keeping residuals homogeneous
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer open bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits well (post_residual large relative to item), allow new bin
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}
